PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE project (
    topic       TEXT PRIMARY KEY CHECK (topic IN ('name','description','done',
                'spec_definition_progress','pouring_state','blocks_division','session_role')),
    information TEXT NOT NULL,
    updated_at  TEXT NOT NULL DEFAULT (date('now', 'localtime')) CHECK (date(updated_at) IS updated_at),
    CHECK (topic NOT IN ('name','description') OR information = TRIM(information)),
    CHECK (topic <> 'done' OR information IN ('true','false')),
    CHECK (topic <> 'spec_definition_progress' OR information IN ('not_started','in_progress','done')),
    CHECK (topic <> 'pouring_state' OR information IN ('not_started','in_progress','spec_edited','done')),
    CHECK (topic <> 'blocks_division' OR information IN ('not_started','in_progress','done')),
    CHECK (topic <> 'session_role' OR information IN ('single','principal'))
);
INSERT INTO project VALUES('name','RAG-against-the-machine-','2026-10-26');
INSERT INTO project VALUES('description','A RAG system that answers questions about the vLLM codebase (vllm-0.10.1): it chunks .py, .md and .txt files, indexes them with BM25 plus semantic embeddings in a versioned store, retrieves the top-k sources and generates grounded answers with Qwen3-0.6B, from a Fire CLI or a local FastAPI server. Built for 42 evaluators and the moulinette (recall@5 >= 80 % docs, >= 50 % code; index <= 5 min; 200 questions <= 90 s), with all five bonuses: semantic index, hybrid RRF, incremental indexing, caching and local HTTP API.','2026-10-31');
INSERT INTO project VALUES('done','true','2026-11-05');
INSERT INTO project VALUES('spec_definition_progress','done','2026-11-05');
INSERT INTO project VALUES('pouring_state','done','2026-11-05');
INSERT INTO project VALUES('blocks_division','not_started','2026-10-26');
INSERT INTO project VALUES('session_role','single','2026-11-06');
CREATE TABLE spec (
    topic       TEXT PRIMARY KEY CHECK (topic IN ('instructions','spec','done')),
    information TEXT NOT NULL,
    updated_at  TEXT NOT NULL DEFAULT (date('now', 'localtime')) CHECK (date(updated_at) IS updated_at),
    CHECK (topic <> 'done' OR information IN ('true','false')),
    CHECK (topic <> 'instructions' OR TRIM(information) <> '')
);
INSERT INTO spec VALUES('instructions',unistr('MANDATORY: every rule in this text is unbreakable. Forbidden to skip\u000aone, accept something without meeting it or advance without the approval it\u000aasks for.\u000a\u000aThe spec is the blueprint of the project. It must have content in each point:\u000a  1. What it is: detailed description of the product.\u000a  2. Target client and/or user.\u000a  3. Product goal: what it exists for and what problem it solves. It must be measurable.\u000a  4. What it does: functionalities and, for each one, its edge cases and what happens when it fails.\u000a  5. Technologies: languages, tools, environment and deployment environment.\u000a  6. Scope: in which direction it is going to scale.\u000a  7. Architectural methods that enable the scaling.\u000a  8. Limits: what it does not do and what must not be used.\u000a\u000aOrigin:\u000a  User''s PDF → pour its full contents into the spec row, in the format\u000a               below, and check that it covers the 8 points (in point 4, also\u000a               the edge cases and failures of each functionality); whatever is\u000a               missing, define it with the user.\u000a  No PDF     → define it with the user, point by point. In each point do not\u000a               just ask and advance: ask, propose and debate until reaching a\u000a               high level of performance, robustness and security. Keep\u000a               writing it in the spec row.\u000a\u000aFormat: the text of the spec row is written in markdown and divided into those 8\u000apoints, in that order, each one as a section. This also applies to content that\u000acomes from a PDF: it is poured in that format and in that order. Content that does\u000anot fit exactly is placed in the closest section; if it fits in none, tell the\u000auser and decide together on a new section.\u000a\u000aCoherence:\u000a  Everything you write must agree with itself and serve the end of the project\u000a  (the measurable goal). Actively look for and point out to the user, before\u000a  continuing:\u000a    1. Inconsistencies: two parts that contradict each other or do not fit (a\u000a       functionality against a limit, a goal against a constraint, a technology\u000a       that does not support what is asked).\u000a    2. Gaps: something the end requires and nobody covers, or something defined\u000a       without what it needs to work.\u000a    3. Weaknesses and failures: fragile points, cases that break, untreated\u000a       security or scaling risks.\u000a    4. Lack of engineering or efficiency: solutions that comply but are not\u000a       robust, efficient or sustainable compared to a better alternative.\u000a  Do not accept something just because it does not clash with anything: the\u000a  criterion is that the result is robust, well designed, efficient and meets the\u000a  end. Point out only what is real and probable in the context of the project and\u000a  its scaling, not improbable assumptions. Propose the fix; the user decides.\u000a  Apply it to the 8 points, among themselves and against the measurable goal,\u000a  before asking for the approval that sets spec.done = true.\u000a\u000aWhat is missing (no placeholders in the spec):\u000a  The spec row only holds what is real: content from the PDF or approved by\u000a  the user. Forbidden to write in it marks of what is missing ("PENDING",\u000a  "to be defined", "TBD"), drafts or examples of yours without approval.\u000a  Each thing still to define goes, at the moment you detect it, to the\u000a  pending table, one row per thing, starting with a verb and naming the\u000a  point; examples you propose go inside it as "proposed, not approved":\u000a    INSERT INTO pending (description)\u000a    VALUES (''Define in spec point <n>: <what> (proposed, not approved: <examples>)'');\u000a  When the user decides it and you write it in the spec, mark it:\u000a    UPDATE pending SET done = 1 WHERE id = <id>;\u000a  Before asking for the approval that sets spec.done = true, the open\u000a  pending items of the spec must be none:\u000a    SELECT id, description FROM pending\u000a    WHERE done = 0 AND description LIKE ''Define in spec point%'';\u000a\u000aWrite and update the spec with:\u000a  UPDATE spec SET information = ''<spec text in markdown>'' WHERE topic = ''spec'';\u000aWhen writing in the spec row, spec_definition_progress changes to in_progress\u000aby itself.\u000aWhen the user approves the spec, run:\u000a  UPDATE spec SET information = ''true'' WHERE topic = ''done'';\u000aEditing the spec row reopens it (spec.done changes to false by itself).\u000a\u000aReopened after the pouring started (the pouring stays in progress until the\u000aspec is approved again):\u000a  When you edit the spec once pouring_state is in_progress or done, save at\u000a  that moment what changed, one row per spec point:\u000a    INSERT INTO pending (description)\u000a    VALUES (''Review changed spec point <n>: <what changed>'');\u000a  Review with the user ONLY those changes and what depends on them, never the\u000a  whole spec again. Before asking for the approval, check each poured row\u000a  (SELECT * FROM prohibitions; constraints; goals; descriptions; concepts)\u000a  against the changed points; a row that no longer matches: propose the fix,\u000a  the user decides (modify, remove or keep). If blocks are already built,\u000a  check also that what is built still matches the changed points (run its\u000a  tests) and save each mismatch in pending. Mark each of those pending done\u000a  when reviewed. When the user approves, run:\u000a    UPDATE spec SET information = ''true'' WHERE topic = ''done'';\u000a  and read: SELECT information FROM pouring WHERE topic = ''current'';\u000a  If it is end, the pouring was already complete and there is nothing to pour:\u000a  that same approval closes it too:\u000a    UPDATE pouring SET information = ''true'' WHERE topic = ''done'';\u000a  and you go back to where you were (row 1 takes you there; in the same session\u000a  do not repeat its ORIENT step). Any other value: row 1 takes you back to the\u000a  pouring, where it stopped.'),'2026-11-05');
INSERT INTO spec VALUES('spec',unistr('# Spec — RAG against the machine (source: en.subject.pdf v2.0)\u000a\u000a## 1. What it is\u000aA Retrieval-Augmented Generation (RAG) system that answers questions about a codebase (the provided vLLM repository, vllm-0.10.1).\u000aPipeline: Corpus (data/raw/vllm-0.10.1) → Chunking (.py code | .md Markdown | .txt plain text) → Index (BM25 lexical + semantic embeddings, versioned under data/processed) → Retrieve top-k sources → Augment (build context) → Generate (Qwen3-0.6B) → Answer (JSON). Retrieval quality is evaluated with recall@k (IoU > 0.05).\u000aFour RAG stages: Indexing (organise data to be searchable), Retrieving (match a question against the index and pull the most relevant snippets), Augmenting (filter snippets and place them in the model context window), Generating (read that context and produce the answer).\u000aOn top of the mandatory pipeline, all five bonuses of point 6 are built: a semantic vector index next to the lexical one, hybrid ranking of both, incremental indexing, caching and a local HTTP API.\u000a\u000a## 2. Target client / user\u000a1. Primary: 42 peer evaluators and the moulinette, who run it through the reference exam scripts and push it with odd inputs; questions are about the vLLM codebase (docs questions and code questions).\u000a2. Secondary: recruiters reviewing the project, mainly through the README and the repository (code quality, design decisions, performance analysis, example usage).\u000a\u000a## 3. Product goal (measurable)\u000aRetrieve the right evidence from a large codebase and make a small model answer faithfully from it.\u000a1. Recall@5 >= 80 % on docs questions and >= 50 % on code questions (reference datasets, official moulinette).\u000a2. Indexing the whole corpus: at most 5 minutes. Measured in the semantic index phase (user decision, 2026-10-29): the full index time on the CPU campus machine (lexical index + embeddings) on the whole corpus. If it exceeds 5 minutes, stop and decide with the user before continuing.\u000a3. Retrieval throughput: at most 90 seconds for 200 questions; the index must be queryable in milliseconds. Measured in the search_dataset phase with bm25 and again in the hybrid retrieval phase (each question also computes its embedding) (user decision, 2026-10-29). If it exceeds 90 seconds, stop and decide with the user before continuing.\u000a4. Answers: coherent, grounded in the retrieved sources (no major hallucination), on point. Not a strict pass/fail bar: grading prioritises retrieval quality, grounding and prompt strategy over perfect phrasing (Qwen3-0.6B has known reasoning limits).\u000a5. Never crash with an unhandled traceback (a crash during review = non-functional).\u000aRecall@k: for each question, the share of its correct sources found in the top-k results. A correct source counts as found when a result is in the same file (file_path compared verbatim) and overlaps its character range with IoU > 0.05 (strict, as in the subject diagram; user decision, 2026-10-31: to be confirmed with pending 11, evaluate against the moulinette on the same output).\u000a\u000a## 4. What it does (functionalities, edge cases, failures)\u000aCLI with Python Fire, invoked as `uv run python -m src <command> [options]` (options shown are the minimum; more may be added). tqdm progress bars for long operations. All input/output paths are CLI arguments, never hard-coded.\u000aOutput channels (every command): results go to stdout; every message, warning and error (e.g. "run index first", "results N/N") goes to stderr, so redirecting stdout (> file) captures only results and the user still sees the messages.\u000aEvery warning and error printed on stderr (e.g. "results N/N", skipped questions, fallbacks, sources left out of the context) is also recorded in the run log file, in every command, with no exception (user decision, 2026-10-28).\u000aRun log file: every command takes --log_dir (default: logs/ at the project root, git-ignored), a CLI argument as the subject requires. The folder and the file are created only when there is something to log; one file per run, in JSON Lines (one JSON object per line), and each event is appended as a new line without rewriting the file, so a run that dies only loses its last line. Each event has the fields type and error (provisional: they may change during implementation; user decision, 2026-10-28).\u000aRetrieval method (search, search_dataset, answer): BM25 by default; hybrid retrieval (bonus) only when requested with --method hybrid. If the semantic part fails (e.g. embedding model not downloaded, embeddings missing or unreadable), the command automatically falls back to BM25 and keeps running; the fallback is reported as a warning naming the reason and that bm25 is used, on stderr and in the run log file, and in search_dataset it is decided once per run so every question uses the same method. Hybrid fuses the lexical and semantic rankings with Reciprocal Rank Fusion (each chunk scores the sum of 1/(c + rank) over both rankings), with c = 100 unless measured recall@k shows that c = 60 is better (user decision, 2026-10-28). --method semantic (embeddings only) also exists; if it fails, it is a normal error: clear message on stderr and in the run log file, exit code != 0, no traceback (in search_dataset it is a run-level failure: no question is processed).\u000a\u000a### 4.1 index --max_chunk_size <int>\u000aIngests data/raw/ (files judged useful from the vLLM repo), splits each into chunks and persists the index under data/processed/.\u000aThree chunking strategies, one per indexed file type (the subject asks for at least two; user decision, 2026-10-29): Python code chunking (.py), Markdown chunking (.md, can use the # headings) and plain text chunking (.txt). The .txt files are not Markdown and differ among themselves (CMakeLists.txt build code, requirements/*.txt package lists, prompt and model lists in tests/ and benchmarks/), so the .txt chunker gets its own engineering, tuned on these real files in the chunking phase. max_chunk_size default 2000 characters, never above 2000 (the moulinette rejects any source longer than 2000 characters and a single over-long source invalidates the whole output); smaller is allowed, report its effect on recall@k.\u000aChunk size rule (measured in the chunking phase; user decision, 2026-10-29): 2000 is a ceiling, not a target. The effective chunk size (never above max_chunk_size) is chosen by measuring recall@5 with search_dataset + evaluate on both public datasets (docs and code) for at least 2000, 1500, 1000 and 500 characters, and also a structural split: one chunk per natural unit (a function or class in Python, a section in Markdown, the natural unit of each .txt kind, e.g. a CMake block or a requirements group, decided in the chunking phase), never merging small units to fill the limit (e.g. five 200-character functions give five chunks, not one of 1000), and a unit larger than max_chunk_size split further; the size with the highest sum of recall@5 on docs and code is kept, and every measured size with its recall@k goes to the README. Reasons to measure: a chunk much larger than a correct source can fail the IoU > 0.05 even when it contains it (e.g. a source of 80 characters inside a chunk of 2000 gives 0.04); correct sources of the public datasets have a median of 1154 characters (docs) and 878 (code); the embedding model reads at most 256 tokens per text (about 1000 characters of English, fewer for code). If no size meets the point 3 goals, stop and decide with the user.\u000aRetrieval method: at least one of TF-IDF or BM25 (others may be added on top). Hint: questions may paraphrase an idea or quote an identifier verbatim; what is kept at indexing time decides which can still be matched.\u000aExample output: "Ingestion complete! Indexed 13466 chunks under data/processed/".\u000aEdge cases / failures:\u000a1. max_chunk_size outside 1..2000 (e.g. 0, -5, 3000) → rejected: clear message ("max_chunk_size must be between 1 and 2000"), exit code != 0, nothing indexed, no traceback.\u000a2. data/raw missing or with no indexable file → clear message ("data/raw not found or empty"), exit code != 0, data/processed left untouched.\u000a3. Binary and non-useful files → not read: only a whitelist of extensions is indexed: .py (Python code chunking), .md (Markdown chunking) and .txt (plain text chunking). Reason (user decision, 2026-10-29): the 199 correct sources of the public datasets cite only .py (99), .md (97) and .txt (3, CMakeLists.txt), so these are taken as what is evaluated.\u000a4. Text that is not valid UTF-8 → file skipped with a warning (errors="replace" would shift character indexes). Files are read with newline="" so \\r\\n is not converted to \\n and character indexes match the raw file. Range check (measured in the indexing phase): run evaluate and the moulinette on the same search_dataset output; if both give the same recall@k, our character ranges agree with the moulinette; if not, check first the 4 corpus files (.py, .md, .txt) that contain \\r, and adapt the reader. If the cause is not found, stop and decide with the user.\u000a5. Empty files (e.g. empty __init__.py) → skipped silently, no [0:0] chunk.\u000a6. Ctrl+C during indexing → KeyboardInterrupt caught, clear message, no traceback.\u000a7. Interruption or write failure must never leave a half-written or mixed index: each index version (chunks + statistics + the content hash, sha256, of every indexed file, used by answer_dataset in 4.5 case 8) is written complete in its own subfolder of data/processed; it is verified (loads without error, chunk count consistent between both parts) and only then activated with a single os.replace of a small pointer file that names the current version (temporary pointer written in the same folder, so the replace is atomic). If verification fails, the pointer is not changed, the failed version is deleted and index exits with a clear error and exit code != 0 (no retry: the failure is most likely deterministic, e.g. disk full or a chunking bug). After the switch, the previous version is deleted.\u000a8. Ctrl+C while writing a new version → the KeyboardInterrupt handler deletes the half-written subfolder before exiting.\u000a9. Abrupt death (terminal closed, kill -9, power loss) runs no code and can leave an orphan subfolder → at startup, index deletes every version subfolder that is not the one named by the pointer.\u000a10. When index finishes, it prints on stderr: "if the API server is running, it will load <version> on its next request", with the real name of the new active version. index never calls the server itself (it may be off, and its --port is unknown to index).\u000aSemantic index and incremental indexing (bonus; user decision, 2026-10-29):\u000a11. Each index version stores, in its own subfolder: chunks, BM25 statistics, the embedding matrix (one vector per chunk), the content hash of every indexed file and the settings it was built with (max_chunk_size, embedding model). The verification of case 7 also checks that there are as many vectors as chunks.\u000a12. Incremental run: the hash of every whitelisted file is compared with the previous version. Unchanged file → its chunks and vectors are copied from the previous version (no chunking, no model). New or changed file → chunked and embedded. Deleted file → its chunks are not copied. BM25 statistics are always recomputed over all chunks (they depend on every chunk; no model involved).\u000a13. Full rebuild when max_chunk_size or the embedding model differs from the previous version (e.g. a reused 2000-character chunk would break --max_chunk_size 1000): nothing is reused.\u000a14. Previous version missing or unreadable (e.g. corrupt embedding file) → full rebuild, with a warning on stderr and in the run log file; never an error.\u000a15. Embedding model not available during index (not downloaded and no connection) → the lexical index (mandatory) is built anyway without the semantic part, with a warning on stderr and in the run log file; --method hybrid then falls back to bm25 by the rule of point 4.\u000a\u000a### 4.2 search <query> --k <int>\u000aReturns the top-k sources for a single query: each source is file_path + [first_character_index:last_character_index], at most 2000 characters wide. file_path must match the corpus path exactly (e.g. data/raw/vllm-0.10.1/docs/features/lora.md).\u000aEdge cases: empty query, nonsensical query, k=0, missing index → handled gracefully.\u000a1. No pointer file (index never run) → clear message "run index first", exit code != 0, no traceback.\u000a2. Empty query ("" or only whitespace) → rejected: clear message ("query must not be empty"), exit code != 0, no search is run, no traceback.\u000a3. Nonsensical query: no query token exists in the index vocabulary, so every chunk scores 0 and any top-k would be arbitrary → rejected: clear message ("no indexed term matches the query"), exit code != 0, no traceback. A query with at least one matching token (e.g. "asdkjh model") is searched normally.\u000a4. k = 0 → returns 0 sources (empty list), exit code 0, no scoring is run (the subject only requires k=0 to be handled gracefully).\u000a5. Negative k (e.g. -2) → rejected: clear message ("k must be >= 0"), exit code != 0, no search is run, no traceback.\u000a6. k greater than the number of chunks N of the active index (e.g. --k 999999 with 100 chunks) → not an error: k is capped to N, all N sources are returned ranked, with the message "results N/N" (e.g. "results 100/100") printed to stderr, so the user sees only N exist while stdout keeps only the sources; exit code 0, no traceback. N is read from the active index version, never hard-coded, since it changes with each index run and max_chunk_size.\u000a\u000a### 4.3 search_dataset --dataset_path <path> --k <int> --save_directory <dir>\u000aSearch over a whole dataset of questions read from JSON; writes a StudentSearchResults JSON file. save_directory always scoped by dataset (UnansweredQuestions or AnsweredQuestions), since public datasets share file names.\u000aEdge cases: missing files, malformed JSON, k=0 → handled gracefully.\u000a1. Run-level checks (same rules as 4.2 cases 1, 4, 5, 6), done once before any question is processed: no index or negative k → clear message on stderr, exit code != 0, no question is processed, no output file; k = 0 → every question gets 0 sources; k > N → k is capped to N for every question and "results N/N" is printed once on stderr.\u000a2. Question-level failures (empty question, nonsensical question as defined in 4.2 cases 2 and 3) → the question is skipped, never the whole dataset: it stays in the output with retrieved_sources: [] so every question_id of the dataset is present (the moulinette validates the output, and a missing id could invalidate the whole file) and it scores 0 in recall; the question_id and the reason are recorded in the run log file, and processing continues with the next question.\u000a3. --dataset_path missing or a folder → clear message, exit code != 0, no output file.\u000a4. Malformed JSON → clear message naming the line and column of the error, exit code != 0, no output file.\u000a5. Valid JSON that is not a RagDataset (e.g. missing rag_questions, wrong types) → summarised pydantic error, no traceback, exit code != 0, no output file.\u000a6. rag_questions empty → valid output with search_results: [], warning "0 questions" on stderr, exit code 0.\u000a7. Duplicated question_id → only the duplicated questions are skipped (recorded in the run log file with their ids) and the rest are processed. Provisional, tested in the search_dataset phase: run the moulinette by hand on an output where the duplicated questions were skipped; if it rejects it, stop and decide with the user how to adapt this case.\u000a8. --save_directory missing → created with its parent folders. Not writable, or an existing file → clear message before any search is run (so the search work is not lost at save time), exit code != 0.\u000a9. Output file already exists → overwritten; written to a temporary file in the same folder and activated with os.replace, so a half-written JSON never exists.\u000a10. Ctrl+C during the run → clear message, no traceback, no output file (a partial file would leave question ids without results).\u000a\u000a### 4.4 answer <query> --k <int>\u000aAnswers a single query with Qwen/Qwen3-0.6B using the retrieved context, passed within the model token budget.\u000aOutput: a MinimalAnswer JSON on stdout (the same model /answer returns).\u000aEdge cases / failures:\u000a1. Empty query, negative k, k greater than N → same rules as 4.2 (cases 2, 5, 6). When k is greater than N, all N sources are used and the run log file also records that only N were used because only N exist (e.g. k = 1000 with 10 chunks → 10 sources).\u000a2. Nonsensical query (no query token in the index vocabulary) → rejected as in 4.2 case 3: answering without context would make the model invent.\u000a3. k = 0 → rejected: clear message ("k must be >= 1 for answer"), exit code != 0, no traceback.\u000a4. Model not downloaded and no connection, or disk full while downloading it → clear message, exit code != 0, no traceback.\u000a5. Qwen3 thinking mode: both modes (with and without thinking) are compared during tests on answer quality and time, and the choice follows the measurements; it is not discarded beforehand, since the questions are moderately demanding. Any <think>...</think> block is always removed from the answer.\u000a6. Empty answer from the model → warning on stderr and in the run log file, answer: "" returned with its sources, exit code 0 (the retrieval did work).\u000a7. Ctrl+C during generation → clear message, no traceback.\u000a8. Hypothesis, tested only if needed (user decision, 2026-10-28): first measure whether any question of the datasets, with its sources, exceeds the model token budget. If some do, test splitting the sources into 2 (at most 3) prompts: each prompt carries a note saying that its answer is based only on sources n..m because the model context is small, the parts are generated one after another, and they are joined into a single answer that is returned.\u000a9. Context safety net (any k, whether or not case 8 is in use): sources enter the prompt in ranking order until the token budget is full; the rest are left out of the prompt but kept in retrieved_sources. A clear message on stderr and in the run log file says that only n/k sources were used to generate the answer because of the model context limit (e.g. "only 12/1000 sources were used to generate the answer (context limit)") (user decision, 2026-10-28).\u000a\u000a### 4.5 answer_dataset --student_search_results_path <path> --save_directory <dir>\u000aGenerates answers for a dataset from search results; writes a StudentSearchResultsAndAnswer JSON file (e.g. "Loaded 100 questions ... Processed 100 of 100 questions").\u000aIt never searches again: it reads the text of each source from the corpus (file_path + character range) and passes it to the model.\u000aEdge cases / failures:\u000a1. --student_search_results_path missing or a folder, malformed JSON, valid JSON that is not a StudentSearchResults → same rules as 4.3 cases 3, 4 and 5.\u000a2. search_results empty → same as 4.3 case 6.\u000a3. Duplicated question_id → same as 4.3 case 7 (provisional, same moulinette test).\u000a4. --save_directory, existing output file, Ctrl+C → same as 4.3 cases 8, 9 and 10.\u000a5. Empty answer from the model and context limit → same as 4.4 cases 6 and 9, applied per question.\u000a6. Model not downloaded and no connection, or disk full while downloading it → checked once before the first question: clear message, exit code != 0, no output file.\u000a7. Question with retrieved_sources: [] (e.g. skipped in search_dataset) or with no valid source left (case 8) → the model is not called (without context it would invent, as in 4.4 case 2); the question stays in the output with answer: "" and is recorded in the run log file. At the end of the run, a summary on stderr says how many questions have no answer and the exact path of the run log file (e.g. "3/100 questions have no answer (no valid sources); details in logs/<file>.jsonl"). The README states that answer: "" means: see the run log file.\u000a8. Invalid source (the input file comes from outside and may be outdated or edited by hand): (a) file_path not in the corpus, or character range outside the file or wider than 2000 characters; (b) the content hash of the cited file differs from the one stored in the active index version (the corpus changed since the last index, so the range may point to different text). The source text is left out of the prompt, but the source stays in retrieved_sources, so the output keeps matching the search results file the moulinette evaluated; a warning on stderr and in the run log file names the file and says to run index and search_dataset again. answer_dataset never re-indexes nor re-searches on its own (user decision, 2026-10-29). The question is answered with the remaining valid sources; if none is left → case 7.\u000a9. k of the output = k of the input file, copied as is (answer_dataset has no --k: it does not search).\u000a\u000a### 4.6 evaluate --student_search_results_path <path> --dataset_path <path>\u000aReports own recall@k against a ground-truth dataset, for own iteration. The official recall@k is computed by the provided moulinette; the solution must never import or call the moulinette.\u000aOutput: Recall@1/3/5/10 on stdout (the same values the moulinette reports), computed with the recall@k definition of point 3.\u000aEdge cases / failures:\u000a1. Either file missing or a folder, malformed JSON, or not the expected model (StudentSearchResults for --student_search_results_path, RagDataset for --dataset_path) → same rules as 4.3 cases 3, 4 and 5, for both files.\u000a2. --dataset_path is an UnansweredQuestions dataset (no correct sources) → recall cannot be computed: clear message ("dataset_path must be an AnsweredQuestions dataset"), exit code != 0.\u000a3. question_id mismatch between both files: (a) a question in the results but not in the dataset → ignored, with a warning on stderr and in the run log file; (b) a question in the dataset but not in the results → counts as recall 0 (it was not answered); (c) no question_id in common → clear message ("no common question_id", most likely the wrong dataset), exit code != 0.\u000a4. A dataset question with sources: [] → its recall is undefined (0/0): excluded from the average, with a warning on stderr and in the run log file.\u000a5. Only the Recall@N with N <= k of the results file are reported (e.g. k = 5 → @1, @3, @5); each missing one is explained on stderr (e.g. "recall@10 needs k >= 10 (file has k = 5)"), since computing it with fewer results would fake a measure that was not made.\u000a6. A source wider than 2000 characters in the results → recall is computed anyway, with a warning on stderr and in the run log file: "the moulinette would reject this file" (it invalidates the whole output, 4.1).\u000a\u000a### 4.7 Local HTTP API (bonus)\u000aThe server is optional and separate from the CLI (user decision, 2026-11-05): the CLI always works locally and never calls the server, so no file with the server host and port is written and the CLI does no health check. Other programs use the server directly over HTTP.\u000aThe server listens only on 127.0.0.1, so nobody else on the network can reach it (the API has no authentication) (user decision, 2026-10-28). Endpoints (parameters in the URL query string): GET /search (query, k, method), GET /answer (query, k, method), GET /health (no parameters); defaults are the same as in the CLI (method=bm25). Status codes: 422 when a parameter does not match its type or a required one is missing (automatic validation); 400 when a value breaks the rules of 4.2 (empty or nonsensical query, negative k), with the same messages; 503 when there is no index (/search and /answer, message "run index first") or the /answer queue is full; 200 otherwise. k = 0: /search returns 200 with an empty list (4.2 case 4); /answer returns 400 with "k must be >= 1 for answer" (4.4 case 3) (user decision, 2026-10-29) (user decision, 2026-10-28). Responses are validated against pydantic models shared with the CLI: /search returns a MinimalSearchResults, /answer a MinimalAnswer (4.9; question_id is a new uuid, since a single query has none) and /health a HealthStatus (4.9); a response that does not match its model never leaves the server (500). The server is started from the CLI and takes --port <int>, so the user can pick another port when the default one is already in use (user decision, 2026-10-28). Requests that need the model (only /answer; /search and /health never wait in it) are put in a queue and served one at a time, so simultaneous requests wait their turn instead of blocking or crashing the server (user decision, 2026-10-28). The model call runs in a worker thread inside the server process (awaited from the event loop), so a generation in progress never freezes /search or /health. Maximum requests waiting in the queue = W / T, where T is the measured time of one answer on CPU and W = 60 seconds (provisional, tuned during tests); a request beyond that limit gets 503 with a clear message at once.\u000aNo index at startup (user decision, 2026-10-29): the server starts anyway; /search and /answer answer 503 ("run index first"); /health answers 200 (the server itself is available) with index_loaded: false and action_suggest: "no index found: run index"; once index is run, the server loads it on the next request by the reload rule below.\u000aIndex version in the server (user decision, 2026-10-29, automatic reload chosen over a manual PUT /index): the server loads the active index version fully in memory at startup (index deletes the previous version folder after a switch, so nothing may be read from it later). Before serving each /search, /answer or /health, it reads the pointer file; if it names a version different from the loaded one, the server loads it apart and swaps it in at once when ready, so a request in progress (e.g. an /answer generating) finishes with the old version without errors; simultaneous requests that see the change trigger a single load (lock). If the new version cannot be loaded (corrupt, or no index), the server keeps serving the old one, logs a warning, reports it in /health action_suggest and does not retry that same version until the pointer names another one (the failure is most likely deterministic). Measure in the API phase: time of loading one index version into the server; if it exceeds 2 seconds, add a background task that reads the pointer every n seconds (n tuned during tests) and loads a new version before any request arrives, so no request pays the load time (user decision, 2026-10-29); the per-request check stays.\u000a\u000a### 4.8 Caching (bonus)\u000aQuery results are cached on disk, keyed by query, k, method and index version; a new index version invalidates them, and the entries of versions that no longer exist are deleted when the active version changes, so the cache never grows without limit (user decision, 2026-10-29).\u000aEdge cases / failures (user decision, 2026-10-29): a cache failure never breaks search or answer: the result is computed without the cache, with a warning on stderr and in the run log file, no traceback.\u000a1. Unreadable or corrupt cache entry → ignored and recomputed.\u000a2. Cache folder not writable, or disk full → the answer is returned anyway, only not stored in the cache.\u000a3. Half-written entry (e.g. Ctrl+C while saving) → cannot exist: each entry is written to a temporary file in the same folder and activated with os.replace, as in 4.3 case 9. Provisional design: it may change during implementation (user decision, 2026-10-28).\u000a\u000a### 4.9 Data models (pydantic, a foundation: may be extended with new models or extra fields)\u000a- MinimalSource: file_path: str, first_character_index: int, last_character_index: int\u000a- UnansweredQuestion: question_id: str = Field(default_factory=lambda: str(uuid.uuid4())), question: str\u000a- AnsweredQuestion(UnansweredQuestion): sources: List[MinimalSource], answer: str\u000a- RagDataset: rag_questions: List[AnsweredQuestion | UnansweredQuestion]\u000a- MinimalSearchResults: question_id: str, question: str, retrieved_sources: List[MinimalSource]\u000a- MinimalAnswer(MinimalSearchResults): answer: str\u000a- StudentSearchResults: search_results: List[MinimalSearchResults], k: int\u000a- StudentSearchResultsAndAnswer: search_results: List[MinimalAnswer], k: int\u000a- HealthStatus (returned by /health): index_loaded: bool, loaded_version: str | None (version held in memory by the server), active_version: str | None (version named by the pointer file, read on every /health call), action_suggest: str | None (null when both versions match; "no index found: run index" when there is no index; otherwise, after a failed automatic load, "<version> could not be loaded: <reason>; still serving <loaded version>; run index again", with the real names)\u000a\u000a### 4.10 Output\u000aEach command writes JSON conforming to the models. Search → StudentSearchResults (search_results with question_id, question, retrieved_sources; k). Answers → StudentSearchResultsAndAnswer (same + answer). file_path relative to the project root, written exactly as in the ingested corpus (data/raw/vllm-0.10.1/...).\u000a\u000a### 4.11 End-to-end pipeline (defense)\u000a1. `uv run python -m src index --max_chunk_size 2000`\u000a2. `uv run python -m src search_dataset --dataset_path data/datasets/UnansweredQuestions/dataset_docs_public.json --k 10 --save_directory data/output/search_results/UnansweredQuestions`\u000a3. `./moulinette evaluate_student_search_results <student results> <AnsweredQuestions dataset> --k 10 --max_context_length 2000` (rename moulinette-ubuntu/-fedora to moulinette) → "Student data is valid: True", Recall@1/3/5/10.\u000a4. `uv run python -m src answer_dataset --student_search_results_path ... --save_directory data/output/search_results_and_answer/UnansweredQuestions`\u000a\u000a## 5. Technologies\u000a- Python >= 3.10; flake8; type hints on parameters, returns and variables, mypy without errors; PEP 257 docstrings (Google or NumPy style).\u000a- Exceptions handled gracefully (try-except); context managers for files/connections; no resource leaks.\u000a- pydantic for the data models exchanged between stages (service/orchestration classes such as indexer, retriever, pipeline need not be pydantic).\u000a- uv as project and package manager (reviewer and moulinette only run `uv sync`); pyproject.toml and uv.lock at repo root.\u000a- CLI with Python Fire; tqdm progress bars.\u000a- Local HTTP API (bonus): FastAPI, served with uvicorn.\u000a- Semantic embeddings (bonus): all-MiniLM-L6-v2 on CPU, numpy brute-force cosine search. Library: fastembed (ONNX Runtime, no PyTorch) or sentence-transformers; both are tried and measured in the semantic index phase, simply and practically, on the points that could affect us (install size and uv sync time, time to embed the whole corpus on CPU against the 5-minute goal, recall@5 on docs and code, model load time in the API server, working offline once the model is cached), and the choice is made with the user from those numbers (user decision, 2026-10-29). Both give the same result for our case: one vector per text (mean pooling done by the library), vectors already normalised, silent truncation at 256 tokens, batching and model cache; fastembed is only lighter and faster (checked 2026-10-29 with fastembed 0.9.1: 152 MB environment, 87 MB model, norms 1.0, truncation max_length 256), so the choice does not change behaviour or recall. Our own code checks with token_count() whether a chunk fits in 256 tokens. Measured in the semantic index phase (user decision, 2026-10-29): share of chunks above 256 tokens, and recall@5 on docs and code of (a) accepting the truncation (only the first 256 tokens are embedded) against (b) one vector per 256-token window of the chunk, scoring the chunk with its best window; the choice is made with the user from those numbers.\u000a- Model: Qwen/Qwen3-0.6B (default). Other models allowed only if everything still works with Qwen3-0.6B.\u000a- Any other library allowed.\u000a- Makefile rules: install, run, debug (pdb), clean (__pycache__, .mypy_cache...), lint (`flake8 .` and `mypy . --warn-return-any --warn-unused-ignores --ignore-missing-imports --disallow-untyped-defs --check-untyped-defs`), lint-strict optional (`flake8 .` and `mypy . --strict`).\u000a- Tests with pytest or unittest covering edge cases (not graded); .gitignore for Python artifacts; virtual environment recommended.\u000a- Environment: CPU-only campus machine; moulinette binaries for Ubuntu / Fedora. Deep-learning stack and weights can total several GB: build and run from a location with enough disk space.\u000a- Repository layout: src/ (runnable as `uv run python -m src <command>`), pyproject.toml, uv.lock, README.md, data/raw/ (vLLM repo), data/processed/ (index), data/datasets/UnansweredQuestions/ and data/datasets/AnsweredQuestions/, data/output/search_results/<DatasetScope>/, data/output/search_results_and_answer/<DatasetScope>/. If structure or interface is not respected, the reference scripts cannot run and checks fail by design.\u000a- README.md (English): first line italic "This project has been created as part of the 42 curriculum by <login1>[, <login2>...]"; sections Description, Instructions, Resources (references + how AI was used, for which tasks and parts); plus System architecture, Chunking strategy, Retrieval method, Performance analysis (recall@k and performance), Design decisions, Challenges faced, Example usage. Any text in the project that states what the AI did is decided by discussing it with the user, never assumed (user decision, 2026-10-31).\u000a\u000a## 6. Scope (scaling direction)\u000aAll five bonuses are committed and implemented (user decision, 2026-10-28). They are graded only if the whole mandatory part validates, including robustness when a reviewer pushes it in odd directions; each worth one point, must work on a CPU-only machine and may have to be demonstrated:\u000a1. Semantic embeddings: vector index with a lightweight CPU model (e.g. all-MiniLM-L6-v2) next to the lexical index.\u000a2. Hybrid retrieval: combine lexical and semantic rankings into one list.\u000a3. Incremental indexing: re-index only a changed file.\u000a4. Caching: cache index and query results for cold start and repeated queries.\u000a5. Local HTTP API: query the index and answer questions over a small local HTTP API.\u000aFlake8 also applies to bonus files.\u000a\u000a## 7. Architectural methods that enable the scaling\u000aUser decisions, 2026-10-29. Each bonus plugs in without rewriting what already works:\u000a1. One retriever interface: Bm25Retriever, SemanticRetriever and HybridRetriever (RRF over the other two) share the same method search(query, k) -> list[MinimalSource]; --method only picks which one is created, so the rest of the program (CLI, API, search_dataset) never knows which one runs. Enables bonuses 1 and 2.\u000a2. One chunker per indexed file type, picked from a registry keyed by extension: .py (code), .md (Markdown), .txt (plain text), each with its own logic (4.1). Adding a type means adding one chunker class.\u000a3. Versioned index store (4.1 cases 7 and 11-15): chunks, embeddings and content hash kept per file; used by index, the CLI and the API server; makes incremental indexing possible. Enables bonus 3.\u000a4. One shared service layer: search and answer functions take and return pydantic models; the Fire CLI and the FastAPI server are thin wrappers that only call them, so the API never duplicates logic. Enables bonus 5.\u000a5. Cache whose key includes the index version (index version, method, query, k): when the version changes, old entries are simply never hit again; the model and the index are loaded once per process (cold start and repeated queries). Enables bonus 4. To be studied in depth with the user at the start of the caching phase before implementing it (user decision, 2026-10-29).\u000a6. One generator interface: Qwen/Qwen3-0.6B by default; another model can be swapped in without touching the rest, as long as everything still works with Qwen3-0.6B.\u000a\u000a## 8. Limits\u000a- Never call or import the moulinette.\u000a- No source wider than 2000 characters; max_chunk_size never above 2000.\u000a- No hard-coded input/output paths.\u000a- No large data files, model weights or generated outputs in the repository (the evaluator generates them).\u000a- No unhandled traceback on any input.\u000a- Must keep working with Qwen/Qwen3-0.6B.\u000a- Package manager is uv only for the evaluator.\u000a- Submission: only the work inside the Git repository is evaluated (src/, pyproject.toml, uv.lock, Makefile with install/run/debug/clean/lint, README.md, needed config files). A brief recode (minor behaviour change or small feature) may be requested during the defense.\u000a- AI usage (subject chapter III): only use AI-generated content that is fully understood and can be explained and justified at evaluation.'),'2026-11-05');
INSERT INTO spec VALUES('done','true','2026-11-05');
CREATE TABLE workflow (
    step    INTEGER PRIMARY KEY CHECK (step > 0),
    process TEXT NOT NULL CHECK (TRIM(process) <> '')
);
INSERT INTO workflow VALUES(1,unistr('MANDATORY: run the queries in order and follow ONLY the branch that\u000amatches what they return. Forbidden to skip or guess a branch.\u000aRun: SELECT topic, information FROM project WHERE topic IN (''name'', ''description'', ''done'');\u000aIf name is empty, ask the user for it and save it:\u000a  UPDATE project SET information = ''<name>'' WHERE topic = ''name'';\u000a\u000aRead what previous sessions left to do:\u000a  SELECT id, description, date FROM pending WHERE done = 0 ORDER BY id;\u000aKeep in mind the ones of the phase you go to (spec, pouring, concept study,\u000adivision) and resolve them there; when one is fulfilled, mark it:\u000a  UPDATE pending SET done = 1 WHERE id = <id>;\u000a(The work agent and the final test do not pass through this row: they read\u000athem in rows 502 and 701.)\u000a\u000aSESSION ROLE — MANDATORY. Each branch below marks which session_role\u000aUPDATE to run BEFORE its query. Run it exactly and re-read:\u000a  SELECT information FROM project WHERE topic = ''session_role'';\u000aIf it does not return the value you wrote, repeat it. Forbidden to follow the\u000abranch without the role written. The two commands are:\u000a  [SINGLE]    UPDATE project SET information = ''single'' WHERE topic = ''session_role'';\u000a  [PRINCIPAL] UPDATE project SET information = ''principal'' WHERE topic = ''session_role'';\u000a              EXCEPTION: if you reached this row from row 305 or 407,\u000a              do NOT run [PRINCIPAL]: this session is already single and MUST\u000a              close as single.\u000a\u000aORIENT THE USER — MANDATORY, before any work of the phase. Once you know\u000athe branch below (its role UPDATE and its state queries, never the phase\u000awork), write in your reply, as plain text: the greeting of the profile''s\u000afirst row 2 if not given yet in this session; where the project stands (its\u000aphase and what is done in it); what was left last session (the open pending\u000aof that phase, each with its context; an index or id a pending cites without\u000asaying what it means, such as e1, is looked up first, for example in reviews,\u000aand shown with its meaning); and what you will do next. End the\u000areply asking the user to tell you whether to resume there. FORBIDDEN in that\u000areply: a selection-tool question (it hides the text) or starting the phase\u000a(proposals, rows, questions). Start the phase only in your next reply, after\u000athe user confirms.\u000a\u000aThen continue according to done:\u000a\u000adone = true\u000a  → if description is empty, run [SINGLE] and then:\u000a      SELECT process FROM workflow WHERE step = 2;\u000a    Otherwise, run:\u000a      SELECT id, concept, level FROM concepts WHERE done = 0;\u000a    If it returns any row, there are concepts left to study: run\u000a      [SINGLE] and then:\u000a      SELECT process FROM workflow WHERE step = 3;\u000a    (the concept study).\u000a    If it returns no rows, all concepts are studied: run\u000a      SELECT information FROM project WHERE topic = ''blocks_division'';\u000a      not_started or in_progress → run [SINGLE] and then: SELECT process FROM workflow WHERE step = 4;\u000a                    (the division into blocks, row 4)\u000a      done        → run the next-block query:\u000a                      SELECT id FROM blocks b WHERE state <> ''done'' AND NOT EXISTS (\u000a                        SELECT 1 FROM block_deps d JOIN blocks p ON p.id = d.depends_on_id\u000a                        WHERE d.block_id = b.id AND p.state <> ''done'') ORDER BY id LIMIT 1;\u000a                    No rows (all blocks in done): launch the work agent\u000a                      of the final test. Run [PRINCIPAL] (except for\u000a                      the EXCEPTION) and then:\u000a                      SELECT process FROM workflow WHERE step = 101;\u000a                      (the same chain 101, 102 and 103, in its final test\u000a                      variant; the work agent does row 7: final test\u000a                      and project close).\u000a                    With an id: launch the work agent of block <id>. Run\u000a                      [PRINCIPAL] (except for the EXCEPTION) and then:\u000a                      SELECT process FROM workflow WHERE step = 101;\u000a                      (it is a chain of rows: 101, 102 and 103; follow it entirely).\u000a\u000adone = false\u000a  → run [SINGLE] and then:\u000a      SELECT information FROM project WHERE topic = ''spec_definition_progress'';\u000a    not_started or in_progress\u000a      → run: SELECT information FROM spec WHERE topic = ''instructions'';\u000a    done\u000a      → run: SELECT information FROM project WHERE topic = ''pouring_state'';\u000a        not_started or in_progress\u000a                    → run: SELECT information FROM pouring WHERE topic = ''instructions'';\u000a        done        → inconsistency: warn and find out why an automatic field was left wrong.\u000a                      Look at the dates with:\u000a                        SELECT topic, information, updated_at FROM project;\u000a                        SELECT topic, updated_at FROM spec;\u000a                      (pouring has no updated_at.) Propose solutions to the user.\u000a        other value → no case defined yet.'));
INSERT INTO workflow VALUES(2,unistr('Diagnosis: project.done = true with project.description empty.\u000aMANDATORY, in this order. Forbidden to write project.description or\u000asolve the problem on your own: you only check, warn and propose.\u000a\u000aCheck with these four queries, and do not write project.description until\u000aall four pass:\u000a\u000a1. The five pouring tables have rows (none counts 0):\u000a   SELECT ''descriptions'' AS table_name, COUNT(*) AS row_count FROM descriptions\u000a   UNION ALL SELECT ''prohibitions'' AS table_name, COUNT(*) AS row_count FROM prohibitions\u000a   UNION ALL SELECT ''constraints'' AS table_name, COUNT(*) AS row_count FROM constraints\u000a   UNION ALL SELECT ''goals'' AS table_name, COUNT(*) AS row_count FROM goals\u000a   UNION ALL SELECT ''concepts'' AS table_name, COUNT(*) AS row_count FROM concepts;\u000a\u000a2. No row of those tables has an empty basis or why (MUST return 0 rows):\u000a   SELECT ''descriptions'' AS table_name, id FROM descriptions WHERE TRIM(basis) = '''' OR TRIM(why) = ''''\u000a   UNION ALL SELECT ''prohibitions'' AS table_name, id FROM prohibitions WHERE TRIM(basis) = '''' OR TRIM(why) = ''''\u000a   UNION ALL SELECT ''constraints'' AS table_name, id FROM constraints WHERE TRIM(basis) = '''' OR TRIM(why) = ''''\u000a   UNION ALL SELECT ''goals'' AS table_name, id FROM goals WHERE TRIM(basis) = '''' OR TRIM(why) = ''''\u000a   UNION ALL SELECT ''concepts'' AS table_name, id FROM concepts WHERE TRIM(basis) = '''' OR TRIM(why) = '''';\u000a\u000a3. Every goal with a constraint_id points to a constraint that exists (MUST\u000a   return 0 rows):\u000a   SELECT id FROM goals WHERE constraint_id IS NOT NULL AND constraint_id NOT IN (SELECT id FROM constraints);\u000a\u000a4. spec.done, pouring.done, project.spec_definition_progress and\u000a   project.pouring_state are true, true, done, done:\u000a   SELECT (SELECT information FROM spec WHERE topic = ''done'') AS spec_done,\u000a          (SELECT information FROM pouring WHERE topic = ''done'') AS pouring_done,\u000a          (SELECT information FROM project WHERE topic = ''spec_definition_progress'') AS spec_progress,\u000a          (SELECT information FROM project WHERE topic = ''pouring_state'') AS pouring_state;\u000a\u000aIf all four pass: write project.description based on what was poured:\u000a  UPDATE project SET information = ''<description>'' WHERE topic = ''description'';\u000aand follow the done = true branch of row 1 from the concepts query\u000a(SELECT id, concept, level FROM concepts WHERE done = 0;).\u000aIf any fails: warn which one and propose a solution to the user.'));
INSERT INTO workflow VALUES(3,unistr('Row 3 of workflow — concept study (entry).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000aConcept study. You arrive here from row 1 because there are concepts left\u000ato study. Handle them all before dividing into blocks: the project''s need2learn\u000aones and the partial ones the user already had.\u000a\u000aThis row is a chain: each task is a row of workflow. Do ONLY the\u000atask of the row you are in and, ONLY when you finish it, run the\u000aquery that takes you to the next one. Do not get ahead, do not do tasks from\u000amemory and do not skip any row.\u000a\u000aRules that apply throughout the row (and its rows 301 to 305):\u000a10. A pending concept only becomes agent or is removed in two ways: the\u000a    user detects it (it is no longer used in the project, due to a spec\u000a    change, or they prefer to delegate it), or you detect it and propose it. In\u000a    both cases the user decides, discussing it with you; never do it\u000a    on your own. ONLY with their decision:\u000a      - Without reviews, it is deleted:\u000a          DELETE FROM concepts WHERE id = <id>;\u000a      - With reviews, the table does not allow deleting it and it would stay pending. It is\u000a        changed to agent to take it out of the pending ones (its reviews stay in\u000a        the history):\u000a          UPDATE concepts SET level = ''agent'' WHERE id = <id>;\u000a        The table marks it studied (done = 1) by trigger.\u000a11. Moving on without finishing the study (the user''s choice). The study is\u000a    not a wall: if at any moment the user says they want to move on without\u000a    completing it (one concept, several or all the pending ones), do not hold\u000a    them back and do not insist. Never propose it yourself. First warn them\u000a    once, in their language, with the selection tool: "<concepts> did not\u000a    complete the study. You may not have enough\u000a    knowledge of them for the project. If you still want to move on, that is\u000a    fine: I will mark them in the tables so you can move on." Options: move\u000a    on / keep studying. ONLY if they choose to move on, for each concept:\u000a      UPDATE concepts SET done = 1, skipped = 1 WHERE id = <id> AND done = 0;\u000a    Check: SELECT id, concept, level, done, skipped FROM concepts WHERE id IN (<ids>);\u000a    The concept keeps its level (a need2learn stays need2learn, it does not\u000a    become partial) and its reviews; skipped = 1 records that the user moved\u000a    on without the study, and the block work reinforces it in practice. Then\u000a    run SELECT process FROM workflow WHERE step = 303; (it sends you to the\u000a    next pending one or to 305). This rule is the only exception to the\u000a    chain and to "do not write concepts.done by hand".\u000a12. A spec decision during the study. It is the user who decides, never you.\u000a    Say which of these cases it is before writing anything:\u000a      - It changes or adds something to the spec: show the spec point and the\u000a        exact text, and warn that writing it reopens the spec and the pouring\u000a        until they approve it again. ONLY with their OK, write it at that moment\u000a        and follow "Reopened after the pouring started" of:\u000a          SELECT information FROM spec WHERE topic = ''instructions'';\u000a        Forbidden to leave it for a later phase or for the close. Once approved,\u000a        continue the study at the concept you were on.\u000a      - It is still undecided: save it in pending, naming the spec point and the\u000a        phase where it is decided. The spec is not touched.\u000a      - It only discards an idea the spec never contained: nothing is written;\u000a        tell them so.\u000a    FORBIDDEN to put the states or dates of spec, pouring or project back by\u000a    hand. If you edited the spec without their OK, tell them and follow that same\u000a    block; if they reject the text, edit it back and they approve that.\u000a\u000aPDF contents (study with NotebookLM): no explanations of yours, because\u000aNotebookLM answers only from the sources. Real text (not images), in this\u000aorder: (a) project name and its goal; (b) one section per concept, with the same format in the PDF and in the text given\u000ato the user when one is added, with the exact name from concepts.concept, its level and\u000atwo separate parts: what the user MUST be able to explain, in general terms and without\u000aproject details (what it is, the problem it solves, how it works, its options and their\u000atrade-offs), and, marked as information only and not evaluated, how it applies here\u000a(basis and why, which goals, constraints or prohibitions touch it, what the spec already\u000adecided and what is still open and in which phase it is decided). Architecture decisions\u000anever go in the first part;\u000a(c) the full spec (SELECT information FROM spec WHERE topic = ''spec'';);\u000a(d) at the end, an "Official documentation" section with the URL of the\u000aofficial documentation of each concept. If you are not sure of a URL,\u000awrite "no verified URL"; do not invent it. The user reviews the URLs and\u000agives them as the source of truth.\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 301;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(4,unistr('Row 4 of workflow — division into blocks (entry).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000aYou arrive here from row 1 with project.done = true, all concepts\u000astudied and project.blocks_division in not_started or in_progress. Here you define\u000awhich blocks the project has: what each one receives, processes and delivers, and what\u000ait depends on. The technical detail of each block goes in its development, not here.\u000a\u000aThis row is a chain: each task is a row of workflow. Do ONLY the\u000atask of the row you are in and, ONLY when you finish it, run the\u000aquery that takes you to the next one. Do not get ahead, do not do tasks from\u000amemory and do not skip any row.\u000a\u000aRules that apply throughout the division (rows 401 to 407):\u000a4. Each block carries in block_division.md: a short name representative of\u000a   what it does (for example parser, runner; unique in the project), what it receives and\u000a   from which block or external source, what it processes (one line), what it delivers and which blocks it depends on.\u000a   Nothing more: acceptance, diagram, outputs and the how and why it processes go in\u000a   its development.\u000a\u000a5. Each observation of yours cites a criterion: coupling (no. of dependencies),\u000a   data crossing each boundary, cost (time, memory, external calls)\u000a   or cut rule (if its acceptance would not fit in 5 "must do" and 5 "must not\u000a   do", the block is split). If a block depends on a concept with\u000a   concepts.level = ''partial'' or concepts.skipped = 1 (the user moved on\u000a   without finishing its study), focus on the theory, explain more and push the\u000a   user to go deeper.\u000a\u000a6. Move what is approved to "Decided" and what is open to "Pending" in the file,\u000a   with the Mermaid of how the blocks are composed. Leave it updated before\u000a   closing the session.\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 401;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(5,unistr('Row 5 of workflow — work on a block (entry).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000aYou are the work agent of block <id>. The launch prompt gives you the path\u000aof project.db, the path of kiron_pupil.db and the id of the block. You work a\u000asingle block in this session. The user decides; you discuss, propose and write\u000aONLY what they approve.\u000aThe prompt also gives you the terminal handle of the principal (<principal_handle>).\u000aCommunication with other agents: use the exact commands of each step; your own\u000ahandle is in $ORCA_TERMINAL_HANDLE. Each orca send goes with --wait-submit 20; if it warns that the Enter may have been swallowed, repeat that same command adding the --retry-request <id> it gives (it never sends twice); never send probe or test messages. The orca commands are an example: if\u000aorca does not exist, look in your environment for an equivalent tool (one that\u000acreates a terminal with an agent, sends it text, closes it and gives you your own\u000aidentifier) and adapt the commands to it. If there is none, tell the\u000auser the exact message and which agent to take it to, and wait.\u000aQuestions to the user: every question you ask the user is asked with the CLI\u000aselection questions (your agent''s multiple-choice tool), with your\u000arecommendation and two or three options, never as loose text in the\u000aconversation (2026-10-22: the work agent does not read SKILL.md, where this\u000arule also lives). When the question asks to approve a text (a MUST, an\u000aoutput, a diagram…), the question itself carries that full text: the user\u000amay not see earlier messages.\u000aWriting to the databases: ALL writes with free text (definition, outputs,\u000aacceptance, diagram, pending, handoff…) go through a heredoc with the delimiter in\u000aquotes, so that neither the shell nor SQLite breaks the text, and each single quote\u000aof the text is written twice (name = ''''x''''):\u000a  sqlite3 <path of the database> <<''SQL''\u000a  UPDATE ... SET ... = ''<text>'' WHERE ...;\u000a  SQL\u000aIf the database rejects the write, read the error, fix it and repeat. This applies to\u000athe whole session, also to last.\u000a\u000aThis row is a chain: each task is a row of workflow. Do ONLY the\u000atask of the row you are in and, ONLY when you finish it, run the\u000aquery that takes you to the next one. Do not get ahead, do not do tasks from\u000amemory and do not skip any row.\u000a\u000aSession close, at any moment of the chain: when the user asks to\u000aclose the session (with the block in done or not), leave the row you are in and\u000ago to kiron_pupil.db and run: SELECT action FROM last WHERE step = 1;\u000aIf the same message asks for something before the close ("then the tests\u000aand kiron bye"), finish that first, following the chain, and close after.\u000aThe whole close is there, including the notice to the principal.\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 501;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(6,unistr('You are the tests agent of block <id>. You were launched by the work agent of that\u000ablock. MANDATORY: each rule of this row is unbreakable; forbidden to\u000askip one or act outside them. Your folder (the tests folder, already\u000acreated, where you were launched) has .tests_context.txt: this row; the\u000adefinition, acceptance and outputs of the block; the outputs of its\u000adependencies; and the complete rows of constraints, prohibitions and\u000adescriptions. The prompt gives you the id <id>, the path of project.db\u000a(only to write it in the automatic close of step 5; you do not open it) and\u000athe terminal handle of the work agent (<work_handle>). You communicate ONLY with the work agent,\u000anever with the user. You ONLY have permission to read and write inside your\u000afolder and to send messages; the launch blocks the rest: do not ask for\u000aothers.\u000a\u000aGOAL: break the block. You are not here to confirm that it works but to\u000afind the input or the sequence that makes it fail. Push it to the maximum\u000awith edge cases that are objective and realistic: the ones the project, as\u000ait is specified and built (spec, acceptance, outputs, dependencies,\u000aconstraints, prohibitions, descriptions), could really demand of this\u000afunctionality inside its real flow. Every case is traceable to one of those\u000asources (its docstring says which); never a case invented outside that\u000acontext (inputs the project can never produce, environments it does not\u000arun in, loads beyond its limits).\u000a\u000a1. Blindness. You work ONLY with what you were given. Do not open, read or search\u000a   anything outside your folder. If you lack something to\u000a   write a test, ask the work agent for it (step 6c).\u000a\u000a2. Tool. Use the standard framework of the block''s technology (in\u000a   Python, pytest). Call each method and structure with the exact name and shape\u000a   that outputs gives. Do not write the imports of the project code:\u000a   the work agent adds them. Do not run the tests.\u000a\u000a3. What to test, always with the GOAL above (break the block, not check the\u000a   normal case):\u000a   a. acceptance: each MUST with at least one test that checks that it does it;\u000a      each MUST NOT with at least one test that checks that it does not happen.\u000a   b. outputs: of each public method and structure, what it returns (type and\u000a      shape) and each case in which outputs says it fails.\u000a   c. Stress of the mechanism, everything that applies:\u000a      - edges: empty, minimum, maximum, a single element, just before and just\u000a        after each limit;\u000a      - invalid inputs, of incorrect type, malformed or incomplete;\u000a      - combinations: several limit conditions at once;\u000a      - sequences: repeated calls, unexpected order, state that remains\u000a        between one call and another;\u000a      - volume and load up to the threshold of each numeric constraint that\u000a        applies, without exceeding the limits of the project.\u000a   d. Decide which rows of constraints, prohibitions and descriptions apply to the\u000a      block according to its definition and outputs. Each row that applies gets at least\u000a      one test.\u000a   e. Nothing outside a-d: no redundant or unnecessary test.\u000a\u000a4. How to write them:\u000a   - Everything in the tests files (names, docstrings, comments, messages,\u000a     data labels) in the tests language the prompt gives; if it gives none,\u000a     English.\u000a   - A test checks a single thing, and its name says which\u000a     (test_rejects_negative_amount).\u000a   - Its docstring says where it comes from: "acceptance MUST 2", "outputs:\u000a     <method>", "constraints 4".\u000a   - Deterministic: the same input gives the same result, without depending on the\u000a     order or on other tests.\u000a   - The input data come from the project''s domain (definition,\u000a     descriptions), never generic like "foo".\u000a   - You can create, inside the tests folder, the structures you\u000a     need to stress the code (fixtures, data generators, doubles\u000a     of the dependencies, helpers), as long as the load they generate does not exceed\u000a     the limits of the project.\u000a\u000a5. Automatic close. In the tests folder of the block, a single mechanism\u000a   of the framework that runs once, at the end of the complete run\u000a   of the folder, and that, ONLY if all the tests passed and there was at least one,\u000a   runs in project.db:\u000a     UPDATE blocks SET constraints = 1, prohibitions = 1, descriptions = 1 WHERE id = <id>;\u000a   Never a function or a test at the end of each file: it runs even if\u000a   other tests fail. Reference in Python with pytest (conftest.py); in another\u000a   framework, use its equivalent (the end-of-run hook or event):\u000a     import sqlite3\u000a     def pytest_sessionfinish(session, exitstatus):\u000a         if exitstatus == 0 and session.testscollected > 0:\u000a             c = sqlite3.connect(''<path of project.db>'')\u000a             c.execute(''UPDATE blocks SET constraints = 1, prohibitions = 1, ''\u000a                       ''descriptions = 1 WHERE id = <id>'')\u000a             c.commit()\u000a\u000a6. Communication with the work agent:\u000a   a. When you finish, send:\u000a        orca terminal send --terminal <work_handle> --text ''[tests → work]\u000a        block <id>: TESTS_READY: path <path>. Coverage: <line of\u000a        acceptance → tests>. Rows applied: constraints <ids>, prohibitions\u000a        <ids>, descriptions <ids>. Discarded: <id: reason>.'' --enter\u000a      and wait for its answer without doing anything else.\u000a   b. If you receive FIX, fix exactly what it asks and send:\u000a        orca terminal send --terminal <work_handle> --text ''[tests → work]\u000a        block <id>: TESTS_READY: fixed <test>: <what changed>.'' --enter\u000a      and wait again.\u000a   c. If you lack information, send:\u000a        orca terminal send --terminal <work_handle> --text ''[tests → work]\u000a        block <id>: QUESTION: <what you need>.'' --enter\u000a      It answers you with ANSWER, without revealing how the code is made.\u000a   d. You do not close yourself: the work agent closes you.\u000a   e. Each orca send goes with --wait-submit 20; if it warns that the Enter may have been swallowed, repeat that same command adding the --retry-request <id> it gives (it never sends twice); never send probe or test messages. The orca commands are an example: if orca does not exist, use the\u000a      equivalent tool that the work agent indicates to you in the prompt and adapt the\u000a      commands to it. If there is none, tell the user: "Tests of block\u000a      <id> ready in <path>; let the work agent know." and wait.'));
INSERT INTO workflow VALUES(7,unistr('Row 7 of workflow — final test and project close (entry).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000aYou are the work agent of the final test: all blocks are in done.\u000aThe principal launched you (row 101); its prompt gives you the path of\u000aproject.db, the path of kiron_pupil.db and its handle (<principal_handle>).\u000aIt verifies your close.\u000aCommunication with other agents: use the exact commands of each step; your\u000aown handle is in $ORCA_TERMINAL_HANDLE. Each orca send goes with --wait-submit 20; if it warns that the Enter may have been swallowed, repeat that same command adding the --retry-request <id> it gives (it never sends twice); never send probe or test messages. The orca commands are an\u000aexample: if orca does not exist, look in your environment for an equivalent\u000atool and adapt the commands; if there is none, tell the user the exact\u000amessage and which agent to take it to, and wait.\u000aQuestions to the user: always with the CLI selection questions (your agent''s\u000amultiple-choice tool), never as loose text, as in row 5.\u000aWriting to the databases: every write with free text goes through a heredoc\u000awith the delimiter in quotes, and each single quote in the text is written\u000atwice, as in row 5:\u000a  sqlite3 <path of the database> <<''SQL''\u000a  UPDATE ... SET ... = ''<text>'' WHERE ...;\u000a  SQL\u000aIf the database rejects the write, read the error, fix it and repeat. This\u000aapplies to the whole session, also to last.\u000aWho you are and who you work with. Go to kiron_pupil.db and run:\u000a  SELECT action FROM first WHERE step = 1;\u000aThese are your rules (identity): unbreakable, in every response.\u000a  SELECT topic, information FROM pupil WHERE topic NOT IN (''state'', ''psychology_review'');\u000aCall the user by their name and speak to them in their language; explain\u000astarting from what they already know.\u000a  SELECT kind, analysis FROM psychology;\u000aApply it silently to how you explain and communicate.\u000a\u000aThis row is a chain: each task is a row of workflow. Do ONLY the task of\u000athe row you are in and, only when you finish it, run the query that takes\u000ayou to the next one. Do not get ahead, do not do tasks from memory and do\u000anot skip any row.\u000a\u000aSession close, at any point in the chain: when the user asks to close the\u000asession, leave the row you are in, go to kiron_pupil.db and\u000arun: SELECT action FROM last WHERE step = 1;\u000a\u000aOnly when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 701;\u000aForbidden to run that query before finishing this row, to skip a row or to\u000ado the work of another row here.'));
INSERT INTO workflow VALUES(8,unistr('You are the final tests agent. MANDATORY: each rule in this row is\u000aunbreakable; forbidden to skip one or act outside them. The work agent of the final test launched you; its prompt gives you the\u000atests folder (final/, already created with individual/ and scenarios/), the\u000apath of project.db (only to write it in the automatic close; you do not open\u000ait) and its handle (<work_handle>). You ONLY\u000acommunicate with the work agent, never with the user. You ONLY have permission\u000ato read and write inside final/ (where you were launched; its\u000a.tests_context.txt holds this row and the queries of the prompt) and to\u000asend messages; the launch blocks the rest: do not ask for others.\u000a\u000aGOAL: break the program. You are not here to confirm that it works but to\u000afind the input or the sequence that makes it fail. Push it to the maximum\u000awith edge cases that are objective and realistic: the ones the project, as\u000ait is specified and built (spec, acceptance, outputs, dependencies,\u000aconstraints, prohibitions, descriptions), could really demand of this\u000afunctionality inside its real flow. Every case is traceable to one of those\u000asources (its docstring says which); never a case invented outside that\u000acontext (inputs the project can never produce, environments it does not\u000arun in, loads beyond its limits).\u000a\u000a1. Blindness. You work ONLY with what you were given. Do not open, read or search\u000a   anything outside final/. If you are missing something, ask the\u000a   work agent for it (step 6c).\u000a\u000a2. Tool. Use the standard framework of the project''s technology (in\u000a   Python, pytest). Call each method and structure with the exact name and shape\u000a   given by the outputs. Do not write the imports of the project''s\u000a   code: the work agent adds them. Do not run the tests.\u000a\u000a3. Individual phase (folder final/individual/), with the GOAL above. For\u000a   each row of goals, constraints, prohibitions and\u000a   descriptions, the tests needed to stress that aspect to the maximum:\u000a   - edges: empty, minimum, maximum, a single element, just before and just\u000a     after each limit;\u000a   - invalid inputs, of the wrong type, malformed or incomplete;\u000a   - sequences: repeated calls, unexpected order, state between calls;\u000a   - volume and load up to the threshold of each numeric constraint, without\u000a     exceeding the project''s limits.\u000a   Each row gets at least one test. Each test marks exactly the row it\u000a   tests, with the framework''s tagging mechanism (in pytest,\u000a   @pytest.mark.row(''<table>'', <id>)).\u000a\u000a4. Scenarios phase (folder final/scenarios/). Real cases of the project''s\u000a   domain (according to the spec), which go through the program end to end\u000a   following block_deps. Each scenario combines two or more rows (one mark\u000a   per row) and they go from the most basic to the most stressful possible, without exceeding\u000a   the project''s limits. They ONLY run if the whole individual phase passed.\u000a\u000a5. How to write them: everything in the tests files (names, docstrings,\u000a   comments, messages, data labels) in the tests language the prompt gives\u000a   (none given: English); a test checks a single thing and its name says which;\u000a   deterministic; data from the project''s domain, never generic like "foo".\u000a   You can create inside final/ the structures you need to stress\u000a   (fixtures, data generators, doubles, helpers), as long as the load\u000a   they generate does not exceed the project''s limits.\u000a   Automatic close. In final/, a single framework mechanism that:\u000a   a. runs all the individual tests before the scenarios;\u000a   b. skips the scenarios if any individual test failed;\u000a   c. when the full run ends, in project.db and in this order:\u000a        DELETE FROM test;\u000a        UPDATE <table> SET compliance = ''not_yet'';   (in the four tables)\u000a      inserts one result per test, the individual ones first (in the code,\u000a      the values go as driver parameters, never pasted into the SQL\u000a      text: a test id with a quote would break the write):\u000a        INSERT INTO test (phase, test, rows, outcome)\u000a          VALUES (''<individual|scenarios>'', ''<test id>'',\u000a                  ''<table> <id>;<table> <id>'', ''<passed|failed|skipped>'');\u000a      sets to partially each row whose individual tests all passed:\u000a        UPDATE <table> SET compliance = ''partially'' WHERE id = <id>;\u000a      and, if no individual test failed and all the scenarios passed:\u000a        UPDATE <table> SET compliance = ''complied'' WHERE compliance = ''partially'';\u000a   Reference in Python with pytest (conftest.py, tested); in another framework,\u000a   reproduce the same with its equivalents (tags, order, skip and hook or\u000a   end-of-run event):\u000a        import sqlite3\u000a        import pytest\u000a\u000a        DB = ''<path of project.db>''\u000a        TABLES = (''goals'', ''constraints'', ''prohibitions'', ''descriptions'')\u000a        results = {''individual'': [], ''scenarios'': []}\u000a\u000a\u000a        def _phase(nodeid):\u000a            return ''scenarios'' if ''scenarios/'' in nodeid else ''individual''\u000a\u000a\u000a        def pytest_configure(config):\u000a            config.addinivalue_line(''markers'', ''row(table, id): pouring row tested by the test'')\u000a\u000a\u000a        def pytest_collection_modifyitems(items):\u000a            items.sort(key=lambda item: _phase(item.nodeid) == ''scenarios'')\u000a\u000a\u000a        def pytest_runtest_setup(item):\u000a            if _phase(item.nodeid) == ''scenarios'' and any(\u000a                    outcome != ''passed'' for _, _, outcome in results[''individual'']):\u000a                pytest.skip(''the individual phase has failures'')\u000a\u000a\u000a        @pytest.hookimpl(hookwrapper=True)\u000a        def pytest_runtest_makereport(item, call):\u000a            outcome = yield\u000a            outcome.get_result().rows = [tuple(m.args) for m in item.iter_markers(''row'')]\u000a\u000a\u000a        def pytest_runtest_logreport(report):\u000a            if report.when == ''call'' or (report.when == ''setup'' and report.outcome != ''passed''):\u000a                results[_phase(report.nodeid)].append(\u000a                    (report.nodeid, getattr(report, ''rows'', []), report.outcome))\u000a\u000a\u000a        def pytest_sessionfinish(session, exitstatus):\u000a            c = sqlite3.connect(DB)\u000a            c.execute(''DELETE FROM test'')\u000a            for table in TABLES:\u000a                c.execute(f"UPDATE {table} SET compliance = ''not_yet''")\u000a            for phase in (''individual'', ''scenarios''):\u000a                for nodeid, rows, outcome in results[phase]:\u000a                    c.execute(''INSERT INTO test (phase, test, rows, outcome) VALUES (?, ?, ?, ?)'',\u000a                              (phase, nodeid, '';''.join(f''{t} {i}'' for t, i in rows), outcome))\u000a            failed = {r for _, rows, o in results[''individual''] if o != ''passed'' for r in rows}\u000a            tested = {r for _, rows, _ in results[''individual''] for r in rows}\u000a            for table, row_id in tested - failed:\u000a                c.execute(f"UPDATE {table} SET compliance = ''partially'' WHERE id = ?", (row_id,))\u000a            scenarios = results[''scenarios'']\u000a            if scenarios and not failed and all(o == ''passed'' for _, _, o in scenarios):\u000a                for table in TABLES:\u000a                    c.execute(f"UPDATE {table} SET compliance = ''complied'' WHERE compliance = ''partially''")\u000a            c.commit()\u000a\u000a6. Communication with the work agent:\u000a   a. When you finish, send:\u000a        orca terminal send --terminal <work_handle> --text ''[tests →\u000a        work] final: TESTS_READY: path <path>. Coverage: <table id →\u000a        tests>. Scenarios: <scenario → rows>.'' --enter\u000a      and wait for its answer without doing anything else.\u000a   b. If you receive FIX, fix exactly what it asks for and send:\u000a        orca terminal send --terminal <work_handle> --text ''[tests →\u000a        work] final: TESTS_READY: fixed <test>: <what changed>.'' --enter\u000a      and wait again.\u000a   c. If you are missing information, send:\u000a        orca terminal send --terminal <work_handle> --text ''[tests →\u000a        work] final: QUESTION: <what you need>.'' --enter\u000a      It answers you with ANSWER, without revealing how the code is built.\u000a   d. You do not close yourself: the work agent closes you.\u000a   e. Each orca send goes with --wait-submit 20; if it warns that the Enter may have been swallowed, repeat that same command adding the --retry-request <id> it gives (it never sends twice); never send probe or test messages. The orca commands are an example: if orca does not exist, use the\u000a      tool the work agent indicated in the prompt. If there is\u000a      none, tell the user the exact message for the work agent and wait.'));
INSERT INTO workflow VALUES(101,unistr('Row 101 of workflow — launch of the work agent of block <id> (1 of 3).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000aFinal test (you arrive without an id because all blocks are in done): do the\u000asame with these differences, and only these: the terminal title is\u000a''work final test''; the prompt says "You are the work agent of the final\u000atest." instead of "of block <id>", carries no id and ends in\u000aSELECT process FROM workflow WHERE step = 7; instead of step = 5; and in the\u000amessages of 102 and 103 "final test" goes where it says "block <id>".\u000a\u000aa. Open the handoff session:\u000a     INSERT INTO handoff (handoff) VALUES (''session open: no changes in blocks yet'');\u000ab. (run it from the folder where your session runs, with no cd before it: --worktree active needs an Orca worktree and fails with selector_not_found otherwise; the cd goes only inside --command)\u000a   orca terminal create --worktree active --title ''work block <id>''\u000a     --command "cd <project root> && KIRON_ROLE=work KIRON_SKILL=<skill folder>\u000a     claude --model <mid model> --effort medium\u000a     --settings <skill folder>/agents/claude_code/hooks_settings.json\u000a     --allowedTools ''Bash(orca:*)''" --json\u000a   (<project root> is the folder of project.db: the agent starts there, not\u000a   in the folder of the terminal.)\u000a   Model and effort: <mid model> is the model just below the most capable one\u000a   the user''s plan covers without usage credits (faster), with its medium\u000a   reasoning/effort level.\u000a   Before launching, find out what the plan covers, spending as little as\u000a   possible (once per session; reuse it in later launches):\u000a   1. The plan: read it from your tool''s account or config, only the plan\u000a     fields; never print anything else of that file (example, Claude Code:\u000a     oauthAccount.organizationType and oauthAccount.hasExtraUsageEnabled of\u000a     ~/.claude.json, or $CLAUDE_CONFIG_DIR/.claude.json). If your tool does\u000a     not expose it, ask the user which plan they have.\u000a   2. Open the official pricing page of the tool''s provider and read its\u000a     table of models per plan, the column of the user''s plan (Claude:\u000a     the "Models and usage" table of https://claude.com/pricing). This page\u000a     is the only source: no web search and no other pages.\u000a   3. In that table, "Yes" or a share of the limits means covered; "Usage\u000a     credits" means it uses credits; "No" means it is not offered. If the\u000a     page cannot be read or the table is not there, FORBIDDEN to mark the\u000a     models as using credits: tell the user and ask them which models their\u000a     plan covers, with no recommendation.\u000a   Then ask the user with the selection tool, in their language: "Which model\u000a   do I launch the <role> with (effort medium)?" Options: the models of the\u000a   tool; first the recommended one, the covered model just below the most\u000a   capable covered one (if the plan covers only one, that one), with\u000a   "(recommended)" after its name; every model that uses credits with\u000a   "(uses credits)" after its name, never recommended; the user can also write\u000a   another one. Launch ONLY with the model the user chose. FORBIDDEN to\u000a   launch, try or relaunch on your own a model that uses credits, or to accept\u000a   a usage-credits prompt: if a launch still asks for usage credits, close\u000a   that terminal without doing anything else in it, mark that\u000a   model "(uses credits)" and ask again.\u000a   Example, Claude Code: --model <mid model> --effort medium, as in the command.\u000a   Another tool: its equivalent options (<skill folder>/agents/ADAPT.md,\u000a   section 3); if it does not let you choose, tell the user and use its\u000a   default.\u000a   Save the handle it returns (<work_handle>). The work agent\u000a   is always launched with KIRON_ROLE=work in its environment, with\u000a   any tool or by hand: that way it knows its role at close (last).\u000a   Hooks: the work agent talks with the user, so it carries kiron''s hooks,\u000a   always with KIRON_SKILL=<skill folder> in its environment. Claude Code:\u000a   --settings <skill folder>/agents/claude_code/hooks_settings.json, as in the\u000a   command. Another tool: use (or create, the first time) its adapter in\u000a   <skill folder>/agents/<your tool>/ following <skill folder>/agents/ADAPT.md,\u000a   section 1; without hooks in your tool, that section says what to add to the\u000a   prompt and what to tell the user.\u000a   If it is not a POSIX shell, use the equivalent form for that shell\u000a   (PowerShell: $env:KIRON_ROLE=''work''; claude ...).\u000ac. Send it the prompt:\u000a     orca terminal send --terminal <work_handle> --text ''<prompt>'' --enter\u000a   The prompt carries: "You are the work agent of block <id>. Path of\u000a   project.db: <path>. Path of kiron_pupil.db: <path of the kiron field of\u000a   first.py>/kiron_pupil.db. My handle is <$ORCA_TERMINAL_HANDLE>. Run in\u000a   project.db: SELECT process FROM workflow WHERE step = 5;" and, if you do not use\u000a   orca, which tool you use and its commands; if there is none, that the\u000a   user will carry the messages between the two.\u000ad. Tell the user: "I opened the work agent of block <id> (<name>) in the\u000a   terminal ''work block <id>''. Work with it there; I am waiting for its close."\u000aEach orca send goes with --wait-submit 20; if it warns that the Enter may have been swallowed, repeat that same command adding the --retry-request <id> it gives (it never sends twice); never send probe or test messages. The orca commands are an example: if orca does not exist, look in your environment\u000afor an equivalent tool (one that creates a terminal with an agent, sends it\u000atext, closes it and gives you your own identifier) and adapt the commands; if\u000athere is none, tell the user the exact message and which agent to take it to,\u000aand wait. Without a tool, the user opens the work agent''s terminal\u000athemselves: give them the exact command from b, with KIRON_ROLE=work and KIRON_SKILL\u000ain front of claude and its --settings.\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 102;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(102,unistr('Row 102 of workflow — review of the CLOSE_DONE (2 of 3).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000ae. Wait for its CLOSE_DONE: it brings the justification for each point of the close.\u000a   Review it point by point; do not approve from memory or out of trust:\u000a     0. Run: python3 <skill folder>/scripts/last.py <path of project.db>\u000a        If it reports failures, they go in this round''s OBJECTION, along with\u000a        what you find in your review. If it reports nothing, continue.\u000a     1. handoff: it is faithful to what happened in the session and Done does not repeat\u000a        completed.\u000a     2. completed and missing: open the cited files and functions and\u000a        check that what each item says exists and matches.\u000a     3. pending: each action starts with a verb, is checked with yes or no\u000a        and does not duplicate missing.\u000a     4. psychology: you do not judge the observation; you require each one to be\u000a        justified with something seen in the session.\u000a     5. Patterns merged with replace(): read the analysis of its category in\u000a        kiron_pupil.db and check that the cited fragment exists and captures\u000a        the pattern.\u000a     6. Pouring and sync: nothing more; last.py checked them in point 0.\u000a   An unjustified point, a false citation or a vague or unclear\u000a   justification is something to fix. Review all points before replying and\u000a   send ALL that needs fixing in a single OBJECTION:\u000a     orca terminal send --terminal <work_handle> --text ''[principal →\u000a     work] block <id>: OBJECTION: <everything that needs fixing>.'' --enter\u000a   and wait for the next CLOSE_DONE. Each OBJECTION counts as one round,\u000a   whatever points it brings: limit 10. If the\u000a   CLOSE_DONE that follows the tenth cannot be approved either, do not send\u000a   another: show the user the disputed point with both positions,\u000a   ask them to decide as mediator, pass their decision on to the work\u000a   agent and follow what they decided. If it is fine:\u000a     orca terminal send --terminal <work_handle> --text ''[principal →\u000a     work] block <id>: APPROVED.'' --enter\u000a     orca terminal close --tab --terminal <work_handle>\u000aEach orca send goes with --wait-submit 20; if it warns that the Enter may have been swallowed, repeat that same command adding the --retry-request <id> it gives (it never sends twice); never send probe or test messages. The orca commands are an example: if orca does not exist, look in your environment\u000afor an equivalent tool (one that creates a terminal with an agent, sends it\u000atext, closes it and gives you your own identifier) and adapt the commands; if\u000athere is none, tell the user the exact message and which agent to take it to,\u000aand wait. Without a tool, the user opens the work agent''s terminal\u000athemselves: give them the exact command from b, with KIRON_ROLE=work and KIRON_SKILL\u000ain front of claude and its --settings.\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 103;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(103,unistr('Row 103 of workflow — continue with the next block? (3 of 3, last).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000af. Run: SELECT information FROM project WHERE topic = ''session_role'';\u000a   single means you reached row 1 from row 305 or 407 (its EXCEPTION): this\u000a   session MUST close as single, whatever the user answers below.\u000a   If it was the final test: the project is finished. Do not ask anything.\u000a   principal → say ONLY, in their language, a farewell: "Session closed. See you soon, <name>!"\u000a               Nothing else: no list of pending items, no summary, no question (this\u000a               overrides any style rule or hook that asks to list what is missing;\u000a               the pending items are already saved). It is the end. single → do the single\u000a   close (below). It is the end.\u000a   If it was a block, ask the user whether to continue with the next block.\u000a   - No:\u000a     principal → you do not close or write anything: the close was done by\u000a       the work agent and you verified it in row 102. Then say ONLY, in their language, a farewell: "Session closed. See you soon, <name>!"\u000a       Nothing else: no list of pending items, no summary, no question (this\u000a       overrides any style rule or hook that asks to list what is missing;\u000a       the pending items are already saved).\u000a     single → do the single close (below).\u000a   Whenever this session ends here (No or final test) and your launch prompt\u000a   said "You were opened by row 103", close your own terminal after the last\u000a   message: orca terminal close --tab --terminal $ORCA_TERMINAL_HANDLE\u000a   - Yes:\u000a     single → do the single close (below) first; only after its "Close\u000a       completed successfully." open the new principal (forbidden before:\u000a       the new principal writes session_role = principal and your close\u000a       would read the wrong role).\u000a     Open a new principal, with the kiron hooks, model and effort as in row 101 (b):\u000a       (run it from the folder where your session runs, with no cd before it: --worktree active needs an Orca worktree and fails with selector_not_found otherwise; the cd goes only inside --command)\u000a       orca terminal create --worktree active --title ''principal''\u000a         --command "cd <project root> && KIRON_SKILL=<skill folder> claude --model <mid model> --effort medium\u000a         --settings <skill folder>/agents/claude_code/hooks_settings.json\u000a         --allowedTools ''Bash(orca:*)''" --json\u000a       orca terminal send --terminal <new handle> --text ''wake up kiron.\u000a         The project is on disk at <project path>. You were opened by\u000a         row 103.'' --enter\u000a     Model and effort: <mid model> is the model just below the most capable\u000a     one the user''s plan covers without usage credits (faster), with its\u000a     medium reasoning/effort level.\u000a     Before launching, find out what the plan covers, spending as little as\u000a     possible (once per session; reuse it in later launches):\u000a     1. The plan: read it from your tool''s account or config, only the plan\u000a       fields; never print anything else of that file (example, Claude Code:\u000a       oauthAccount.organizationType and oauthAccount.hasExtraUsageEnabled of\u000a       ~/.claude.json, or $CLAUDE_CONFIG_DIR/.claude.json). If your tool does\u000a       not expose it, ask the user which plan they have.\u000a     2. Open the official pricing page of the tool''s provider and read its\u000a       table of models per plan, the column of the user''s plan (Claude:\u000a       the "Models and usage" table of https://claude.com/pricing). This page\u000a       is the only source: no web search and no other pages.\u000a     3. In that table, "Yes" or a share of the limits means covered; "Usage\u000a       credits" means it uses credits; "No" means it is not offered. If the\u000a       page cannot be read or the table is not there, FORBIDDEN to mark the\u000a       models as using credits: tell the user and ask them which models their\u000a       plan covers, with no recommendation.\u000a     Then ask the user with the selection tool, in their language:\u000a     "Which model do I launch the <role> with (effort medium)?" Options: the\u000a     models of the tool; first the recommended one, the covered model just\u000a     below the most capable covered one (if the plan covers only one, that\u000a     one), with "(recommended)" after its name; every model that uses credits\u000a     with "(uses credits)" after its name, never recommended; the user can\u000a     also write another one. Launch ONLY with the model the user chose.\u000a     FORBIDDEN to launch, try or relaunch on your own a model that uses\u000a     credits, or to accept a usage-credits prompt: if a launch still asks for\u000a     usage credits, close that terminal without doing anything else in it,\u000a     mark that model "(uses credits)" and ask again.\u000a     Example, Claude Code: --model <mid model> --effort medium, as in the command.\u000a     Another tool: its equivalent options (<skill folder>/agents/ADAPT.md,\u000a     section 3); if it does not let you choose, tell the user and use its\u000a     default.\u000a     and close yourself: orca terminal close --tab --terminal $ORCA_TERMINAL_HANDLE\u000a   The single close: go to kiron_pupil.db and run:\u000a     SELECT action FROM last WHERE step = 1;\u000a   and follow its whole chain (it ends with the external review).\u000aEach orca send goes with --wait-submit 20; if it warns that the Enter may have been swallowed, repeat that same command adding the --retry-request <id> it gives (it never sends twice); never send probe or test messages. The orca commands are an example: if orca does not exist, look in your environment\u000afor an equivalent tool (one that creates a terminal with an agent, sends it\u000atext, closes it and gives you your own identifier) and adapt the commands; if\u000athere is none, tell the user the exact message and which agent to take it to,\u000aand wait. Without a tool, the user opens the work agent''s terminal\u000athemselves: give them the exact command from b, with KIRON_ROLE=work and KIRON_SKILL\u000ain front of claude and its --settings.'));
INSERT INTO workflow VALUES(301,unistr('Row 301 of workflow — study PDF (1 of 5).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Count the records in reviews:\u000a     SELECT COUNT(*) FROM reviews;\u000a   If it returns 0, it is the first time: generate the study PDF (see "PDF\u000a   contents" below) in the project root, named study_concepts.pdf\u000a   (if there is no PDF tool, a study_concepts.md with the same\u000a   structure), and make the first record:\u000a     INSERT INTO reviews (concept_id, review, pdf_up_to)\u000a     VALUES (NULL, ''PDF generated: study_concepts.pdf. Concepts included: <ids>'',\u000a             <highest id of the pending concepts included>);\u000a   Tell the user to upload it to NotebookLM together with the official URLs at the\u000a   end, as support for their studies, wish them luck and tell them that you will\u000a   explain each need2learn concept and discuss it with them before asking them to\u000a   explain it (row 303), and that they can also study any other concept with you.\u000a   Studying with you is not a review and is not recorded in reviews. It ONLY counts as a review if the user asks you to\u000a   review it and explains the topic in general (what it is and how it works, the\u000a   criterion of row 304), not just what they have just studied:\u000a   then record it like any review (row 304). Otherwise, stay waiting\u000a   for them to tell you they want to start; then continue in row 302.\u000a   If they do not resume the session that day, it closes normally (last); on\u000a   returning, reviews already has rows and row 3 continues in row 302.\u000a   If it returns more than 0, continue in row 302.\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 302;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(302,unistr('Row 302 of workflow — outdated PDF (2 of 5).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Check whether the PDF became outdated (a new pending concept, due to\u000a   a spec change or discovered in the middle of development):\u000a     SELECT id, concept, level, basis, why FROM concepts\u000a     WHERE done = 0 AND id > (SELECT MAX(pdf_up_to) FROM reviews WHERE concept_id IS NULL);\u000a   If it returns rows:\u000a     a. Tell the user which concept or concepts were added.\u000a     b. Write, for each one, its section exactly as it will appear in the PDF (same\u000a        format; see "PDF contents") with the official URL of its\u000a        documentation, and give it to the user as text to paste into\u000a        NotebookLM as a source. That way the whole PDF does not have to be sent again.\u000a     c. Add those sections to the PDF in the root.\u000a     d. Record it:\u000a          INSERT INTO reviews (concept_id, review, pdf_up_to)\u000a          VALUES (NULL, ''PDF updated: added <concept(s)>'',\u000a                  <highest id of the pending concepts>);\u000a   If it returns no rows, the PDF is up to date.\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 303;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(303,unistr('Row 303 of workflow — pending ones and their last review (3 of 5).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. List the pending ones with their last review:\u000a     SELECT c.id, c.concept, c.level, r.reviewed_at, r.review\u000a     FROM concepts c\u000a     LEFT JOIN reviews r ON r.id = (SELECT MAX(id) FROM reviews WHERE concept_id = c.id)\u000a     WHERE c.done = 0\u000a     ORDER BY c.id;\u000a   review is the briefing of the previous review: how it was done, which detail\u000a   was missing and how to continue. If it is empty, the concept has no reviews.\u000a\u000a2. Before the first review, run:\u000a     SELECT COUNT(*) FROM reviews WHERE concept_id IS NOT NULL;\u000a   If it returns 0, there is no concept review yet: ask the\u000a   user, only once, whether they want to start the concept study now, and do not\u000a   start without their answer. If it returns\u000a   more than 0, do not ask.\u000a   Then, for the first pending one in the list, go to row 304. For each one, start from the briefing:\u000a   0. A need2learn concept with no review yet: the user may not know it, so never\u000a      ask them to explain it before this step. You explain it first, in plain\u000a      text, PART BY PART, ONE PART PER REPLY: before the first one, split it into\u000a      its parts (part 1: what it is and the problem it solves; then one part per\u000a      piece of how it works, such as each mechanism, pattern or tool the concept\u000a      names; with two or more pieces, a last part on how they fit together). Each\u000a      part: in general, with a small example and without project details, its\u000a      code shown as identity rule 7 says. Start each part with\u000a      its place ("Part 2 of 5: Protocol") and end it asking them to say when they\u000a      finish reading. In your next reply do the identity rule 17 check of THAT\u000a      part, with an option to go on to the next part; answer their doubts about\u000a      it as many times as needed, without evaluating and without recording\u000a      anything in reviews. Give the next part ONLY when they choose to go on or\u000a      say it is clear. FORBIDDEN to put two parts in the same reply or to give\u000a      the whole explanation at once, also when they ask you to redo it or show\u000a      the code: redo it part by part from part 1. After the last part, answer\u000a      their doubts and go to a ONLY when they say they can explain it.\u000a      Exceptions: if they say at any moment that they already know it, go to a.\u000a      If it is the first concept you reach in this session, you cannot know\u000a      whether it was explained before (the explanation is not recorded): first\u000a      ask with the selection tool, without saying it is new or a repeat, whether\u000a      you explain it or they explain it themselves.\u000a      MANDATORY in both selection questions (who explains, go on to the next\u000a      part): pass metadata {"source": "kiron_explain:<exact label of the option\u000a      that makes you explain>"} in the selection tool, so a hook gives you the\u000a      user''s profile again for the explanation (identity rule 2).\u000a   a. No review yet, or the last review starts with "Achieved": ask the user to\u000a      explain in their own words (without help) what it is and how it works, in\u000a      general, enough to be able to create the solution to the problem it solves.\u000a      In that same message tell them the criteria you will judge it with (rule 1\u000a      of row 304), as an indexed list of topics: each one names what to cover for\u000a      THIS concept, in general terms, without giving the answer and without\u000a      project details (files, values, spec decisions), and that minor details may\u000a      be missing. FORBIDDEN to ask only "explain it" and reveal the criteria afterwards.\u000a   b. The last review starts with "Not achieved": what it records as met counts.\u000a      Say so, and ask them to reformulate ONLY the failures it lists (rule 2 of\u000a      row 304), not the whole concept.\u000a   If it is partial, ask them first what they know and go deeper into what is\u000a   missing; if it is need2learn, insist until they internalize it.\u000a   FORBIDDEN to ask how the concept applies to the project or about an architecture\u000a   decision, even one the spec already made: that is not a criterion (row 304,\u000a   rule 5 explains it to them afterwards). Techniques (proven scientific basis): retrieval\u000a   practice and self-explanation.\u000a\u000aIf the list returns rows: ONLY when you have done the above, run\u000a  SELECT process FROM workflow WHERE step = 304;   (review of the first one)\u000aIf it returns no rows: run\u000a  SELECT process FROM workflow WHERE step = 305;   (end of the study)\u000aForbidden to run those queries before finishing this row.'));
INSERT INTO workflow VALUES(304,unistr('Row 304 of workflow — review of a concept (4 of 5).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Criterion: the review is achieved when it covers what it is and how it works, in\u000a   general, enough to be able to create the solution to the problem it solves,\u000a   with nothing said wrong; minor details may be missing if they show they know\u000a   what it is and how it works. How it applies to the project and architecture\u000a   decisions are not a criterion: never judge them or count them as a failure.\u000a   The user already knows these criteria: row 303 tells them before they explain.\u000a\u000a2. What they said well counts and is never asked again. A failure is a missing\u000a   criterion or something said wrong. If there are failures: first tell them\u000a   what they said well, then correct each failure and help them understand it\u000a   (explain it in your reply as plain text, with the identity rule 17 check in\u000a   your next reply), and then ask them to reformulate ONLY the failures, in their\u000a   own words. When they reformulate them correctly the review is achieved\u000a   (rule 3), without repeating the rest, the same day or another day. If a reformulation still fails, what they got right now also counts and\u000a   only what still fails is asked again.\u000a\u000a3. Record each attempt right away (an explanation or a reformulation), so nothing\u000a   is lost if the session closes:\u000a     INSERT INTO reviews (concept_id, review, score)\u000a     VALUES (<id>, ''<text>'', <score>);\u000a   Not achieved: score = 0; text = "Not achieved. Met: <what they said well>. To\u000a   reformulate: <each failure, with the correction>".\u000a   Achieved: score = 1; text = "Achieved: <how it went, minor details left>".\u000a\u000a4. One achieved review is enough: with score 1 a trigger marks the concept as\u000a   studied (concepts.done = 1) and a need2learn becomes partial. There is no\u000a   second review. Do not write concepts.done by hand (only exception: rule 11\u000a   of row 3, the user moving on).\u000a\u000a5. Closing the concept, ONLY when the review was achieved. Never explain on your\u000a   own how the concept applies to this project: that is only option c below.\u000a   If there are minor details left, tell them in your reply as plain text and\u000a   end asking them to say when they finish reading; the question goes in your\u000a   next reply. Otherwise ask it in this same reply. Read the concepts already\u000a   studied:\u000a     SELECT id, concept FROM concepts WHERE done = 1 AND level <> ''agent'' AND id <> <id>;\u000a   and check whether the concept just studied really relates to any of them\u000a   (never invent a relation; there may be none). Ask\u000a   with the selection tool. Exception to the rule of explaining before asking:\u000a   the question text itself states the relation, in one concrete line. Options,\u000a   in their language:\u000a     a. Go deeper into the relation with <concept>: only if there is a real one,\u000a        at most the two strongest.\u000a     b. Review an earlier concept: only if there is one studied.\u000a     c. How this concept applies to this project.\u000a     d. I have a doubt about this concept or an earlier one.\u000a     e. Move on to the next concept.\u000a   Option a is one option even with two relations. If the options exceed what\u000a   the selection tool allows (Claude Code: 4), join b and d in one option.\u000a   FORBIDDEN to recommend any option or push them to move on.\u000a   Handle what they choose:\u000a     a. Explain the relation in your reply as plain text (identity rule 17).\u000a     b. Ask which one if they did not say, ask them to explain what it is and\u000a        how it works, and correct what fails right there.\u000a     c. Explain in your reply, as plain text, how the concept applies to this\u000a        project, from the spec: separate what the spec already decided from what\u000a        is still open and in which phase it is decided. Never present something\u000a        open as decided and do not decide it here (if the user decides it, rule\u000a        12 of row 3). Do not ask about it or evaluate it; end asking them to say\u000a        when they finish reading.\u000a     d. Ask for the doubt as text in your reply and answer it.\u000a   Nothing here is recorded in reviews, and a failure here does not reopen the\u000a   concept: it stays studied. After each one ask the same question again, until\u000a   they choose to move on.\u000a\u000aONLY when you have recorded the review of this concept and, if it was achieved,\u000athey chose to move on, run in project.db:\u000a  SELECT process FROM workflow WHERE step = 303;\u000a(list the pending ones again; 303 sends you to the next one or to 305).\u000aForbidden to skip the record or to review two concepts in a single pass.'));
INSERT INTO workflow VALUES(305,unistr('Row 305 of workflow — end of the study (5 of 5, last).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. You arrive here because row 303 returned no pending ones: the study is finished.\u000a   run SELECT process FROM workflow WHERE step = 1; and follow the\u000a   done = true branch from the concepts query. With 0 pending ones, row 1\u000a   decides whether it moves on to the division into blocks (row 4) or launches the work\u000a   agent.\u000a   You arrive at row 1 from 305: its session_role EXCEPTION applies to you\u000a   (forbidden to run [PRINCIPAL]; this session closes as single).\u000a   The level in kiron_pupil.db (knowledge) is not touched here: it is updated at\u000a   project close, with skill_evidence.'));
INSERT INTO workflow VALUES(401,unistr('Row 401 of workflow — resume (1 of 7).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Resume. Look for block_division.md in the project root.\u000a   - If it exists: read it and run, with the file''s "coherence" date:\u000a       SELECT COALESCE(MAX(d) >= ''<coherence>'', 0) AS repeat FROM (\u000a         SELECT updated_at AS d FROM spec UNION ALL SELECT updated_at FROM prohibitions\u000a         UNION ALL SELECT updated_at FROM constraints UNION ALL SELECT updated_at FROM goals\u000a         UNION ALL SELECT updated_at FROM descriptions UNION ALL SELECT updated_at FROM concepts);\u000a     If it returns 1, continue in row 402. If it returns 0, resume from the\u000a     "Pending" and "Decided" lists in the file: continue in row 403.\u000a   - If it does not exist and blocks_division = in_progress, the file was lost but\u000a     the blocks are already registered. Rebuild it with:\u000a       SELECT id, name, definition, state FROM blocks ORDER BY id;\u000a       SELECT block_id, depends_on_id FROM block_deps ORDER BY block_id;\u000a     Each row of blocks goes into the Blocks section (its definition brings what it\u000a     receives, processes and delivers); the Mermaid comes from block_deps. Leave\u000a     "coherence" empty (it is not known when the last one was), continue in row 402 and,\u000a     when you finish it, jump to 405 (the blocks are already registered).\u000a   - If it does not exist and blocks_division = not_started: create it with the header\u000a     (date, coherence) and the sections Blocks, Diagram (Mermaid),\u000a     Decided and Pending, and continue in row 402.\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db the query of the branch you got:\u000a  coherence due (row 402)      → SELECT process FROM workflow WHERE step = 402;\u000a  you resume without coherence → SELECT process FROM workflow WHERE step = 403;\u000aForbidden to run it before finishing this row or to skip a row.'));
INSERT INTO workflow VALUES(402,unistr('Row 402 of workflow — coherence (2 of 7).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Coherence. Read the spec and the five pouring tables in full:\u000a     SELECT information FROM spec WHERE topic = ''spec'';\u000a     SELECT * FROM prohibitions;  SELECT * FROM constraints;\u000a     SELECT * FROM goals;  SELECT * FROM descriptions;  SELECT * FROM concepts;\u000a   Apply the Coherence block of:\u000a     SELECT information FROM spec WHERE topic = ''instructions'';\u000a   All fine: say "coherence OK", write today''s date in the file''s "coherence"\u000a   and continue. Something wrong: one problem per message, with the exact row and the\u000a   concrete case that proves it; propose the fix and the user decides\u000a   (apply, modify or discard); edit the pouring row; when the list is\u000a   finished repeat this whole step until it comes out clean. If the error is in\u000a   the spec itself, edit it anyway: editing it reopens the spec, which takes you\u000a   out of this row, and row 1 picks up the flow.\u000a\u000aONLY when coherence comes out clean, run in project.db:\u000a  SELECT process FROM workflow WHERE step = 403;\u000aunless you come from rebuilding block_division.md (row 401): then\u000a  SELECT process FROM workflow WHERE step = 405;\u000aForbidden to run it before coherence comes out clean.'));
INSERT INTO workflow VALUES(403,unistr('Row 403 of workflow — propose and decide the blocks (3 of 7).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Ask the user whether they want to propose the division (yes or no).\u000a   - Yes: tell them they can ask you whatever they want about what is recorded in spec,\u000a     prohibitions, constraints, goals, descriptions and concepts. They propose the\u000a     full list of blocks with their purpose, or block by block; you\u000a     contrast it with what is recorded and with your knowledge, one point per message,\u000a     pushing them to participate, internalize and propose.\u000a   - No: you make a global proposal for the project and then block by block,\u000a     each one with its rationale; they approve, modify or discard each one.\u000a\u000aApply rules 4, 5 and 6 of row 4 to each block. Stay here until\u000athe full list of blocks is approved by the user.\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 404;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(404,unistr('Row 404 of workflow — register the blocks (4 of 7).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Register. With the full list approved, insert the blocks in build\u000a   order and their dependencies (the first INSERT moves blocks_division to\u000a   in_progress by trigger):\u000a     INSERT INTO blocks (name, definition) VALUES (''<name>'', ''<what it receives, processes and delivers>'');\u000a     INSERT INTO block_deps (block_id, depends_on_id) VALUES (<block>, <the one it depends on>);\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 405;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(405,unistr('Row 405 of workflow — verify the division (5 of 7).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Verify, noting it in the file. All four, as yes/no:\u000a   c1. Each row of goals has a path of blocks from its input to\u000a       its result.\u000a   c2. Everything a block receives comes from another block or from a declared\u000a       external input.\u000a   c3. Everything it delivers is consumed by another block or is a declared final output.\u000a   c4. Run, and the user confirms each row:\u000a         SELECT id FROM blocks WHERE id NOT IN (SELECT block_id FROM block_deps);\u000a         SELECT id FROM blocks WHERE id NOT IN (SELECT depends_on_id FROM block_deps);\u000a   Then, for each row of goals, follow a concrete piece of data through the blocks,\u000a   one by one, and point out where it does not fit, in case something does not fit.\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 406;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(406,unistr('Row 406 of workflow — scaffold (6 of 7).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Scaffold. With the blocks registered and verified, propose the file\u000a   structure of each block. First look at which blocks already have it:\u000a     SELECT id, files FROM blocks ORDER BY id;   (files not empty = already done)\u000a   For the rest, read:\u000a     SELECT id, definition FROM blocks ORDER BY id;\u000a     SELECT information FROM spec WHERE topic = ''spec'';  (technologies point)\u000a   Split it following the good practices of the project''s technology (for\u000a   example, in a REST API: routes, schemas, services and models) and state in each\u000a   split which practice you follow. Show the full tree and the user\u000a   accepts, edits or discards each file. Content of each file: ONLY the\u000a   names of the files and of the classes, with a one-line docstring (what it\u000a   receives, processes and delivers, taken from the block''s definition); no method\u000a   signatures or logic. With what was accepted:\u000a   a. Create the files and folders in the project root, without\u000a      overwriting anything that already exists. Also create the tests folders\u000a      required by the technology''s practice, empty: the tests are created later by the\u000a      tests agent of each block.\u000a   b. Register the paths of each block, relative to the root and separated by\u000a      commas:\u000a        UPDATE blocks SET files = ''<path1>,<path2>'' WHERE id = <id>;\u000a   c. Note it in block_division.md.\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 407;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(407,unistr('Row 407 of workflow — close of the division (7 of 7, last).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Close. ONLY when the user says so and everything is at yes:\u000a     UPDATE project SET information = ''done'' WHERE topic = ''blocks_division'';\u000a   Then run SELECT process FROM workflow WHERE step = 1; (row 1\u000a   launches the work agent).\u000a   You arrive at row 1 from 407: its session_role EXCEPTION applies to you\u000a   (forbidden to run [PRINCIPAL]; this session closes as single).'));
INSERT INTO workflow VALUES(501,unistr('Row 501 of workflow — who you are and who you work with (1 of 10).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Who you are and who you work with. Go to kiron_pupil.db and run:\u000a     SELECT action FROM first WHERE step = 1;\u000a   They are your rules (identity): unbreakable, in every answer.\u000a     SELECT topic, information FROM pupil WHERE topic NOT IN (''state'', ''psychology_review'');\u000a   Call the user by their name and speak to them in their language. The rest of the rows are\u000a   their knowledge: explain starting from what they already know.\u000a     SELECT kind, analysis FROM psychology;\u000a   Apply it silently to how you explain and communicate; do not mention it or\u000a   recite it, unless the user asks.\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 502;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(502,unistr('Row 502 of workflow — the block and its context (2 of 10).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. The block and its context. In project.db run:\u000a   a. SELECT id, name, definition, acceptance, state, missing, completed, diagram,\u000a        outputs, files FROM blocks WHERE id = <id>;\u000a   b. What its dependencies deliver to you:\u000a        SELECT b.id, b.name, b.definition, b.outputs FROM block_deps d\u000a        JOIN blocks b ON b.id = d.depends_on_id WHERE d.block_id = <id>;\u000a   c. The handoff:\u000a        SELECT id, kind, handoff, date FROM handoff\u000a        WHERE id >= COALESCE((SELECT MAX(id) FROM handoff WHERE kind = ''closed''), 0)\u000a        ORDER BY id;\u000a      The last open row is your session (the principal opened it when launching you): ignore it.\u000a      - closed: summary of the previous session (what was done and what was not, what was\u000a        decided and discarded). If it starts with "block <id>" (this block), resume\u000a        from the missing of 2a and the pending items below. If it is from another block,\u000a        it is only context.\u000a      - interrupted: the previous session was closed without a handoff. Tell the user: "The\u000a        previous session was closed without a handoff; I am rebuilding from the state of the\u000a        block." Its text is a snapshot of blocks (blocks and their state):\u000a        compare it with 2a and with the code of files, rebuild what was done and\u000a        confirm it with the user before continuing.\u000a      Also read the pending items that the previous sessions left; together\u000a      with the handoff, it is the list of where everything was left:\u000a        SELECT id, description, date FROM pending WHERE done = 0 ORDER BY id;\u000a   d. SELECT concept FROM concepts WHERE level = ''partial'' OR skipped = 1;\u000a      (skipped = 1: the user moved on without finishing its study.)\u000a      When the block uses any of them, keep it in mind when explaining, making them\u000a      internalize those concepts more and reinforcing them in practice, without warning.\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 503;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(503,unistr('Row 503 of workflow — method (3 of 10).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Method. Ask the user how they want to work (ai_first or hybrid),\u000a   offering as the first option the one noted in the last closed handoff, and run:\u000a     SELECT instructions FROM work_methods WHERE method = ''<method chosen by the user>'';\u000a   That instruction governs how the code is written in row 506.\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 504;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(504,unistr('Row 504 of workflow — acceptance criterion and diagram (4 of 10).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Acceptance criterion. ONLY if acceptance is empty (row 502, a); if not, do nothing here and go to the end of the row.\u000a   a. From the definition and the outputs of the dependencies, propose\u000a      one check per message; the user approves, edits or discards each one:\u000a      - MUST: up to 5, what the block does.\u000a      - MUST NOT: up to 5, what it cannot do.\u000a      - Each one 100% verifiable by a test: yes/no or number with a threshold. Never\u000a        "works well" or "is robust".\u000a      - Word the MUSTs so that they also cover what would be a MUST NOT ("only\u000a        accepts X" instead of "accepts X": it says what it accepts and that it rejects everything\u000a        else); the MUST NOTs are left only for what could not be covered.\u000a   b. Cut rule: if more than 5 MUST or more than 5 MUST NOT are needed, the block\u000a      does not fit in one session. Propose where to split it (name and what each part\u000a      receives, processes and delivers) and, with the user''s approval, run:\u000a        UPDATE blocks SET name = ''<name>'', definition = ''<part that stays>''\u000a          WHERE id = <id>;\u000a        INSERT INTO blocks_at (position, name, definition)\u000a          VALUES (<id> + 1, ''<name>'', ''<the other part>'');\u000a        INSERT INTO block_deps (block_id, depends_on_id) VALUES (<id> + 1, <id>);\u000a      blocks_at overwrites nothing: the new part takes <id> + 1 and all the blocks\u000a      from <id> + 1 go up one number, with their dependencies. Check who\u000a      depended on this block:\u000a        SELECT block_id FROM block_deps WHERE depends_on_id = <id>;\u000a      and, for each one that needs the new part, run:\u000a        INSERT INTO block_deps (block_id, depends_on_id) VALUES (<dependent>, <id> + 1);\u000a      Update block_division.md at that moment: the new block with its name,\u000a      definition and dependencies, the following blocks renumbered and the\u000a      Mermaid diagram redrawn, so that it matches:\u000a        SELECT id, name, definition FROM blocks ORDER BY id;\u000a        SELECT block_id, depends_on_id FROM block_deps;\u000a      Continue with a for the part that stays.\u000a   c. With everything approved:\u000a        UPDATE blocks SET acceptance = ''MUST:\u000a        1. <…>\u000a        MUST NOT:\u000a        1. <…>'' WHERE id = <id>;\u000a      The database moves the block to in_progress. If it answers "blocks: its dependencies\u000a      are not done", nothing was saved: notify the user and the principal:\u000a        orca terminal send --terminal <principal_handle> --text ''[work →\u000a        principal] block <id>: WAIT_DEPS: its dependencies are not in done.'' --enter\u000a      and do not continue: do not run the query of the next row.\u000a   d. Mermaid diagram: input (from which dependency or source each piece of data arrives),\u000a      process (the steps of the block) and output (what it delivers and to whom). With the\u000a      user''s approval:\u000a        UPDATE blocks SET diagram = ''<mermaid>'' WHERE id = <id>;\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 505;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(505,unistr('Row 505 of workflow — what is missing (5 of 10).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Run in project.db:\u000a     SELECT missing, completed FROM blocks WHERE id = <id>;\u000a   If either of the two has data, it was already done: do nothing here and go to the\u000a   end of the row.\u000a2. If both are NULL, propose the complete list of what has to be built\u000a   to meet each line of acceptance and each step of diagram (functions,\u000a   classes, structures…), one line per element. The user approves, edits\u000a   or discards each line. With the approved list:\u000a     UPDATE blocks SET missing = ''<list>'' WHERE id = <id>;\u000a3. Check by rereading: SELECT missing FROM blocks WHERE id = <id>;\u000aFrom here on, each element moves from missing to completed when resolved, and everything\u000athat appears and has to be resolved is added to missing at that moment\u000a(row 506, d). The database does not allow verifying the block with completed empty.\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 506;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(506,unistr('Row 506 of workflow — construction (6 of 10).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Construction, according to the method of row 503. While you build, always:\u000a   a. If a concept or tool appears that is not in concepts, go to\u000a      kiron_pupil.db and run:\u000a        SELECT level FROM knowledge WHERE skill = ''<concept>'';\u000a      If it is there, propose the row with that level. If not, propose it with need2learn or\u000a      agent and, once approved, run in kiron_pupil.db:\u000a        INSERT INTO knowledge (skill, level) VALUES (''<concept>'', ''<level>'');\u000a      In project.db:\u000a        INSERT INTO concepts (concept, level, basis, why)\u000a        VALUES (''<concept>'', ''<level>'', ''block <id>'', ''<what it is needed for>'');\u000a      If it is need2learn, notify the user: the next start of the project\u000a      sends them to study it (row 3) before continuing with the blocks.\u000a   b. If a code change stops matching what is written, update it at that\u000a      moment:\u000a        what it receives, processes or delivers → UPDATE blocks SET definition = ''<…>'' WHERE id = <id>;\u000a        the flow                                → UPDATE blocks SET diagram = ''<…>'' WHERE id = <id>;\u000a        new, deleted or renamed files\u000a                                                → UPDATE blocks SET files = ''<path1>,<path2>'' WHERE id = <id>;\u000a        (paths relative to the project root)\u000a        public outputs already described        → UPDATE blocks SET outputs = ''<…>'' WHERE id = <id>;\u000a      No trigger detects a code change: if you do not update it, the database\u000a      lies.\u000a   c. Each time you fulfill a pending item from row 502 (c), mark it at that moment (the\u000a      table sets the fulfillment date):\u000a        UPDATE pending SET done = 1 WHERE id = <id>;\u000a   d. Progress of the block, at that moment, each time something is built and\u000a      tested in some way or something missing appears:\u000a        SELECT completed, missing FROM blocks WHERE id = <id>;\u000a      completed: everything that exists in the code of the block and was tested\u000a      (functions, classes, structures…), one line per element:\u000a        <name> — <how it was tested>\u000a      Start from the current list: add what is new, correct what was renamed and remove\u000a      what no longer exists in the code.\u000a      missing: what is missing to close the block, one line per element\u000a      (it was born in row 505 with everything planned). Every new pending item that\u000a      appears and has to be resolved to close the block is added to missing\u000a      at the moment it appears, without waiting for the close. What is no longer missing,\u000a      remove it from missing and move it to completed. With nothing missing, NULL.\u000a        UPDATE blocks SET completed = ''<list>'', missing = ''<list or NULL>''\u000a        WHERE id = <id>;\u000a      With the block in done the database rejects writing them: they are only reopened if\u000a      the block is reopened.\u000a\u000aYou stay in this row while you build. You move to the next one ONLY when the\u000auser and you consider that the code meets each line of acceptance and\u000amissing is NULL (the database does not allow verifying a block that is missing something).\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 507;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(507,unistr('Row 507 of workflow — outputs and launch of the tests agent (7 of 10).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000aClose of the block (the same in ai_first and hybrid): outputs and tests agent.\u000aa. outputs: each public method and structure of the block, with its name, what it\u000a   returns (type and shape) and in which cases it fails. With the user''s approval:\u000a     UPDATE blocks SET outputs = ''<…>'' WHERE id = <id>;\u000ab. Create the tests folder of the block (if it already exists, do not touch it):\u000a     mkdir -p <root>/<tests folder>/<name of the block>/\u000a   Write what the tester may see in that folder, in .tests_context.txt\u000a   (it reads nothing else of the project):\u000a     sqlite3 -readonly -header <path of project.db> <<''SQL'' > <root>/<tests folder>/<name of the block>/.tests_context.txt\u000a     SELECT process FROM workflow WHERE step = 6;\u000a     SELECT definition, acceptance, outputs FROM blocks WHERE id = <id>;\u000a     SELECT b.id, b.outputs FROM block_deps d JOIN blocks b\u000a       ON b.id = d.depends_on_id WHERE d.block_id = <id>;\u000a     SELECT * FROM constraints;  SELECT * FROM prohibitions;  SELECT * FROM descriptions;\u000a     SQL\u000a   Launch the tests agent (its own agent in another terminal, not a subagent),\u000a   inside that folder and with permission ONLY for messaging and for reading\u000a   and writing in that folder; the launch enforces it (reads outside the\u000a   folder blocked, any other tool denied):\u000a     (run it from the folder where your session runs, with no cd before it: --worktree active needs an Orca worktree and fails with selector_not_found otherwise; the cd goes only inside --command)\u000a     orca terminal create --worktree active --title ''tests block <id>''\u000a       --command "cd <root>/<tests folder>/<name of the block> && claude\u000a       --model <top model> --effort high --permission-mode dontAsk\u000a       --settings <skill folder>/agents/claude_code/tester_settings.json" --json\u000a   Blindness, enforced by the launch: the tester starts inside its folder and\u000a   may only read and write there and send messages; everything else is denied\u000a   without asking. Claude Code: --permission-mode dontAsk --settings <skill\u000a   folder>/agents/claude_code/tester_settings.json, as in the command; if you\u000a   send messages with a tool other than orca, add --allowedTools\u000a   ''Bash(<tool>:*)''. Another tool: use (or create, the first time) its adapter\u000a   in <skill folder>/agents/<your tool>/ following <skill\u000a   folder>/agents/ADAPT.md, section 2.\u000a   Model and effort: <top model> is the most capable model the user''s plan\u000a   covers without usage credits, with its high reasoning/effort level.\u000a   Before launching, find out what the plan covers, spending as little as\u000a   possible (once per session; reuse it in later launches):\u000a   1. The plan: read it from your tool''s account or config, only the plan\u000a     fields; never print anything else of that file (example, Claude Code:\u000a     oauthAccount.organizationType and oauthAccount.hasExtraUsageEnabled of\u000a     ~/.claude.json, or $CLAUDE_CONFIG_DIR/.claude.json). If your tool does\u000a     not expose it, ask the user which plan they have.\u000a   2. Open the official pricing page of the tool''s provider and read its\u000a     table of models per plan, the column of the user''s plan (Claude:\u000a     the "Models and usage" table of https://claude.com/pricing). This page\u000a     is the only source: no web search and no other pages.\u000a   3. In that table, "Yes" or a share of the limits means covered; "Usage\u000a     credits" means it uses credits; "No" means it is not offered. If the\u000a     page cannot be read or the table is not there, FORBIDDEN to mark the\u000a     models as using credits: tell the user and ask them which models their\u000a     plan covers, with no recommendation.\u000a   Then ask the user with the selection tool, in their language: "Which model\u000a   do I launch the <role> with (effort high)?" Options: the models of the\u000a   tool; first the recommended one, the most capable covered model, with\u000a   "(recommended)" after its name; every model that uses credits with\u000a   "(uses credits)" after its name, never recommended; the user can also write\u000a   another one. Launch ONLY with the model the user chose. FORBIDDEN to\u000a   launch, try or relaunch on your own a model that uses credits, or to accept\u000a   a usage-credits prompt: if a launch still asks for usage credits, close\u000a   that terminal without doing anything else in it, mark that\u000a   model "(uses credits)" and ask again.\u000a   Example, Claude Code: --model <top model> --effort high, as in the command. Another\u000a   tool: its equivalent options (<skill folder>/agents/ADAPT.md, section 3);\u000a   if it does not let you choose, tell the user and use its default.\u000a   Save the handle it returns (<tests_handle>) and send it the prompt:\u000a     orca terminal send --terminal <tests_handle> --text ''<prompt>'' --enter\u000a   The prompt carries: "You are the tests agent of block <id>. Your goal is\u000a   to break it with realistic edge cases from the project''s own flow. Read\u000a   .tests_context.txt in your folder: it starts with your row (step 6).\u000a   Path of project.db, only for the automatic close: <path>."\u000a   plus the path of the tests folder already created (<root>/<tests\u000a   folder>/<name of the block>/), the id <id>, "My handle is\u000a   <$ORCA_TERMINAL_HANDLE>", "Tests language: <English, unless the user asked\u000a   for another>" and, if you do not use orca, which tool you use and its\u000a   commands to send messages. Never pass it diagram or files, nor\u000a   explain to it how the code works: it works ONLY with outputs. The tester\u000a   writes the tests; it does not run them.\u000a\u000aONLY when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 508;\u000aForbidden to run that query before finishing this row, to skip a row or\u000ato do the work of another row here.'));
INSERT INTO workflow VALUES(508,unistr('Row 508 of workflow — review and execution of the tests (8 of 10).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000ac. When you receive its TESTS_READY message, review its tests: that each line of acceptance\u000a   has at least one test, that they are coherent with how the\u000a   code is built and that they really stress it without being unnecessary. If something has to be\u000a   fixed, return it saying which test and why, without revealing the code:\u000a     orca terminal send --terminal <tests_handle> --text ''[work → tests]\u000a     block <id>: FIX: <test>: <why>.'' --enter\u000a   If it sends you QUESTION, answer it without revealing how the code is made:\u000a     orca terminal send --terminal <tests_handle> --text ''[work → tests]\u000a     block <id>: ANSWER: <…>.'' --enter\u000a   With the tests approved, you add the imports and run them with the tester\u000a   still open. If any fails, check whether the failure is in the test or in the\u000a   code; a badly written test you return to the tester and you run it\u000a   again.\u000a   Round: each time you return a test to the tester because it is badly written\u000a   and does not match how the block works (in the review or after\u000a   running it); nothing else counts as a round. Maximum 10. On\u000a   reaching 10, close the tester, delete everything it created inside its folder (the folder stays) and launch another one (row 507, b).\u000a   If the second one also reaches 10, close it, delete everything it created,\u000a   analyze all the possibilities and propose to the user the 3 best\u000a   fixes; they decide.\u000a   Outside those two cases, close the tester ONLY when everything passed (row 510) or\u000a   when the only thing failing is the code (row 509). Closing it is always:\u000a     orca terminal close --tab --terminal <tests_handle>\u000a     rm <root>/<tests folder>/<name of the block>/.tests_context.txt\u000a\u000aONLY when you have run the approved tests, run in project.db:\u000a  everything passed                    → SELECT process FROM workflow WHERE step = 510;\u000a  the only thing failing is the code   → SELECT process FROM workflow WHERE step = 509;\u000aForbidden to run them before running the approved tests.'));
INSERT INTO workflow VALUES(509,unistr('Row 509 of workflow — the code fails (9 of 10).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000ad. If the only thing failing is the code: close the tester and keep its tests\u000a   (they are fine). Review the errors.\u000a   Write the report, in the user''s language, overwriting it if it exists:\u000a     <root>/<tests folder>/<name of the block>/TESTS_REPORT.md\u000a     # <name of the block>\u000a     ## TESTS:\u000a     ### <n>. <short description of the cause>\u000a     - Line that breaks it: <file>:<line> → <the code of that line>\u000a     - Why: <the cause, e.g. a ValueError not handled with try/except>\u000a     - Failing tests:\u000a       - <test name> (<its source: acceptance MUST 2, outputs…>): <what broke, in one\u000a         sentence>. <function> was given <argument> (the exact call) →\u000a         <actual output: the error or the wrong result, as printed>\u000a   One section per cause: the failing tests that share the same line and\u000a   the same why go together in one section, each with its own call and\u000a   output. The labels go in the user''s language, except "TESTS:".\u000a   Never the fix: no corrected code and no solution, the user solves it\u000a   working with you. Tell the user the path of the file.\u000a   Each run that still fails rewrites it with the current failures; when\u000a   all pass, add at the end: "Resolved: all tests pass (<date>)."\u000a   You decide the fix together, you fix according to the method and you run the\u000a   same tests again.\u000a\u000aONLY when the same tests pass at 100%, run in project.db:\u000a  SELECT process FROM workflow WHERE step = 510;\u000aForbidden to run it while any test fails.'));
INSERT INTO workflow VALUES(510,unistr('Row 510 of workflow — block closed (10 of 10, last).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000ae. At 100%, the automatic close of the tests sets the three booleans and the database moves the\u000a   block to done. Check it:\u000a     SELECT state FROM blocks WHERE id = <id>;\u000a   If it is done, close the tester if it is still open, say "Block id: <id> name: <name> closed and functional" and\u000a   recommend closing the session.\u000a\u000aThis is the last work row of the block. If the user does not close the session,\u000astay available; the close is done with last (rule of row 5).'));
INSERT INTO workflow VALUES(701,unistr('Row 701 of workflow — handoff and context (1 of 6).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Handoff. The principal already opened your handoff row when it launched you.\u000a    a. Read where the project was left:\u000a         SELECT id, kind, handoff, date FROM handoff\u000a         WHERE id >= COALESCE((SELECT MAX(id) FROM handoff WHERE kind = ''closed''), 0)\u000a         ORDER BY id;\u000a         SELECT id, description, date FROM pending WHERE done = 0 ORDER BY id;\u000a       - closed: summary of the previous session. If it starts with "final test", it\u000a         is a previous session of this row: resume from its pending items and from\u000a         the step where it stopped, without repeating what was done. If not, it is only context.\u000a       - open or interrupted after the closed one: the previous session closed\u000a         without a handoff. Tell the user, rebuild with the snapshot, the state\u000a         of blocks and the test table (SELECT phase, test, outcome FROM test;) and\u000a         confirm it with them before continuing.\u000a    b. The same context as the final tester, to be able to evaluate their tests:\u000a         SELECT information FROM spec WHERE topic = ''spec'';\u000a         SELECT id, statement, basis, why, constraint_id FROM goals;\u000a         SELECT id, statement, basis, why FROM constraints;\u000a         SELECT id, statement, basis, why FROM prohibitions;\u000a         SELECT id, statement, basis, why FROM descriptions;\u000a         SELECT id, name, definition, outputs FROM blocks ORDER BY id;\u000a         SELECT block_id, depends_on_id FROM block_deps ORDER BY block_id;\u000a\u000aOnly when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 702;\u000aForbidden to run that query before finishing this row, to skip a row or to\u000ado the work of another row here.'));
INSERT INTO workflow VALUES(702,unistr('Row 702 of workflow — launch the final tests agent (2 of 6).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Create the folder for the final tests (if it already exists, do not touch it):\u000a      mkdir -p <root>/<tests folder>/final/individual/ <root>/<tests folder>/final/scenarios/\u000a    Write what the tester may see in that folder, in .tests_context.txt\u000a    (it reads nothing else of the project):\u000a      sqlite3 -readonly -header <path of project.db> <<''SQL'' > <root>/<tests folder>/final/.tests_context.txt\u000a      SELECT process FROM workflow WHERE step = 8;\u000a      SELECT information FROM spec WHERE topic = ''spec'';\u000a      SELECT id, statement, basis, why, constraint_id FROM goals;\u000a      SELECT id, statement, basis, why FROM constraints;\u000a      SELECT id, statement, basis, why FROM prohibitions;\u000a      SELECT id, statement, basis, why FROM descriptions;\u000a      SELECT id, name, definition, outputs FROM blocks ORDER BY id;\u000a      SELECT block_id, depends_on_id FROM block_deps ORDER BY block_id;\u000a      SQL\u000a    Launch the final tests agent (its own agent in another terminal),\u000a    inside final/ and with permission only for messaging and for reading and\u000a    writing in that folder; the launch enforces it (reads outside the folder\u000a    blocked, any other tool denied):\u000a      (run it from the folder where your session runs, with no cd before it: --worktree active needs an Orca worktree and fails with selector_not_found otherwise; the cd goes only inside --command)\u000a      orca terminal create --worktree active --title ''final tests''\u000a        --command "cd <root>/<tests folder>/final && claude\u000a        --model <top model> --effort high --permission-mode dontAsk\u000a        --settings <skill folder>/agents/claude_code/tester_settings.json" --json\u000a    Blindness, enforced by the launch: the tester starts inside its folder and\u000a    may only read and write there and send messages; everything else is denied\u000a    without asking. Claude Code: --permission-mode dontAsk --settings <skill\u000a    folder>/agents/claude_code/tester_settings.json, as in the command; if you\u000a    send messages with a tool other than orca, add --allowedTools\u000a    ''Bash(<tool>:*)''. Another tool: use (or create, the first time) its adapter\u000a    in <skill folder>/agents/<your tool>/ following <skill\u000a    folder>/agents/ADAPT.md, section 2.\u000a    Model and effort: <top model> is the most capable model the user''s plan\u000a    covers without usage credits, with its high reasoning/effort level.\u000a    Before launching, find out what the plan covers, spending as little as\u000a    possible (once per session; reuse it in later launches):\u000a    1. The plan: read it from your tool''s account or config, only the plan\u000a      fields; never print anything else of that file (example, Claude Code:\u000a      oauthAccount.organizationType and oauthAccount.hasExtraUsageEnabled of\u000a      ~/.claude.json, or $CLAUDE_CONFIG_DIR/.claude.json). If your tool does\u000a      not expose it, ask the user which plan they have.\u000a    2. Open the official pricing page of the tool''s provider and read its\u000a      table of models per plan, the column of the user''s plan (Claude:\u000a      the "Models and usage" table of https://claude.com/pricing). This page\u000a      is the only source: no web search and no other pages.\u000a    3. In that table, "Yes" or a share of the limits means covered; "Usage\u000a      credits" means it uses credits; "No" means it is not offered. If the\u000a      page cannot be read or the table is not there, FORBIDDEN to mark the\u000a      models as using credits: tell the user and ask them which models their\u000a      plan covers, with no recommendation.\u000a    Then ask the user with the selection tool, in their language: "Which model\u000a    do I launch the <role> with (effort high)?" Options: the models of the\u000a    tool; first the recommended one, the most capable covered model, with\u000a    "(recommended)" after its name; every model that uses credits with\u000a    "(uses credits)" after its name, never recommended; the user can also\u000a    write another one. Launch ONLY with the model the user chose. FORBIDDEN to\u000a    launch, try or relaunch on your own a model that uses credits, or to\u000a    accept a usage-credits prompt: if a launch still asks for usage credits,\u000a    close that terminal without doing anything else in it, mark that\u000a    model "(uses credits)" and ask again.\u000a    Example, Claude Code: --model <top model> --effort high, as in the command. Another\u000a    tool: its equivalent options (<skill folder>/agents/ADAPT.md, section 3);\u000a    if it does not let you choose, tell the user and use its default.\u000a    Save the handle it returns (<tests_handle>) and send it the prompt:\u000a      orca terminal send --terminal <tests_handle> --text ''<prompt>'' --enter\u000a    The prompt contains: "You are the final tests agent. Your goal is to\u000a    break the program with realistic edge cases from the project''s own flow.\u000a    Read .tests_context.txt in your folder: it starts with your row (step 8).\u000a    Path of project.db, only for the automatic close: <path>."\u000a    plus "Tests folder, already created: <root>/<tests folder>/final/", "My\u000a    handle is <$ORCA_TERMINAL_HANDLE>", "Tests language: <English, unless the\u000a    user asked for another>" and, if you do not use orca, which tool\u000a    you use and its commands to send messages; if there is none, that the\u000a    user will carry the messages between the two of you.\u000a    Each orca send goes with --wait-submit 20; if it warns that the Enter may have been swallowed, repeat that same command adding the --retry-request <id> it gives (it never sends twice); never send probe or test messages. The orca commands are an example: if orca does not exist, look in your environment\u000a    for an equivalent tool (one that creates a terminal with an agent, sends it\u000a    text, closes it and gives you your own identifier) and adapt the\u000a    commands. If there is none, tell the user the exact message and which\u000a    agent to take it to, and wait.\u000a\u000aOnly when you have finished ALL of the above in this row, run in\u000aproject.db:\u000a  SELECT process FROM workflow WHERE step = 703;\u000aForbidden to run that query before finishing this row, to skip a row or to\u000ado the work of another row here.'));
INSERT INTO workflow VALUES(703,unistr('Row 703 of workflow — review and execution of the final tests (3 of 6).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Review. When you receive TESTS_READY, check:\u000a    - that each row of goals, constraints, prohibitions and descriptions has\u000a      at least one individual test (compare its coverage with\u000a      SELECT COUNT(*) FROM goals; and the same in the other three);\u000a    - that the individual tests stress each aspect to the maximum, without\u000a      unnecessary tests;\u000a    - that each scenario is a real case that combines two or more rows, and that\u000a      they go from the most basic to the most stressful possible;\u000a    - that they are consistent with how the code is built.\u000a    If something needs fixing, without revealing the code:\u000a      orca terminal send --terminal <tests_handle> --text ''[work → tests]\u000a      final: FIX: <test>: <why>.'' --enter\u000a    If it sends you QUESTION, answer it without revealing the code:\u000a      orca terminal send --terminal <tests_handle> --text ''[work → tests]\u000a      final: ANSWER: <…>.'' --enter\u000a    With the tests approved, add the imports yourself and run the whole\u000a    final/ folder with the tester still open. Then:\u000a      SELECT phase, test, rows, outcome FROM test WHERE outcome <> ''passed'';\u000a    - A badly written test: send it back with FIX and run again.\u000a    - The code fails: go to row 704.\u000a    - No rows: go to row 705.\u000a    Round: each time you send a test back to the tester because it is badly written\u000a    and does not match how the program works (in the review or after\u000a    running it); nothing else counts as a round. Maximum 10. On reaching 10,\u000a    close the tester, delete everything it created inside final/ (the folder stays) and launch another one (row 702). If the\u000a    second one also reaches 10, close it, delete everything it created, analyze\u000a    all the possibilities and propose the 3 best fixes to the user;\u000a    they decide.\u000a    Closing the tester is always: orca terminal close --tab --terminal <tests_handle>\u000a    and then: rm <root>/<tests folder>/final/.tests_context.txt\u000a\u000aOnly when you have run the approved tests, run in project.db:\u000a  the code fails → SELECT process FROM workflow WHERE step = 704;\u000a  no rows        → SELECT process FROM workflow WHERE step = 705;\u000aForbidden to run them before running the approved tests.'));
INSERT INTO workflow VALUES(704,unistr('Row 704 of workflow — the code fails (4 of 6).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. The code fails. You fix it with the same process as in a block:\u000a    a. Close the tester and keep its tests (they are fine).\u000a    b. From the rows of the failing test and the outputs it calls, identify\u000a       the block and read the same as the work agent reads:\u000a         SELECT id, name, definition, acceptance, state, missing, completed, diagram,\u000a           outputs, files FROM blocks WHERE id = <id>;\u000a         SELECT b.id, b.name, b.definition, b.outputs FROM block_deps d\u000a           JOIN blocks b ON b.id = d.depends_on_id WHERE d.block_id = <id>;\u000a         SELECT concept FROM concepts WHERE level = ''partial'' OR skipped = 1;\u000a       (the partial ones and the ones the user moved on from: keep them in mind when explaining, reinforcing them without notice).\u000a       Write the report, in the user''s language, overwriting it if it exists:\u000a         <root>/<tests folder>/final/TESTS_REPORT.md\u000a         # <name of the project>\u000a         ## TESTS:\u000a         ### <n>. <short description of the cause>\u000a         - Line that breaks it: <file>:<line> → <the code of that line>\u000a         - Why: <the cause, e.g. a ValueError not handled with try/except>\u000a         - Failing tests:\u000a           - <test name> (<the rows it marks: goals 3…>), block <id> <name>: <what broke, in one\u000a             sentence>. <function> was given <argument> (the exact call) →\u000a             <actual output: the error or the wrong result, as printed>\u000a       One section per cause: the failing tests that share the same line and\u000a       the same why go together in one section, each with its own call and\u000a       output. The labels go in the user''s language, except "TESTS:".\u000a       Never the fix: no corrected code and no solution, the user solves it\u000a       working with you. Tell the user the path of the file.\u000a       Each run that still fails rewrites it with the current failures; when\u000a       all pass, add at the end: "Resolved: all tests pass (<date>)."\u000a       You decide the fix together.\u000a    c. Ask for the method (ai_first or hybrid) and run:\u000a         SELECT instructions FROM work_methods WHERE method = ''<method chosen by the user>'';\u000a       Fix according to that instruction. If the change no longer matches what\u000a       is written for the block, update it:\u000a         UPDATE blocks SET definition = ''<…>'' WHERE id = <id>;\u000a         UPDATE blocks SET diagram = ''<…>'' WHERE id = <id>;\u000a         UPDATE blocks SET files = ''<path1>,<path2>'' WHERE id = <id>;\u000a         UPDATE blocks SET outputs = ''<…>'' WHERE id = <id>;\u000a       (definition and outputs reopen the block and its dependents).\u000a    d. Re-verify the reopened blocks, in order:\u000a         SELECT id, name FROM blocks WHERE state <> ''done'' ORDER BY id;\u000a       Run the tests of each one, in <tests folder>/<name of the\u000a       block>/; its automatic close returns it to done. If any fails, apply this\u000a       same row 704 to that block.\u000a    e. With all blocks in done, run the final/ folder again and\u000a       continue in row 703 (if tests need fixing, launch a new\u000a       tester, row 702).\u000a\u000aOnly when all blocks are in done and you have run final/ again,\u000arun in project.db:\u000a  SELECT process FROM workflow WHERE step = 703;\u000aForbidden to run it before.'));
INSERT INTO workflow VALUES(705,unistr('Row 705 of workflow — everything passes (5 of 6).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Everything passes. Check that no row is left unmet:\u000a      SELECT ''goals'', id FROM goals WHERE compliance <> ''complied''\u000a      UNION ALL SELECT ''constraints'', id FROM constraints WHERE compliance <> ''complied''\u000a      UNION ALL SELECT ''prohibitions'', id FROM prohibitions WHERE compliance <> ''complied''\u000a      UNION ALL SELECT ''descriptions'', id FROM descriptions WHERE compliance <> ''complied'';\u000a    If it returns rows, they are missing tests: ask the tester for them with FIX\u000a    (it does not count as a round) and go back to row 703. No rows: close the tester\u000a    and review the pending items:\u000a      SELECT id, description, date FROM pending WHERE done = 0 ORDER BY id;\u000a    If there are any, show them to the user: each one is fulfilled (UPDATE pending SET\u000a    done = 1 WHERE id = <id>;) or, if they discard it, it is deleted (DELETE FROM\u000a    pending WHERE id = <id>;). With no pending items, ask the user: "All the final tests passed. Do you want to do\u000a    anything else in the project?"\u000a    - Yes: handle what they ask for. If it involves changing the spec, the pouring or the\u000a      blocks, the triggers reopen what corresponds and row 1 picks up the\u000a      flow on the next start.\u000a    - No: go to row 706.\u000a\u000aOnly when the user says they do not want to do anything else, run in project.db:\u000a  SELECT process FROM workflow WHERE step = 706;\u000aForbidden to run it before.'));
INSERT INTO workflow VALUES(706,unistr('Row 706 of workflow — project close (6 of 6, last).\u000aMANDATORY, in this order, without skipping anything:\u000a\u000a1. Project close, in this order:\u000a    a. Reconciliation of block_division.md. Run\u000a         SELECT process FROM workflow WHERE step = 405;\u000a       and apply only its checks to the real blocks (do not run the\u000a       query at the end of that row: you stay in this one). Then\u000a       leave the file as the project guide: delete pending, decided and\u000a       handoff leftovers, and update it to the real version with\u000a         SELECT id, name, definition, state FROM blocks ORDER BY id;\u000a         SELECT block_id, depends_on_id FROM block_deps ORDER BY block_id;\u000a    b. Final project description (replaces the one from the diagnosis):\u000a         UPDATE project SET information = ''<what it is and what it does, in 2 to 4\u000a           sentences, according to the spec and the real blocks>'' WHERE topic = ''description'';\u000a    c. Skills evidence. Run:\u000a         SELECT information FROM project WHERE topic = ''name'';\u000a         SELECT concept FROM concepts WHERE level <> ''agent'';\u000a       For each concept, go to kiron_pupil.db and run:\u000a         SELECT id FROM knowledge WHERE skill = ''<concept>'';\u000a         INSERT INTO skill_evidence (project_name, use, skill)\u000a           VALUES (''<name>'', ''<in which blocks and files it was used>'', <id>);\u000a       The trigger raises the level in knowledge (need2learn → partial on the\u000a       first record); do not write it yourself. The concepts the user moved on\u000a       from without finishing their study (skipped = 1) count the same and are\u000a       NEVER left out: after the whole project and its constant reinforcement,\u000a       the knowledge was acquired, in a more practical than theoretical way.\u000a    d. Tell the user, in their language: "Project <name> completed successfully!\u000a       Go celebrate."\u000a    e. Session close. Go to kiron_pupil.db and run:\u000a         SELECT action FROM last WHERE step = 1;'));
CREATE TABLE pouring (
    topic       TEXT PRIMARY KEY CHECK (topic IN ('instructions','current','done')),
    information TEXT NOT NULL,
    CHECK (topic <> 'current' OR information IN
           ('not_started','prohibitions','constraints','goals','descriptions','concepts','end')),
    CHECK (topic <> 'done' OR information IN ('true','false')),
    CHECK (topic <> 'instructions' OR TRIM(information) <> '')
);
INSERT INTO pouring VALUES('instructions',unistr('MANDATORY: every rule in this text is unbreakable. Forbidden to skip\u000aone, accept something without meeting it or advance without the approval it\u000aasks for.\u000a\u000aRead the spec with:\u000a  SELECT information FROM spec WHERE topic = ''spec'';\u000aThe pouring extracts from it, in this order, the project tables (four from the\u000aspec plus concepts):\u000a  1. prohibitions  (section 8: limits)\u000a  2. constraints   (sections 5 and 7: technologies and architectural methods)\u000a  3. goals         (sections 3, 4 and 6: goal, functionalities and scaling direction)\u000a  4. descriptions  (sections 1 and 2: what the product is and whom it serves; it\u000a                    goes after the three previous ones because it relies on them)\u000a  5. concepts      (every concept or tool that will be used to complete the project)\u000a\u000aProcess, table by table and row by row:\u000a  1. Propose ONE row per reply, never several: a selection-tool question whose\u000a     text is the row with its index (x1:), its statement, what it is based on\u000a     (basis: section of the spec, with its context) and its practical purpose\u000a     (why), explained so it can be judged alone; options: approve, reject,\u000a     comment before advancing (then ask for the comment as plain text in your\u000a     next reply). This question is the exception to writing explanations\u000a     outside the selection tool. If the user answers it with a question,\u000a     answer it as plain text in your reply and ask again only in the next one\u000a     (rule EXPLAIN_FIRST of the style hook). The next row only after this one\u000a     is decided.\u000a  2. If the user approves it, add it and continue with the next one:\u000a       INSERT INTO <table> (statement, basis, why) VALUES (''<statement>'', ''<basis>'', ''<why>'');\u000a     In goals, if it depends on a constraint, add constraint_id:\u000a       INSERT INTO goals (statement, basis, why, constraint_id)\u000a       VALUES (''<statement>'', ''<basis>'', ''<why>'', <constraint id>);\u000a     In concepts, the row carries concept and level instead of statement:\u000a       INSERT INTO concepts (concept, level, basis, why)\u000a       VALUES (''<concept>'', ''<level>'', ''<basis>'', ''<why>'');\u000a  3. If it does not agree, discuss it until deciding whether it is added, modified\u000a     or discarded. To modify a row already added:\u000a       UPDATE <table> SET statement = ''<new text>'' WHERE id = <id>;\u000a  Every row must respond to a clear, practical, objective and real purpose within\u000a  the context of the project and its scaling projections. Do not add rows for\u000a  improbable assumptions, of little practical value or that fulfill something\u000a  already described in another row.\u000a  In goals, constraints and prohibitions, the statement must be objective and\u000a  verifiable: that it can be checked with a yes or no, or with a number and its\u000a  threshold (e.g. "responds in less than 200 ms with 100 users", "uses\u000a  PostgreSQL", "does not store passwords in plain text"). If it cannot be checked\u000a  that way, rephrase it with the user before adding it. descriptions and concepts\u000a  are exempt: they describe, they are not measured.\u000a  If a goal depends on a technical constraint, link it with its constraint_id and\u000a  explain in its why how it is supported (not just which one it is), e.g.\u000a  "possible thanks to constraint 3 because ...".\u000a  In descriptions, which is filled after prohibitions, constraints and goals, the\u000a  why quotes the rows of those tables on which the description relies, with their\u000a  table and id (e.g. "verified with goals 2 and constraints 1"), to tie the\u000a  descriptive to the verifiable. To see them, run:\u000a    SELECT ''prohibitions'' AS table_name, id, statement FROM prohibitions\u000a    UNION ALL SELECT ''constraints'', id, statement FROM constraints\u000a    UNION ALL SELECT ''goals'', id, statement FROM goals;\u000a  A description that cannot rely on any row is discussed with the user: either a\u000a  verifiable row is missing, or the description adds nothing.\u000a\u000aCoherence:\u000a  Everything you write must agree with itself and serve the end of the project\u000a  (the measurable goal). Actively look for and point out to the user, before\u000a  continuing:\u000a    1. Inconsistencies: two parts that contradict each other or do not fit (a\u000a       functionality against a limit, a goal against a constraint, a technology\u000a       that does not support what is asked).\u000a    2. Gaps: something the end requires and nobody covers, or something defined\u000a       without what it needs to work.\u000a    3. Weaknesses and failures: fragile points, cases that break, untreated\u000a       security or scaling risks.\u000a    4. Lack of engineering or efficiency: solutions that comply but are not\u000a       robust, efficient or sustainable compared to a better alternative.\u000a  Do not accept something just because it does not clash with anything: the\u000a  criterion is that the result is robust, well designed, efficient and meets the\u000a  end. Point out only what is real and probable in the context of the project and\u000a  its scaling, not improbable assumptions. Propose the fix; the user decides.\u000a  Apply it to each proposed row, against the already approved rows of all the\u000a  tables and against the spec.\u000a\u000aconcepts: list every concept or tool that will be used to complete the project,\u000a  regardless of its type or size: from a language, a framework or a deployment\u000a  tool (Python, FastAPI, Docker) to a technique or a pattern (RAG,\u000a  decorators). What goes in depends on each project; it is deduced from the\u000a  full spec and the tables already poured.\u000a  Before proposing each concepts row, consult knowledge. Go to kiron_pupil.db\u000a  and run:\u000a    SELECT level FROM knowledge WHERE skill = ''<concept>'';\u000a  - If the concept is already in knowledge, copy its level to the row and propose\u000a    it to the user anyway, so they validate its basis and its why.\u000a  - If it is not, propose it with level need2learn (it is a skill the user will\u000a    want to learn) or agent (it will always be delegated to the agent); on\u000a    approving it, it is added to concepts (INSERT above) and to knowledge. Go to\u000a    kiron_pupil.db and run:\u000a      INSERT INTO knowledge (skill, level) VALUES (''<concept>'', ''<level>'');\u000a  The done column is not written on insert: the table sets it (1 if level is\u000a  mastered or agent; 0 if it is need2learn or partial), and the study of row 3\u000a  of workflow closes it afterwards.\u000a  Values of level, identical in both tables: mastered (the user masters it),\u000a  partial (masters it halfway), need2learn (does not master it and is going to\u000a  study it) and agent (stays under the agent''s responsibility: it is discussed\u000a  and contextualized, but the user does not need to know it in depth).\u000a\u000aControl:\u000a  pouring.current ONLY accepts these values: not_started (the pouring has not\u000a  started), prohibitions, constraints, goals, descriptions and concepts (the\u000a  current table) and end (the pouring finished).\u000a  On starting (current = not_started), run:\u000a    UPDATE project SET information = ''in_progress'' WHERE topic = ''pouring_state'';\u000a    UPDATE pouring SET information = ''prohibitions'' WHERE topic = ''current'';\u000a  When the user confirms that a table is complete, move current to the\u000a  next one (constraints, goals, descriptions, concepts, in that order):\u000a    UPDATE pouring SET information = ''<next table>'' WHERE topic = ''current'';\u000a  If you resume with project.pouring_state = in_progress, read current:\u000a    SELECT information FROM pouring WHERE topic = ''current'';\u000a  and continue that table, comparing it with the rows it already has:\u000a    SELECT * FROM <current table>;\u000a  If current = end there is no table to continue: the pouring was complete and\u000a  the spec was reopened. Close it as "Reopened after the pouring started" says:\u000a    SELECT information FROM spec WHERE topic = ''instructions'';\u000a  Before moving current to end, do a final coherence pass over the five\u000a  complete tables:\u000a    SELECT id, statement FROM descriptions;\u000a    SELECT id, statement FROM prohibitions;\u000a    SELECT id, statement FROM constraints;\u000a    SELECT id, statement, constraint_id FROM goals;\u000a    SELECT id, concept, level FROM concepts;\u000a  In addition, no description must be left without quoting rows of the other three\u000a  tables (it must return 0 rows):\u000a    SELECT id FROM descriptions\u000a    WHERE why NOT LIKE ''%prohibitions%'' AND why NOT LIKE ''%constraints%'' AND why NOT LIKE ''%goals%'';\u000a  That query only checks that the why names one of the three tables, not that the\u000a  quoted id exists or that the quote is correct; the coherence pass reviews that.\u000a  If something fails, fix it with the UPDATE above before closing the pouring.\u000a  On finishing concepts and the user confirming that the pouring is complete, run:\u000a    UPDATE pouring SET information = ''end'' WHERE topic = ''current'';\u000a    UPDATE pouring SET information = ''true'' WHERE topic = ''done'';'));
INSERT INTO pouring VALUES('current','end');
INSERT INTO pouring VALUES('done','true');
CREATE TABLE handoff (
    id      INTEGER PRIMARY KEY,
    kind    TEXT NOT NULL DEFAULT 'open' CHECK (kind IN ('open','closed','interrupted')),
    handoff TEXT NOT NULL CHECK (TRIM(handoff) <> ''),
    date    TEXT NOT NULL DEFAULT (date('now', 'localtime')) CHECK (date(date) IS date)
);
CREATE TABLE block_deps (
    block_id      INTEGER NOT NULL,
    depends_on_id INTEGER NOT NULL,
    PRIMARY KEY (block_id, depends_on_id)
);
CREATE TABLE descriptions (
    id         INTEGER PRIMARY KEY,
    statement  TEXT NOT NULL UNIQUE CHECK (TRIM(statement) <> ''),
    basis      TEXT NOT NULL CHECK (TRIM(basis) <> ''),
    why        TEXT NOT NULL CHECK (TRIM(why) <> ''),
    compliance TEXT NOT NULL DEFAULT 'not_yet' CHECK (compliance IN
               ('not_yet','partially','complied','statement_edited')),
    updated_at TEXT NOT NULL DEFAULT (date('now', 'localtime')) CHECK (date(updated_at) IS updated_at)
);
INSERT INTO descriptions VALUES(1,'A RAG system that answers questions about the vLLM codebase (vllm-0.10.1) in four stages: index (chunk .py, .md and .txt files and store a BM25 index plus embeddings), retrieve the top-k most relevant sources, place them in the model context and generate the answer with Qwen3-0.6B as JSON. It is used from the CLI or from a local HTTP API that returns the same results.','Spec point 1 (what it is).','Summary of the product; relies on goals 1 (recall@5), 4 (grounded answers) and 8 (local API), and on constraints 10 (one chunker per type), 7 (semantic embeddings), 8 (Qwen3-0.6B), 6 (FastAPI + uvicorn) and 12 (shared service layer).','not_yet','2026-10-31');
INSERT INTO descriptions VALUES(2,'On top of the mandatory pipeline, the product has all five bonuses: a semantic index next to the lexical one, hybrid ranking of both, incremental indexing, caching and a local HTTP API. Each bonus plugs in without rewriting what already works, and counts only if the whole mandatory part validates.','Spec point 1 (all five bonuses of point 6 are built) and point 6 (scope).','States the full scope; relies on goals 5 (hybrid retrieval), 6 (incremental indexing), 7 (caching) and 8 (local API), and on constraints 9 (retriever interface), 11 (versioned index), 13 (versioned cache) and 12 (shared service layer).','not_yet','2026-10-31');
INSERT INTO descriptions VALUES(3,'Primary user: 42 peer evaluators and the moulinette, who run it through the reference exam scripts and push it with odd inputs; questions are about the vLLM codebase (docs questions and code questions).','Spec point 2.1 (primary target client).','Explains why the exact interface and robustness weigh so much; relies on prohibitions 5 (no unhandled traceback), constraints 4 (Fire CLI), 5 (pydantic models) and 14 (repository layout), and goals 1 (recall@5).','not_yet','2026-10-31');
INSERT INTO descriptions VALUES(4,'Secondary user: recruiters reviewing the project, mainly through the README and the repository (code quality, design decisions, performance analysis, example usage).','Spec point 2.2 (secondary target client).','Justifies that the README holds the measures and the decisions; relies on constraints 15 (README) and 2 (code quality), and prohibitions 7 (code the user can explain).','not_yet','2026-10-31');
CREATE TABLE prohibitions (
    id         INTEGER PRIMARY KEY,
    statement  TEXT NOT NULL UNIQUE CHECK (TRIM(statement) <> ''),
    basis      TEXT NOT NULL CHECK (TRIM(basis) <> ''),
    why        TEXT NOT NULL CHECK (TRIM(why) <> ''),
    compliance TEXT NOT NULL DEFAULT 'not_yet' CHECK (compliance IN
               ('not_yet','partially','complied','statement_edited')),
    updated_at TEXT NOT NULL DEFAULT (date('now', 'localtime')) CHECK (date(updated_at) IS updated_at)
);
INSERT INTO prohibitions VALUES(1,'The solution never imports or calls the moulinette (checked: no import or call of it anywhere in src/).','Spec point 8 (limits: never call or import the moulinette) and point 4.6 (evaluate computes its own recall@k; the official one is computed by the moulinette).','Keeps evaluate independent from the official grader, as the subject requires; a dependency on it would break the project rules and fake the own measurement.','not_yet','2026-10-31');
INSERT INTO prohibitions VALUES(2,'No source wider than 2000 characters is ever output, and index rejects any --max_chunk_size above 2000 (checked: index --max_chunk_size 3000 exits != 0; the longest source of a search_dataset output is <= 2000 characters).','Spec point 8 (limits: no source wider than 2000 characters; max_chunk_size never above 2000) and point 4.1 (index; case 1: max_chunk_size outside 1..2000 rejected with a clear message and exit code != 0).','The moulinette rejects any source longer than 2000 characters, and a single over-long source invalidates the whole output.','not_yet','2026-10-31');
INSERT INTO prohibitions VALUES(3,'No input or output path is hard-coded: every path read or written in src/ comes from a CLI argument, defaults allowed (e.g. index takes the raw and processed folders as arguments with defaults data/raw and data/processed).','Spec point 8 (limits: no hard-coded input/output paths) and point 4 (all input/output paths are CLI arguments, never hard-coded; options shown are the minimum, more may be added).','Required by the subject, and lets the evaluator run every command on data placed in other folders without touching the code.','not_yet','2026-10-31');
INSERT INTO prohibitions VALUES(4,'The repository never holds data (data/), model weights, indexes, generated outputs or logs; all of them are listed in .gitignore (checked: git ls-files lists nothing under data/ or logs/ and no model file).','Spec point 8 (limits: no large data files, model weights or generated outputs in the repository, the evaluator generates them; only src/, pyproject.toml, uv.lock, Makefile, README.md and needed config files are evaluated).','Keeps the repository light and prevents submitting results that do not come from the code.','not_yet','2026-10-31');
INSERT INTO prohibitions VALUES(5,'No input ever ends in an unhandled traceback: every error gives a clear message and exit code != 0 (checked: running every edge case of spec points 4.1 to 4.6, e.g. missing paths, malformed JSON, negative k, Ctrl+C, prints no "Traceback").','Spec point 8 (limits: no unhandled traceback on any input) and point 3, goal 5 (never crash with an unhandled traceback; a crash during review = non-functional).','Bad inputs are tested at the defense and a crash counts as non-functional; a clear message also tells the user what to fix.','not_yet','2026-10-31');
INSERT INTO prohibitions VALUES(6,'The HTTP API is reachable only from 127.0.0.1 of the machine where it runs (checked: without Docker, lsof -iTCP -sTCP:LISTEN shows the server only on 127.0.0.1; if Docker is used, it is kept as a separate solution and checked with docker port, which must show the port published only on 127.0.0.1).','Spec point 4.7 (local HTTP API, bonus; user decision, 2026-10-28: listens only on 127.0.0.1 because the API has no authentication).','If it listened on 0.0.0.0, anyone on the campus network could use the API and fill the model queue.','not_yet','2026-10-31');
INSERT INTO prohibitions VALUES(7,'The repository holds no code the user cannot explain and justify at the defense (checked: before a block is marked done, the user explains its functions in their own words).','Spec point 8 (limits: AI usage, subject chapter III: only use AI-generated content that is fully understood and can be explained and justified at evaluation; a brief recode may be requested during the defense).','At the defense any part can be questioned or a small recode requested; code the user does not understand fails the evaluation.','not_yet','2026-10-31');
CREATE TABLE constraints (
    id         INTEGER PRIMARY KEY,
    statement  TEXT NOT NULL UNIQUE CHECK (TRIM(statement) <> ''),
    basis      TEXT NOT NULL CHECK (TRIM(basis) <> ''),
    why        TEXT NOT NULL CHECK (TRIM(why) <> ''),
    compliance TEXT NOT NULL DEFAULT 'not_yet' CHECK (compliance IN
               ('not_yet','partially','complied','statement_edited')),
    updated_at TEXT NOT NULL DEFAULT (date('now', 'localtime')) CHECK (date(updated_at) IS updated_at)
);
INSERT INTO constraints VALUES(1,'The project is installed and run only with uv: pyproject.toml and uv.lock at the repo root, and uv sync on a clean clone installs everything with no extra step (checked: fresh clone, uv sync, then uv run python -m src index runs with the data in place).','Spec point 5 (technologies: uv as project and package manager; reviewer and moulinette only run uv sync) and point 8 (limits: package manager is uv only for the evaluator).','If anything needs pip or a manual step, it does not start on the evaluator machine and the whole project counts as non-functional.','not_yet','2026-10-31');
INSERT INTO constraints VALUES(2,'Python >= 3.10; make lint (flake8 . and mypy with the subject flags --warn-return-any --warn-unused-ignores --ignore-missing-imports --disallow-untyped-defs --check-untyped-defs) passes with no error on the whole repo, bonus files included; type hints on parameters, returns and variables; PEP 257 docstrings in Google or NumPy style (checked: make lint exits 0).','Spec point 5 (technologies: Python >= 3.10, flake8, type hints, mypy without errors, PEP 257 docstrings; Makefile lint rule) and point 6 (flake8 also applies to bonus files).','The evaluator runs the lint, and a norm error counts against the project even when the program works.','not_yet','2026-10-31');
INSERT INTO constraints VALUES(3,'The Makefile has the rules install, run, debug (pdb), clean (__pycache__, .mypy_cache...) and lint; lint-strict is optional (checked: make install, make run, make debug, make clean and make lint exist and end without error).','Spec point 5 (technologies: Makefile rules) and point 8 (submission: the Makefile with install/run/debug/clean/lint is part of what is evaluated).','The evaluator calls these rules by name; a missing rule fails that part of the evaluation.','not_yet','2026-10-31');
INSERT INTO constraints VALUES(4,'The CLI uses Python Fire, is invoked as uv run python -m src <command> [options], has the commands index, search, search_dataset, answer, answer_dataset and evaluate with at least the options of the spec, and shows tqdm progress bars on long operations (checked: the three uv commands of the defense pipeline, spec point 4.11, run exactly as written, and each of the six commands answers to --help).','Spec point 4 (commands and minimum options; uv run python -m src <command>) and point 5 (technologies: CLI with Python Fire; tqdm progress bars).','The evaluator reference scripts call these commands by these names; if the interface changes, the checks fail by design.','not_yet','2026-10-31');
INSERT INTO constraints VALUES(5,'The data exchanged between stages, and the API responses, are pydantic models with at least the fields of spec point 4.9, and every JSON written is validated against its model (checked: the search_dataset output passes the moulinette with "Student data is valid: True").','Spec point 4.9 (data models, pydantic), point 4.10 (output: each command writes JSON conforming to the models) and point 5 (technologies: pydantic for the data models exchanged between stages).','The moulinette reads these JSON files; one wrong field name invalidates the whole output.','not_yet','2026-10-31');
INSERT INTO constraints VALUES(6,'The local HTTP API (bonus) is built with FastAPI and served with uvicorn, started from the CLI with --port (checked: the server starts from the CLI with --port and GET /health answers 200).','Spec point 5 (technologies: local HTTP API with FastAPI, served with uvicorn) and point 4.7 (the server is started from the CLI and takes --port).','FastAPI validates parameters with the same pydantic models of constraints 5 and gives the automatic 422 that point 4.7 requires.','not_yet','2026-10-31');
INSERT INTO constraints VALUES(7,'The semantic index (bonus) uses all-MiniLM-L6-v2 on CPU with numpy brute-force cosine search; the library (fastembed or sentence-transformers) is chosen with the user from the measures of pending 17 (library comparison) and 34 (256-token truncation) (checked: every index version stores the embedding model name and one vector per chunk, built without GPU).','Spec point 5 (technologies: semantic embeddings, all-MiniLM-L6-v2 on CPU, numpy brute-force cosine search, fastembed or sentence-transformers measured) and point 6 (bonus 1, CPU-only machine).','A small CPU model fits the 5-minute indexing goal (spec point 3, goal 2) and runs on the campus machines without GPU.','not_yet','2026-10-31');
INSERT INTO constraints VALUES(8,'The answer generator uses Qwen/Qwen3-0.6B by default behind one generator interface; another model can be swapped in without touching the rest, but everything must still work with Qwen3-0.6B (checked: answer with no model option uses Qwen3-0.6B and returns a valid MinimalAnswer).','Spec point 5 (technologies: model Qwen/Qwen3-0.6B by default), point 7 method 6 (one generator interface) and point 8 (limits: must keep working with Qwen/Qwen3-0.6B).','The subject evaluates with this model; another model is only useful if it does not break that case.','not_yet','2026-10-31');
INSERT INTO constraints VALUES(9,'Bm25Retriever, SemanticRetriever and HybridRetriever (RRF over the other two) share the method search(query, k) -> list[MinimalSource]; --method only picks which one is created, and the CLI, the API and search_dataset never know which one runs (checked: outside the factory that reads --method, no file of src/ names a concrete retriever class).','Spec point 7 method 1 (one retriever interface; enables bonuses 1 and 2).','Adding the semantic and hybrid retrievers does not force rewriting what already works with BM25.','not_yet','2026-10-31');
INSERT INTO constraints VALUES(10,'There is one chunker per indexed file type (.py code, .md Markdown, .txt plain text), each with its own logic, picked from a registry keyed by extension; adding a type means adding one class and one registry entry (checked: the registry holds exactly .py, .md and .txt, and the indexer has no branch on the extension outside the registry).','Spec point 7 method 2 (one chunker per indexed file type, registry keyed by extension) and point 4.1 (three chunking strategies, one per indexed file type; the subject asks for at least two).','Each type is tuned separately in the chunking phase without breaking the others.','not_yet','2026-10-31');
INSERT INTO constraints VALUES(11,'Every index version is written complete in its own subfolder of the processed folder (chunks, BM25 statistics, embeddings, sha256 of every indexed file and build settings) and is activated, only after verification, by an atomic os.replace of a pointer file; index, the CLI and the API all read it through this store (checked: kill -9 on index halfway leaves the pointer on the previous version and search still works).','Spec point 7 method 3 (versioned index store; enables bonus 3) and point 4.1 cases 7 and 11 to 15.','An interruption never leaves a broken or mixed index, and incremental indexing can reuse what did not change.','not_yet','2026-10-31');
INSERT INTO constraints VALUES(12,'Search and answer functions live in one service layer and take and return pydantic models; the Fire CLI and the FastAPI server are thin wrappers that only call them (checked: the CLI and API files import no retriever, chunker or generator, only the service layer).','Spec point 7 method 4 (one shared service layer; enables bonus 5).','The API never duplicates logic, so a fix in search or answer applies to the CLI and the API at once.','not_yet','2026-10-31');
INSERT INTO constraints VALUES(13,'The query result cache (bonus) is stored on disk keyed by (index version, method, query, k); when the active version changes, entries of versions that no longer exist are deleted, and the model and the index are loaded once per process; its inner design is studied with the user at the start of the caching phase (pending 32) (checked: after re-indexing, the same query is recomputed and the cache folder holds no entry of a deleted version).','Spec point 7 method 5 (cache whose key includes the index version; enables bonus 4) and point 4.8 (caching).','A result of an old index is never served and the cache never grows without limit.','not_yet','2026-10-31');
INSERT INTO constraints VALUES(14,'The repository follows the subject layout: src/ (runnable as uv run python -m src), pyproject.toml, uv.lock, README.md, and the default data folders data/raw, data/processed, data/datasets/UnansweredQuestions and AnsweredQuestions, data/output/search_results/<DatasetScope> and data/output/search_results_and_answer/<DatasetScope>; these are defaults, not fixed paths (prohibitions 3) (checked: the defense pipeline, spec point 4.11, runs with the default paths).','Spec point 5 (repository layout: if structure or interface is not respected, the reference scripts cannot run and checks fail by design).','The evaluator scripts look for the files in these places.','not_yet','2026-10-31');
INSERT INTO constraints VALUES(15,'README.md is in English; its first line, in italics, is "This project has been created as part of the 42 curriculum by <login>" where <login> is the user''s 42 login; it has the sections Description, Instructions, Resources (references and how AI was used, for which tasks and parts), System architecture, Chunking strategy, Retrieval method, Performance analysis, Design decisions, Challenges faced and Example usage. Any text in the project that states what the AI did is decided by discussing it with the user, never assumed (user decision, 2026-10-31) (checked: the first line and the 10 section titles are in the README).','Spec point 5 (README.md, English, first line and required sections; any text stating what the AI did is decided with the user, user decision 2026-10-31).','Required by the subject; it is also where the measures go (e.g. the recall@k of every chunk size, pending 29).','not_yet','2026-10-31');
INSERT INTO constraints VALUES(16,'Errors are handled with try-except and clear messages; files and connections are opened with context managers (with), with no resource leaks; this is how prohibitions 5 (no unhandled traceback) is met (checked: no open() in src/ outside a with block).','Spec point 5 (technologies: exceptions handled gracefully with try-except; context managers for files and connections; no resource leaks).','Required by the subject; a file left open can leave half-done writes.','not_yet','2026-10-31');
INSERT INTO constraints VALUES(17,'pytest tests cover the edge cases of spec points 4.1 to 4.8; they are not graded, but uv run pytest passes in full (checked: uv run pytest exits 0 and every numbered edge case of points 4.1 to 4.8 has at least one test).','Spec point 5 (tests with pytest or unittest covering edge cases, not graded).','They check prohibitions 5 (no unhandled traceback) and the error cases without testing them by hand each time, and show that a change does not break what already worked.','not_yet','2026-10-31');
INSERT INTO constraints VALUES(18,'Everything, bonuses included, runs on the CPU-only campus machine, with no GPU or CUDA (checked: the defense pipeline, spec point 4.11, and the bonuses run with CUDA_VISIBLE_DEVICES empty on a campus machine).','Spec point 5 (environment: CPU-only campus machine; moulinette binaries for Ubuntu / Fedora) and point 6 (every bonus must work on a CPU-only machine).','Anything that depends on a GPU does not run at the defense and counts as non-functional.','not_yet','2026-10-31');
CREATE TABLE goals (
    id         INTEGER PRIMARY KEY,
    statement  TEXT NOT NULL UNIQUE CHECK (TRIM(statement) <> ''),
    basis      TEXT NOT NULL CHECK (TRIM(basis) <> ''),
    why        TEXT NOT NULL CHECK (TRIM(why) <> ''),
    constraint_id INTEGER,
    compliance TEXT NOT NULL DEFAULT 'not_yet' CHECK (compliance IN
               ('not_yet','partially','complied','constraint_edited','statement_edited')),
    updated_at TEXT NOT NULL DEFAULT (date('now', 'localtime')) CHECK (date(updated_at) IS updated_at)
);
INSERT INTO goals VALUES(1,'Recall@5 >= 80 % on docs questions and >= 50 % on code questions, measured with the official moulinette on the public datasets (checked: moulinette Recall@5 >= 0.80 on docs and >= 0.50 on code).','Spec point 3, goal 1 (measurable product goal).','Main grade of the subject: retrieval quality weighs most in the evaluation. Possible thanks to constraints 10 because recall depends on how each file type is cut, and one chunker per type lets .py, .md and .txt be tuned separately with the chunk size measures of pending 29.',10,'not_yet','2026-10-31');
INSERT INTO goals VALUES(2,'A full index of the whole corpus (lexical index + embeddings) takes at most 5 minutes on the CPU-only campus machine; above 5 minutes, stop and decide with the user (pending 18) (checked: time uv run python -m src index <= 300 s).','Spec point 3, goal 2 (indexing the whole corpus: at most 5 minutes).','The evaluator runs index at the defense and cannot wait long. Possible thanks to constraints 7 because embeddings are the slow part, and it fixes a small CPU model and picks the fastest library from the measures of pending 17.',7,'not_yet','2026-10-31');
INSERT INTO goals VALUES(3,'search_dataset answers 200 questions in at most 90 seconds, with bm25 and also with hybrid; above 90 s, stop and decide with the user (pending 33) (checked: time of search_dataset on 200 questions <= 90 s for each method).','Spec point 3, goal 3 (retrieval throughput: at most 90 seconds for 200 questions; the index must be queryable in milliseconds).','The defense runs search_dataset on the full datasets. Not tied to a constraint: the time depends on loading the index once and querying it in memory, which is how it is coded, not a mandatory technology.',NULL,'not_yet','2026-10-31');
INSERT INTO goals VALUES(4,'Answers are grounded in their sources: on a sample of 20 docs questions reviewed by hand with the user, no answer states a fact absent from its sources; no answer contains a <think> block; a question with no source gets answer "" without calling the model (spec point 4.5 case 7) (checked: yes or no on each of the 3 conditions).','Spec point 3, goal 4 (answers coherent, grounded in the retrieved sources, no major hallucination; not a strict pass/fail bar, made verifiable with the user, 2026-10-31).','Grading of answers rewards grounding and prompt strategy. Possible thanks to constraints 8 because the small model is the quality limit, and the generator interface lets the prompt be tuned without touching the rest.',8,'not_yet','2026-10-31');
INSERT INTO goals VALUES(5,'--method hybrid (bonus 1 semantic embeddings and bonus 2 hybrid retrieval) works in search, search_dataset and answer; if the semantic part fails, it falls back to bm25 with a warning naming the reason and keeps running (checked: the search_dataset --method hybrid output passes the moulinette; with the embeddings removed, a warning appears, bm25 is used and the exit code is 0).','Spec point 6 (bonuses 1 and 2) and point 4 (retrieval method: RRF fusion and automatic fallback to BM25 with a warning).','Each bonus is worth one point only if it can be demonstrated; the warning tells the user that the recall measured is bm25, not hybrid. Possible thanks to constraints 9 because HybridRetriever shares search(query, k) with BM25, so the CLI does not change.',9,'not_yet','2026-10-31');
INSERT INTO goals VALUES(6,'Re-running index chunks and embeds only new or changed files; unchanged files have their chunks and vectors copied from the previous version (bonus 3) (checked: change one file, re-index, and the run log reports 1 file reprocessed and the rest copied).','Spec point 6 (bonus 3, incremental indexing) and point 4.1 cases 12 to 14.','Worth one point if demonstrated, and re-indexing after a small change takes seconds instead of minutes. Possible thanks to constraints 11 because every index version stores the sha256 of each file, which is how a change is detected.',11,'not_yet','2026-10-31');
INSERT INTO goals VALUES(7,'A repeated query (same query, k and method on the same index version) is served from the disk cache, and a cache failure never breaks search or answer (bonus 4) (checked: the second run of the same answer is much faster and the run log says it came from the cache; with the cache folder not writable, answer still answers with a warning).','Spec point 6 (bonus 4, caching) and point 4.8 (caching and its failure cases).','Worth one point if demonstrated, and a repeated question (e.g. on the API) does not call the model again. Possible thanks to constraints 13 because the index version is part of the key, so a result of an old index is never served.',13,'not_yet','2026-10-31');
INSERT INTO goals VALUES(8,'The HTTP API (bonus 5) serves GET /search, /answer and /health with the status codes of spec point 4.7 (200, 400, 422, 503) and responses validated with the same models as the CLI; while /answer generates, /search and /health keep answering (checked: a curl script hits every endpoint and every status code, and a /search sent during an /answer returns before the /answer ends).','Spec point 6 (bonus 5, local HTTP API) and point 4.7 (local HTTP API).','Worth one point if demonstrated at the defense. Possible thanks to constraints 12 because the API only calls the same service functions as the CLI, so it returns the same results without duplicating logic.',12,'not_yet','2026-10-31');
INSERT INTO goals VALUES(9,'Every message, warning and error of every command goes to stderr and is also recorded in the run log file, while stdout carries only results (checked: running each command with stdout redirected to a file leaves only results in that file, and every warning seen on stderr appears in the run log file).','Spec point 4 (output channels: results on stdout, messages on stderr; every warning and error also recorded in the run log file, with no exception; user decision, 2026-10-28).','Redirecting stdout must capture only results for the evaluator scripts, and the run log is the record of skipped questions and fallbacks (e.g. answer "" means: see the run log). Added after the external review of the close (user decision, 2026-10-31). Not tied to a constraint: it is how the commands are coded.',NULL,'not_yet','2026-10-31');
CREATE TABLE concepts (
    id         INTEGER PRIMARY KEY,
    concept    TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK (TRIM(concept) <> ''),
    level      TEXT NOT NULL CHECK (level IN ('mastered','partial','need2learn','agent')),
    basis      TEXT NOT NULL CHECK (TRIM(basis) <> ''),
    why        TEXT NOT NULL CHECK (TRIM(why) <> ''),
    done       INTEGER NOT NULL DEFAULT 0 CHECK (done IN (0,1)),
    skipped    INTEGER NOT NULL DEFAULT 0 CHECK (skipped IN (0,1)),
    updated_at TEXT NOT NULL DEFAULT (date('now', 'localtime')) CHECK (date(updated_at) IS updated_at)
);
INSERT INTO concepts VALUES(1,'RAG (Retrieval-Augmented Generation)','partial','Spec point 1 (what it is: a RAG system with four stages: indexing, retrieving, augmenting, generating).','It is the architecture of the whole project, and every stage must be explained at the defense.',1,0,'2026-11-02');
INSERT INTO concepts VALUES(2,'Chunking','partial','Spec point 4.1 (index: three chunking strategies, chunk size rule) and constraints 10 (one chunker per type).','It drives goals 1 (recall@5) the most, and the subject asks to justify the chunking strategy in the README.',1,0,'2026-11-02');
INSERT INTO concepts VALUES(3,'BM25 and tokenization','partial','Spec point 4.1 (retrieval method: at least TF-IDF or BM25; what is kept at indexing time decides what can be matched) and point 4 (BM25 by default).','It is the mandatory retriever and the default method of search, search_dataset and answer; it must be explained at the defense.',1,0,'2026-11-02');
INSERT INTO concepts VALUES(4,'Recall@k and IoU','partial','Spec point 3 (recall@k definition: same file and character range overlap with IoU > 0.05, to be confirmed with pending 11) and point 4.6 (evaluate).','Needed to decide chunk sizes (pending 29) and to read the output of evaluate and the moulinette.',1,0,'2026-11-02');
INSERT INTO concepts VALUES(5,'Embeddings and cosine similarity','partial','Spec point 5 (semantic embeddings: all-MiniLM-L6-v2 on CPU, 256-token limit, numpy brute-force cosine search) and constraints 7 (semantic embeddings).','Bonus 1 and the base of hybrid retrieval; the user decides from the measures of pending 17 (library comparison) and 34 (256-token truncation).',1,0,'2026-11-03');
INSERT INTO concepts VALUES(6,'Reciprocal Rank Fusion (hybrid retrieval)','partial','Spec point 4 (retrieval method: hybrid fuses lexical and semantic rankings with RRF, c = 100 unless measured recall favours 60) and constraints 9 (retriever interface).','Bonus 2; it fuses ranks, not scores, because BM25 and cosine live on different scales.',1,0,'2026-11-03');
INSERT INTO concepts VALUES(7,'LLM generation and prompting (Qwen3-0.6B)','partial','Spec point 4.4 (answer: token budget, thinking mode, <think> removal, context safety net) and constraints 8 (Qwen3-0.6B).','Goals 4 (grounded answers) depends on it, and grading of answers rewards the prompt strategy.',1,0,'2026-11-03');
INSERT INTO concepts VALUES(8,'pydantic','partial','Spec point 4.9 (data models) and constraints 5 (pydantic models).','Every input and output JSON goes through these models; one wrong field invalidates the output for the moulinette.',1,0,'2026-11-03');
INSERT INTO concepts VALUES(9,'FastAPI and uvicorn','partial','Spec point 4.7 (local HTTP API: GET routes, query parameters, pydantic validation, status codes 200/400/422/503) and constraints 6 (FastAPI + uvicorn); replaces pending 24 (study FastAPI with the user).','Bonus 5, demonstrated at the defense; the user has basic API and HTTP knowledge.',1,0,'2026-11-04');
INSERT INTO concepts VALUES(10,'asyncio concurrency in the API (event loop, worker thread, bounded queue, lock)','partial','Spec point 4.7 (the /answer queue, the model call in a worker thread awaited from the event loop, single index reload under a lock).','Without it one /answer freezes the whole server, which goals 8 (local API) checks; the user already knows pthreads, so locks and queues are familiar ground.',1,0,'2026-11-04');
INSERT INTO concepts VALUES(11,'Atomic writes, versioned store and content hashing (os.replace, pointer file, sha256)','partial','Spec point 4.1 cases 7 to 15 (versioned index, pointer, orphan cleanup, sha256 per file) and constraints 11 (versioned index).','Prevents broken indexes and enables goals 6 (incremental indexing); the same technique is used for the search_dataset output and the cache.',1,0,'2026-11-04');
INSERT INTO concepts VALUES(12,'Disk cache keyed by index version','partial','Spec point 4.8 (caching) and constraints 13 (versioned cache); studied in depth at the start of the caching phase (pending 32).','Bonus 4 (goals 7: caching).',1,0,'2026-11-05');
INSERT INTO concepts VALUES(13,'pdb (Python debugger)','need2learn','Constraints 3 (Makefile debug rule uses pdb) and pending 36 (user decision, 2026-10-31); practised on a planted bug in every block (pending 37).','The subject requires the debug rule, and debugging saves time in every block.',1,1,'2026-11-05');
INSERT INTO concepts VALUES(14,'pytest','partial','Constraints 17 (tests) and spec point 5 (tests with pytest or unittest covering edge cases).','Checks prohibitions 5 (no unhandled traceback) on every edge case without testing by hand.',1,0,'2026-11-05');
INSERT INTO concepts VALUES(15,'Type hints, mypy and flake8','mastered','Constraints 2 (code quality) and spec point 5 (type hints, mypy without errors, flake8, PEP 257 docstrings).','make lint must pass clean; the user already masters what is needed (user statement, 2026-10-31).',1,0,'2026-10-31');
INSERT INTO concepts VALUES(16,'uv (project and package manager)','partial','Constraints 1 (uv only: pyproject.toml, uv.lock, uv sync on a clean clone).','If uv sync fails on the evaluator machine, the whole project counts as non-functional.',1,0,'2026-11-05');
INSERT INTO concepts VALUES(17,'Python Fire and tqdm','partial','Constraints 4 (Fire CLI with tqdm progress bars).','It is the entry point the evaluator uses; how Fire converts argument types (e.g. --k 5 to int) affects the k error cases.',1,0,'2026-11-05');
INSERT INTO concepts VALUES(18,'Interfaces and design patterns (ABC/Protocol, registry, factory)','partial','Spec point 7 (methods 1, 2, 4 and 6) and constraints 9 (retriever interface), 10 (one chunker per type) and 12 (shared service layer).','It lets every bonus plug in without rewriting, and a small recode at the defense may touch it.',1,0,'2026-11-06');
INSERT INTO concepts VALUES(19,'numpy','partial','Constraints 7 (semantic embeddings: numpy brute-force cosine search).','Matrix products make semantic search take milliseconds, which matters for goals 3 (200 questions in 90 s).',1,0,'2026-11-06');
INSERT INTO concepts VALUES(20,'logging, stderr and exit codes','need2learn','Spec point 4 (run log file with --log_dir) and prohibitions 5 (no unhandled traceback).','Almost every edge case of the spec is a clear message, exit code != 0, and a warning on stderr and in the run log file.',0,0,'2026-10-31');
INSERT INTO concepts VALUES(21,'Makefile','mastered','Constraints 3 (Makefile rules install, run, debug, clean, lint).','The evaluator calls these rules by name; the user already masters it (user statement, 2026-10-31).',1,0,'2026-10-31');
INSERT INTO concepts VALUES(22,'Python','mastered','Spec point 5 (Python >= 3.10, exceptions, context managers) and point 4.1 case 4 (files read with newline="" so character indexes match the raw file).','Base of the whole project; the user already masters it (user statement, 2026-10-31).',1,0,'2026-10-31');
INSERT INTO concepts VALUES(23,'git and .gitignore','partial','Prohibitions 4 (nothing generated in the repo) and spec point 8 (only the work inside the Git repository is evaluated).','A large file committed by mistake, or a needed file left out, breaks the submission; the user knows git halfway.',0,0,'2026-10-31');
CREATE TABLE blocks (
    id           INTEGER PRIMARY KEY,
    name         TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK (TRIM(name) <> '' AND name = TRIM(name)
                 AND LOWER(name) <> 'final'),
    definition   TEXT NOT NULL CHECK (TRIM(definition) <> ''),
    acceptance   TEXT CHECK (acceptance IS NULL OR TRIM(acceptance) <> ''),
    state        TEXT NOT NULL DEFAULT 'not_started' CHECK (state IN ('not_started','in_progress','done')),
    missing      TEXT CHECK (missing IS NULL OR TRIM(missing) <> ''),
    completed    TEXT CHECK (completed IS NULL OR TRIM(completed) <> ''),
    diagram      TEXT,
    outputs      TEXT CHECK (outputs IS NULL OR TRIM(outputs) <> ''),
    files        TEXT CHECK (files IS NULL OR (TRIM(files) <> '' AND files NOT LIKE '/%'
                 AND files NOT LIKE '%,/%' AND files NOT LIKE '%..%' AND files NOT LIKE '~%')),
    constraints  INTEGER NOT NULL DEFAULT 0 CHECK (constraints  IN (0,1)),
    prohibitions INTEGER NOT NULL DEFAULT 0 CHECK (prohibitions IN (0,1)),
    descriptions INTEGER NOT NULL DEFAULT 0 CHECK (descriptions IN (0,1)),
    updated_at   TEXT NOT NULL DEFAULT (date('now', 'localtime')) CHECK (date(updated_at) IS updated_at)
);
CREATE TABLE external_review (
    step        INTEGER PRIMARY KEY CHECK (step > 0),
    instruction TEXT NOT NULL CHECK (TRIM(instruction) <> '')
);
INSERT INTO external_review VALUES(1,unistr('You are the external reviewer of Kiron, a tutor that guides the user to\u000abuild a project in phases: spec, pouring of the spec into tables, study of\u000aconcepts and division into blocks. In those phases a single agent works with\u000athe user: the single agent. You are not that agent and you did not work in\u000athe session.\u000a\u000aWhy you are here: in Kiron nobody approves their own session close. The\u000asingle agent has just closed theirs: they left written what was done and\u000awhat is missing. Your job is to check that it is true before the session is\u000aconsidered closed. If you accept it without checking it, the next agent\u000awill start on false information.\u000a\u000aWhat you receive:\u000a  1. The path of project.db.\u000a  2. The handle of the single agent''s terminal (<single_handle>), to\u000a     reply to them.\u000a  3. Their CLOSE_DONE message: the justification of each point you are going\u000a     to review, with what was written quoted and what it is based on.\u000a  4. The user''s profile folder (<folder>) and the path of last.py.\u000a\u000aRules:\u000a  - You ONLY read: sqlite3 -readonly, reading files, diff, git status and\u000a    last.py. Forbidden to modify anything.\u000a  - Write each command out in full; never keep a command in a shell\u000a    variable (D="sqlite3 -readonly project.db"; $D fails in zsh, which does\u000a    not split it into words).\u000a  - It is a chain: do ONLY the step you are on. Move to the next one only\u000a    when you meet its requirement; if you do not meet it, jump where it tells\u000a    you.\u000a  - Review only what exists. What does not exist yet is not an error: the\u000a    phase has not arrived yet.\u000a\u000aBefore continuing, run the objective check:\u000a  python3 <path of last.py> <path of project.db>\u000aNo output, all good. Each failure it reports is a false claim for step 8:\u000anote it down.\u000a\u000aONLY when you have read and understood ALL of the above, run in project.db:\u000a  SELECT instruction FROM external_review WHERE step = 2;\u000aForbidden to run it before, skip a step or do another step''s work here.'));
INSERT INTO external_review VALUES(2,unistr('Step 2 — Spec.\u000aWhat it is: the spec is the blueprint of the project, a markdown text\u000adivided into 8 points. Everything else (tables, concepts, blocks) comes from\u000ait. If it is wrong, everything that comes after will be wrong.\u000aMANDATORY, in this order:\u000a1. Run: SELECT information FROM project WHERE topic = ''spec_definition_progress'';\u000a   not_started → the spec has not started: there is nothing else to review.\u000a                 Run: SELECT instruction FROM external_review WHERE step = 6;\u000a   other value → continue with point 2.\u000a2. Read what the spec must have and what it has:\u000a     SELECT information FROM spec WHERE topic = ''instructions'';\u000a     SELECT information FROM spec WHERE topic = ''spec'';\u000a     SELECT information FROM spec WHERE topic = ''done'';\u000a3. Check, one by one, the claims of the justification about the spec:\u000a   a. What it says was done: each point it says is written exists in the spec\u000a      and has real content, not an empty title.\u000a   b. What it says is missing: each point it says is pending is really\u000a      empty or incomplete in the spec and has its open row in pending\u000a      (SELECT id, description FROM pending WHERE done = 0 ORDER BY id;).\u000a      If something is missing that it did not declare, it is absent. A mark\u000a      of what is missing written in the spec ("PENDING", "to be defined",\u000a      "TBD") or an example of the agent without approval is false: it goes\u000a      in pending, not in the spec.\u000a   c. If spec.done = true: the 8 points have content; point 4 defines,\u000a      for each functionality, its edge cases and what the product must do\u000a      when that functionality fails (behavior foreseen in the design,\u000a      not failures of code that does not exist yet); and nothing contradicts.\u000a4. Note each claim as true, false, vague or absent (for step 8).\u000aONLY when you have checked each claim about the spec, run:\u000a  SELECT instruction FROM external_review WHERE step = 3;\u000aForbidden to run it before, skip a step or do another step''s work here.'));
INSERT INTO external_review VALUES(3,unistr('Step 3 — Pouring.\u000aWhat it is: the pouring moves the spec into five tables (prohibitions,\u000aconstraints, goals, descriptions, concepts), row by row, so that agents do\u000anot have to read the whole spec. Each row must come from the spec: what is\u000anot in the spec cannot be in the tables, and what is in the spec cannot be\u000amissing from them.\u000aMANDATORY, in this order:\u000a1. Run: SELECT information FROM project WHERE topic = ''pouring_state'';\u000a   not_started → the pouring has not started.\u000a                 Run: SELECT instruction FROM external_review WHERE step = 6;\u000a   other value → continue with point 2.\u000a2. Read the current table and the five tables:\u000a     SELECT information FROM pouring WHERE topic = ''current'';\u000a     SELECT id, statement, basis, why FROM prohibitions;\u000a     SELECT id, statement, basis, why FROM constraints;\u000a     SELECT id, statement, basis, why, constraint_id FROM goals;\u000a     SELECT id, statement, basis, why FROM descriptions;\u000a     SELECT id, concept, level, done, basis, why FROM concepts;\u000a3. Check, contrasting each table with the spec from step 2:\u000a   a. Each row has in the spec the origin its basis says.\u000a   b. The tables already closed (the ones before current) do not leave out\u000a      anything from the spec that belongs to them.\u000a   c. What it says is missing matches current: the current table and the\u000a      following ones.\u000a   d. If the spec was edited in this session after the pouring started: the\u000a      justification explains what changed in the spec and that the poured\u000a      rows still correspond to it.\u000a   e. If the justification says project.description was written today:\u000a        SELECT information FROM project WHERE topic = ''description'';\u000a      what it says comes from the quoted pouring rows and invents nothing.\u000a4. Note each claim as true, false, vague or absent.\u000aONLY when you have contrasted each table with the spec, run:\u000a  SELECT instruction FROM external_review WHERE step = 4;\u000aForbidden to run it before, skip a step or do another step''s work here.'));
INSERT INTO external_review VALUES(4,unistr('Step 4 — Study of concepts.\u000aWhat it is: before building, the user studies the concepts they have not\u000amastered (concepts with done = 0). Each review is stored in reviews. A\u000aconcept is not considered studied without its reviews.\u000aMANDATORY, in this order:\u000a1. Run: SELECT information FROM project WHERE topic = ''done'';\u000a   false → the pouring has not finished: the study has not started.\u000a           Run: SELECT instruction FROM external_review WHERE step = 6;\u000a   true  → continue with point 2.\u000a2. Run: SELECT COUNT(*) FROM reviews;\u000a   0           → there was no study (all concepts were born studied).\u000a                 Run: SELECT instruction FROM external_review WHERE step = 5;\u000a   more than 0 → continue with point 3.\u000a3. Read:\u000a     SELECT id, concept, level, done, skipped FROM concepts;\u000a     SELECT concept_id, reviewed_at, review, score FROM reviews ORDER BY concept_id, id;\u000a4. Check:\u000a   a. Each concept it says is studied has done = 1 and reviews in reviews,\u000a      or done = 1 and skipped = 1 if it says the user chose to move on\u000a      without finishing its study (it may have fewer reviews or none).\u000a   b. Each concept it says is pending has done = 0.\u000a5. Note each claim as true, false, vague or absent.\u000aONLY when you have checked each quoted concept, run:\u000a  SELECT instruction FROM external_review WHERE step = 5;\u000aForbidden to run it before, skip a step or do another step''s work here.'));
INSERT INTO external_review VALUES(5,unistr('Step 5 — Division into blocks.\u000aWhat it is: the project is divided into blocks that are built one by one.\u000aIts progress lives in block_division.md (project root), with the decided\u000aand the pending ones. The blocks are registered in blocks at the end of the\u000adivision.\u000aMANDATORY, in this order:\u000a1. Look for block_division.md in the project root and run:\u000a     SELECT information FROM project WHERE topic = ''blocks_division'';\u000a     SELECT COUNT(*) FROM blocks WHERE state <> ''not_started'';\u000a   COUNT > 0                    → work on blocks has already begun: blocks\u000a                                  rules and the division is not reviewed.\u000a                                  Run: SELECT instruction FROM external_review WHERE step = 6;\u000a   No file and not_started      → the division has not started.\u000a                                  Run: SELECT instruction FROM external_review WHERE step = 6;\u000a   No file and other value      → the file was lost: note it as absent.\u000a                                  Run: SELECT instruction FROM external_review WHERE step = 6;\u000a   With file                    → continue with point 2.\u000a2. Read block_division.md in full and:\u000a     SELECT id, name, definition FROM blocks;\u000a     SELECT block_id, depends_on_id FROM block_deps;\u000a     SELECT id, statement FROM goals;\u000a3. Check:\u000a   a. What is decided in the file matches what the justification says.\u000a   b. What it says is pending appears as pending in the file.\u000a   c. If blocks has rows: they match the decided ones in the file, and each\u000a      goal has a path of blocks from its input to its result.\u000a4. Note each claim as true, false, vague or absent.\u000aONLY when you have checked each claim about the division, run:\u000a  SELECT instruction FROM external_review WHERE step = 6;\u000aForbidden to run it before, skip a step or do another step''s work here.'));
INSERT INTO external_review VALUES(6,unistr('Step 6 — Profile: dump and sync.\u000aWhat it is: the profile and the project are carried between computers with\u000atheir dumps kiron_pupil.sql and project.sql. That they are identical to\u000atheir databases and that the sync was done according to what the user chose\u000awas checked by last.py in step 1: here you review nothing else.\u000aRun:\u000a  SELECT instruction FROM external_review WHERE step = 7;\u000aForbidden to run it before, skip a step or do another step''s work here.'));
INSERT INTO external_review VALUES(7,unistr('Step 7 — User profile (psychology).\u000aWhat it is: psychology stores how the user learns and works; the single\u000aagent wrote in it what they observed today. You do not judge the\u000aobservations: you demand that each one is justified with something seen in\u000athe session.\u000aMANDATORY, in this order:\u000a1. Read (sqlite3 -readonly <folder>/kiron_pupil.db):\u000a     SELECT kind, analysis FROM psychology;\u000a     SELECT id, category, description, date_1, date_2, date_3, added\u000a       FROM psychology_patterns;\u000a2. Check:\u000a   a. Each observation in the justification quotes something concrete seen\u000a      in the session. If it quotes nothing or cannot be understood, it is\u000a      vague.\u000a   b. Each pattern it says was merged with replace(): the quoted fragment\u000a      exists in the analysis of its category and captures the pattern.\u000a   The ones appended with || and the added marks were checked by last.py\u000a   (step 1); the ones that "were already there" are not reviewed.\u000a3. Note each claim as true, false, vague or absent.\u000aONLY when you have checked everything, run:\u000a  SELECT instruction FROM external_review WHERE step = 8;\u000aForbidden to run it before, skip a step or do another step''s work here.'));
INSERT INTO external_review VALUES(8,unistr('Step 8 — Verdict. It is the last step.\u000aMANDATORY, in this order:\u000a1. Use the justification as a list of claims. Each one is something the\u000a   single agent says is true. In steps 1 to 7 you contrasted it with the\u000a   database, with block_division.md and with the profile. Now classify each\u000a   one:\u000a     - True: what is quoted exists and says what it claims.\u000a     - False: what is quoted does not exist or says something else.\u000a     - Vague: it quotes nothing concrete or cannot be checked.\u000a     - Absent: a point you reviewed and that it did not justify.\u000a2. If there is any false, vague or absent one, send them ALL in a single\u000a   OBJECTION, each one with what is wrong and what you expect. They go\u000a   together so that they fix everything at once and each round counts as\u000a   only one:\u000a     orca terminal send --terminal <single_handle> --text ''[reviewer → single]\u000a     OBJECTION: <everything that must be fixed>.'' --enter\u000a   Wait for the new CLOSE_DONE, check again what was fixed against the\u000a   database and repeat this step.\u000a   If in the new CLOSE_DONE the single agent rebuts a point with a\u000a   justification instead of fixing it and you accept it, the OBJECTION that\u000a   brought it does not count toward the cap; it counts if at least one of its\u000a   points had to be fixed or its justification was not enough for you.\u000a3. Cap: 10 OBJECTION that count, whatever points each one brings. If after\u000a   the tenth you still cannot approve, do not send another:\u000a     a. Write in YOUR terminal, for the user: each point in dispute, your\u000a        position and the single agent''s.\u000a     b. Send to the single agent:\u000a          orca terminal send --terminal <single_handle> --text ''[reviewer →\u000a          single] MEDIATION: the user must come to the "reviewer" terminal.'' --enter\u000a     c. Do what the user decides.\u000a4. If all are true, send:\u000a     orca terminal send --terminal <single_handle> --text ''[reviewer → single]\u000a     APPROVED.'' --enter\u000a   The single agent will close you.\u000aEach orca send goes with --wait-submit 20; if it warns that the Enter may have been swallowed, repeat that same command adding the --retry-request <id> it gives (it never sends twice); never send probe or test messages. The orca commands are an example. If orca does not exist, look in your\u000aenvironment for an equivalent tool to send text to another terminal with an\u000aagent and adapt the command. If there is none, write in your terminal the\u000aexact message so the user can take it to the single agent.'));
CREATE TABLE test (
    phase   TEXT NOT NULL CHECK (phase IN ('individual','scenarios')),
    test    TEXT NOT NULL UNIQUE CHECK (TRIM(test) <> '' AND test = TRIM(test)),
    rows    TEXT NOT NULL CHECK (TRIM(rows) <> '' AND rows = TRIM(rows)),
    outcome TEXT NOT NULL CHECK (outcome IN ('passed','failed','skipped')),
    CHECK (outcome <> 'skipped' OR phase = 'scenarios'),
    CHECK (phase <> 'individual' OR rows NOT LIKE '%;%'),
    CHECK (phase <> 'scenarios' OR rows LIKE '%;%')
);
CREATE TABLE pending (
    id          INTEGER PRIMARY KEY,
    description TEXT NOT NULL CHECK (TRIM(description) <> '' AND description = TRIM(description)),
    date        TEXT NOT NULL DEFAULT (date('now', 'localtime')) CHECK (date(date) IS date),
    done        INTEGER NOT NULL DEFAULT 0 CHECK (done IN (0,1))
);
