INSERT INTO pending VALUES(8,'Check after the mandatory part is complete (user decision, 2026-10-28): how viable Docker and a small frontend are as an optional way to run the local HTTP API (technically viable: inside the container the server binds 0.0.0.0 and the port is published only on the host 127.0.0.1, e.g. docker run -p 127.0.0.1:8000:8000; model weights and data mounted as volumes). Verify whether Docker is available without root on the campus machines; the evaluator only runs uv sync, so Docker can never be required. Must meet prohibitions 6 (API reachable only from 127.0.0.1 of the host): Docker kept as a separate solution, checked with docker port (user decision, 2026-10-31)','2026-10-26',0);
INSERT INTO pending VALUES(9,'Define in spec point 4.3: where the run log file is written (it records skipped questions and retrieval-method fallbacks and errors), as a CLI argument since no path is hard-coded (proposed, not approved: --log_path, defaulting to a file inside --save_directory)','2026-10-28',1);
INSERT INTO pending VALUES(10,'Start next session by having the user explain in their own words the index → search flow (toy index over lora.md: chunking, word counts saved to disk, search loads the index and scores chunks, overlap with the correct source), then correct what is missing; the user asked to go deeper into it','2026-10-28',1);
INSERT INTO pending VALUES(11,'Measure in the indexing phase (rule in spec point 4.1 case 4): run evaluate and the moulinette on the same search_dataset output and compare recall@k; if they differ, check the 4 corpus files that contain \r. Also confirms the IoU threshold: the spec uses IoU > 0.05 (strict); if evaluate and the moulinette differ only on sources with IoU exactly 0.05, switch to >= (user decision, 2026-10-31)','2026-10-27',0);
INSERT INTO pending VALUES(12,'Define in spec point 6: the user decided (2026-10-28) to implement all 5 bonuses (semantic embeddings, hybrid retrieval, incremental indexing, caching, local HTTP API); turn them from directions into committed functionalities and reflect them in points 1, 4 (new edge cases), 5 and 7','2026-10-28',1);
INSERT INTO pending VALUES(13,'Define in spec point 4: how retrieval modes are exposed in search, search_dataset and answer (proposed, not approved: --method bm25|semantic|hybrid, default chosen by measured recall@k; hybrid fusion with Reciprocal Rank Fusion)','2026-10-28',1);
