INSERT INTO pending VALUES(15,'Define in spec point 4: caching, what is cached and when it is invalidated (proposed, not approved: query results cached on disk keyed by query, k, method and index version; a new index version invalidates them)','2026-10-28',1);
INSERT INTO pending VALUES(16,'Define in spec point 4.7: whether the local HTTP API is bound to 127.0.0.1 only (proposed, not approved: yes; any other address lets anyone on the network use the CPU through /answer and fill the queue, and the API has no authentication)','2026-10-28',1);
INSERT INTO pending VALUES(17,'Measure in the semantic index phase (rule in spec point 5, semantic embeddings): try both fastembed and sentence-transformers with all-MiniLM-L6-v2 and measure simply and practically install size and uv sync time, time to embed the whole corpus on CPU (5-minute goal), recall@5 on docs and code, model load time in the API server and working offline once cached; then decide with the user from those numbers. Expected same behaviour and recall, so lightness and speed should decide','2026-10-28',0);
