INSERT INTO pending VALUES(23,'Test in the search_dataset phase (rule in spec point 4.3 case 7): run the moulinette by hand on an output where the duplicated questions were skipped; if it rejects it, stop and decide with the user','2026-10-28',0);
INSERT INTO pending VALUES(24,'Study FastAPI with the user (HTTP methods, routes, query parameters, pydantic validation, status codes, uvicorn) before defining spec point 4 for the local HTTP API (pending 16). Moved to the concept study as concepts row FastAPI and uvicorn (2026-10-31)','2026-10-31',1);
INSERT INTO pending VALUES(25,'Define in spec point 4.7: the maximum size of the /answer queue, as max waiting = W / T, where T is the measured time of one answer of Qwen3-0.6B on CPU and W the longest wait accepted (user decision); beyond it the request gets 503 with a clear message. Also decide whether the model call runs in a worker thread so a generation in progress does not freeze /search and /health (proposed, not approved: yes)','2026-10-28',1);
