INSERT INTO pending VALUES(27,'Define in spec point 4.4: the safety net when the context does not fit and the split hypothesis (case 8) is not in use, e.g. a user running answer with a very large k (proposed, not approved: keep the sources in ranking order up to the budget and report on stderr and in the run log how many were used)','2026-10-28',1);
INSERT INTO pending VALUES(28,'Start next session with spec point 4.5 (pending 4, edge cases of answer_dataset), then 4.6 (pending 5); then the /health model (26), study of semantic embeddings and incremental indexing (22) to define 4.1 (14), embedding libraries (17) and the 5-minute indexing goal (18); point 7 (6); whitelist (7) and character ranges (11); moulinette test of duplicate ids (23); FastAPI study (24) before implementing the API','2026-10-29',1);
INSERT INTO pending VALUES(29,'Measure in the chunking phase (rule in spec point 4.1, chunk size rule): recall@5 on docs and code for chunk sizes 2000, 1500, 1000 and 500 and for the structural split (one chunk per function, class or section, no merging); keep the highest sum and report all in the README. Extra candidate (user decision, 2026-11-02), compared against the structural split that breaks oversized .md sections by paragraphs, and kept only if it improves recall@5 and meets the 5-minute goal: .py and .txt always structural; .md structural by sections, and only a section above n with the embedding model available gets a semantic cut, applied to prose only. Code and tables are cut by lines or rows without breaking a block, and a table that fits in n stays whole. Without the model, oversized sections are split by paragraphs. A piece still above n is cut at the last full stop before n, or at exactly n if there is none. The index version stores a setting oversized_md_cut (paragraphs or semantic); if it differs from what can be done in the next run, full rebuild with nothing reused (hash match does not reuse). If this candidate wins, update spec point 4.1 cases 11 and 13 then.','2026-10-29',0);
INSERT INTO pending VALUES(30,'Explain to the user at the start of the chunking phase (user decision, 2026-10-29): what the indexed corpus files contain (1763 .py, 178 .md, 28 .txt of vllm-0.10.1) and how important each group is for the evaluation, summarised by folder and file type with real examples, so the user does not have to read them one by one','2026-10-29',0);
INSERT INTO pending VALUES(31,'Measure in the API phase (rule in spec point 4.7, index version in the server): time of loading one index version into the server; if it exceeds 2 seconds, add a background task that reads the pointer every n seconds and loads the new version before any request arrives (user decision, 2026-10-29)','2026-10-29',0);
INSERT INTO pending VALUES(32,'Study with the user at the start of the caching phase (rule in spec point 7, item 5): how the cache keyed by index version, method, query and k works and what it stores, before implementing it; include deleting the entries of index versions that no longer exist (spec point 4.8)','2026-10-29',0);
INSERT INTO pending VALUES(33,'Measure in the search_dataset phase and again in the hybrid retrieval phase (rule in spec point 3, goal 3): time of search_dataset on 200 questions; if it exceeds 90 seconds, stop and decide with the user','2026-10-29',0);
INSERT INTO pending VALUES(34,'Measure in the semantic index phase (rule in spec point 5, semantic embeddings): share of chunks above 256 tokens and recall@5 on docs and code of truncation versus one vector per 256-token window (chunk scored by its best window); decide with the user','2026-10-29',0);
INSERT INTO pending VALUES(35,'Resume the pouring at table prohibitions (pouring.current = prohibitions, no row added yet): proposed, not approved, waiting for the user: x1 never imports or calls the moulinette (basis 8, 4.6); x2 no source wider than 2000 characters, max_chunk_size above 2000 rejected (8, 4.1); x3 no hard-coded input/output paths, all are CLI arguments with defaults allowed (8, 4); x4 no data, model weights, index, generated outputs or logs committed, all in .gitignore (8); x5 no unhandled traceback on any input, clear message and exit code != 0 (8, 3 goal 5); x6 the API never listens on an address other than 127.0.0.1 (4.7, no authentication); x7 no code in the repo the user cannot explain and justify at the defense (8, subject chapter III). "Must keep working with Qwen3-0.6B" and "uv only" go to constraints, not prohibitions. Note: project.pouring_state is spec_edited (the close edited spec points 4.7, 4.8 and 4.9 with user approval); at resume, follow first the spec_edited branch of row 1 of workflow (verify the pouring against the new spec; the five tables have 0 rows) before continuing prohibitions','2026-10-31',1);
